/// * `df0` - The input DataFrame
/// * `var0` - The name of the date column to filter on
/// * `date0` - The start date (inclusive) as a string (e.g., "2023-01-01")
/// * `date1` - The end date (inclusive) as a string (e.g., "2023-12-31")
///
/// # Returns
/// A filtered DataFrame containing only rows where var0 is between date0 and date1
pub async fn filter_by_date_range(
    ctx: &SessionContext,
    df0: DataFrame,
    var0: &str,
    date0: &str,
    date1: &str,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Register the dataframe as a temporary table
    df0.register_temporary_table("temp_table")?;

    // Execute SQL query with date range filter
    let query = format!(
        "SELECT * FROM temp_table WHERE \"{}\" >= '{}' AND \"{}\" <= '{}'",
        var0, date0, var0, date1
    );

    let result = ctx.sql(&query).await?;
    Ok(result)
}

