/// * `col1` - Name of the column to use as source (0-based index)
///
/// # Returns
/// Result containing the modified CSV data as a string, or an error
pub fn fill_missing_entries(data0: &str, col0: usize, col1: usize) -> Result<String, Box<dyn Error>> {
    // Create a cursor around the input data
    let mut rdr = ReaderBuilder::new()
        .has_headers(true)
        .from_reader(Cursor::new(data0.as_bytes()));

    // Read headers to get column names
    let headers = rdr.headers()?.clone();

    // Verify columns exist
    if col0 >= headers.len() || col1 >= headers.len() {
        return Err("Column index out of bounds".into());
    }

    // Collect all records
    let mut records = Vec::new();
    for result in rdr.records() {
        let record = result?;
        records.push(record);
    }

    // Process each record
    for record in &mut records {
        let col0_index = col0;
        let col1_index = col1;

        // Check if col0 value is empty and col1 has a value
        if record[col0_index].is_empty() && !record[col1_index].is_empty() {
            record[col0_index] = record[col1_index].clone();
