/// Replace all missing entries in col0 with corresponding entries from col1
/// 
/// # Arguments
/// * `data0` - CSV data as a string
/// * `col0` - Name of the column with missing entries to fill
/// * `col1` - Name of the column to use as replacement source
/// 
/// # Returns
/// Modified CSV data as a string
pub fn replace_missing_entries(
    data0: &str,
    col0: &str,
    col1: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    // Parse the input CSV
    let mut reader = Reader::from_reader(data0.as_bytes());
    let headers = reader.headers()?.clone();

    // Find column indices
    let col0_idx = headers
        .iter()
        .position(|h| h == col0)
        .ok_or(format!("Column '{}' not found", col0))?;

    let col1_idx = headers
        .iter()
        .position(|h| h == col1)
        .ok_or(format!("Column '{}' not found", col1))?;

    // Collect and process records
    let mut output = Vec::new();
    {
        let mut writer = Writer::from_writer(&mut output);
        writer.write_record(&headers)?;

        for result in reader.records() {
            let mut record = result?;

            // If col0 is empty, replace with col1 value
            if record[col0_idx].trim().is_empty() && col1_idx < record.len() {
                record[col0_idx] = record[col1_idx].to_string();
            }

            writer.write_record(&record)?;
        }

        writer.flush()?;
    }

    Ok(String::from_utf8(output)?)
}

#[cfg(test)]
