    // Get the shape of the input array
    let shape = arr0.shape();

    // Create a new shape by reducing the dimension `var1` by (shape[var1] / var0)
    let new_shape = {
        let mut new_shape = shape.to_vec();
        new_shape[var1] = new_shape[var1] / var0;
        new_shape
    };

    // Create a new array with the new shape
    let mut new_arr = Array::zeros(new_shape);

    // Iterate over all dimensions except var1
    let mut indices = (0..arr0.ndim()).collect::<Vec<_>>();
    indices.remove(var1); // Remove the dimension we're modifying

