extern crate ndarray;

use ndarray::{Array, Axis};

/// Deletes elements from an array along the specified dimension, removing every nth element.
///
/// # Arguments
///
/// * `arr0`: The input array.
/// * `var0`: The interval at which elements are removed.
/// * `var1`: The dimension along which elements are removed.
///
/// # Returns
///
/// A new array with the elements removed.
fn delete_elements(arr0: Array<f64, _>, var0: usize, var1: usize) -> Array<f64, _> {
