use rayon::prelude::*;
use std::collections::HashMap;

/// Given an input mapping with keys "key1" and "key2", each associated with
/// a Vec<T> of equal length, produce a Vec of HashMaps where each HashMap
/// has "key1" and "key2" set to the corresponding elements at that index.
///
/// T must be Clone + Send + Sync so we can safely process the data in parallel.
pub fn zip_map_pairs<T>(
    input: &HashMap<String, Vec<T>>,
) -> Result<Vec<HashMap<String, T>>, String>
where
    T: Clone + Send + Sync + 'static,
{
    let a = input
        .get("key1")
        .ok_or_else(|| "input missing key \"key1\"".to_string())?;
    let b = input
        .get("key2")
        .ok_or_else(|| "input missing key \"key2\"".to_string())?;

    if a.len() != b.len() {
        return Err("sequences for \"key1\" and \"key2\" must have equal length".to_string());
    }

    // Use Rayon to zip and map in parallel.
    let out: Vec<HashMap<String, T>> = a
        .par_iter()
        .cloned()
        .zip(b.par_iter().cloned())
        .map(|(v1, v2)| {
            let mut m = HashMap::with_capacity(2);
            m.insert("key1".to_string(), v1);
            m.insert("key2".to_string(), v2);
            m
        })
        .collect();

    Ok(out)
}

fn main() {
    // Example usage
    let mut input: HashMap<String, Vec<i32>> = HashMap::new();
    input.insert("key1".to_string(), vec![1, 2, 3]);
    input.insert("key2".to_string(), vec![10, 20, 30]);

