        Ok(result) => {
            for (i, map) in result.into_iter().enumerate() {
                println!("item {}: key1 = {}, key2 = {}", i, map["key1"], map["key2"]);
            }
        }
        Err(e) => eprintln!("error: {}", e),
    }
}
```

Notes:
