use rayon::prelude::*;
use std::collections::HashMap;

/// Given a HashMap with sequences of equal length, produces a Vec of HashMaps
/// where each mapping contains elements at the same position from the input sequences.
///
/// # Arguments
/// * `input` - A HashMap with keys "key1" and "key2", each mapped to a Vec<String>
///
/// # Returns
/// A Vec of HashMaps, where each HashMap has "key1" and "key2" with corresponding values
///
/// # Example
/// ```
/// let mut input = HashMap::new();
/// input.insert("key1".to_string(), vec!["a".to_string(), "b".to_string()]);
/// input.insert("key2".to_string(), vec!["x".to_string(), "y".to_string()]);
/// 
/// let result = zip_sequences_to_mappings(input);
/// // result[0] = {"key1": "a", "key2": "x"}
/// // result[1] = {"key1": "b", "key2": "y"}
/// ```
fn zip_sequences_to_mappings(
    input: HashMap<String, Vec<String>>,
) -> Vec<HashMap<String, String>> {
    // Get sequences for key1 and key2
    let seq1 = input
        .get("key1")
        .cloned()
        .unwrap_or_default();
    let seq2 = input
        .get("key2")
        .cloned()
        .unwrap_or_default();

    // Ensure sequences have equal length
    let len = seq1.len().min(seq2.len());

    // Use Rayon to parallelize the mapping creation
    (0..len)
        .into_par_iter()
        .map(|i| {
            let mut mapping = HashMap::new();
            mapping.insert("key1".to_string(), seq1[i].clone());
            mapping.insert("key2".to_string(), seq2[i].clone());
            mapping
        })
        .collect()
}

fn main() {
    // Example usage
    let mut input = HashMap::new();
    input.insert(
        "key1".to_string(),
        vec!["apple".to_string(), "banana".to_string(), "cherry".to_string()],
    );
    input.insert(
        "key2".to_string(),
        vec!["red".to_string(), "yellow".to_string(), "red".to_string()],
    );

    let result = zip_sequences_to_mappings(input);

    println!("Result:");
    for (i, mapping) in result.iter().enumerate() {
        println!(
            "  [{}] key1: {}, key2: {}",
            i,
            mapping.get("key1").unwrap(),
            mapping.get("key2").unwrap()
        );
    }
}
