/// Recursively count key-value pairs in a serde_json::Value produced from TOML.
/// - For objects (tables) we count the number of keys and then descend into values.
/// - For arrays we descend into each element (to handle arrays of tables).
/// - Other scalar types contribute 0.
fn count_in_value(v: &JsonValue) -> usize {
    match v {
        JsonValue::Object(map) => {
            let mut count = map.len();
            for val in map.values() {
                count += count_in_value(val);
            }
            count
        }
        JsonValue::Array(arr) => arr.iter().map(count_in_value).sum(),
        _ => 0,
    }
}

/// Parse the given TOML text with tomlet and return the total number of key-value pairs
/// (including nested ones). Returns an Err if parsing fails.
pub fn count_toml_kv_pairs(toml_text: &str) -> Result<usize, Box<dyn std::error::Error>> {
    // Deserialize TOML into a serde_json::Value using tomlet's serde support.
    let value: JsonValue = de::from_str(toml_text)?;
    Ok(count_in_value(&value))
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let toml = r#"
        title = "Example"

        [owner]
        name = "Alice"
        age = 30

        [database]
        server = "192.168.1.1"

        [[products]]
        name = "prod1"
        price = 10

        [[products]]
        name = "prod2"
        price = 20
    "#;

    let total = count_toml_kv_pairs(toml)?;
    println!("Total key-value pairs: {}", total);
    // For the example above:
    // top-level: title, owner (table), database (table), products (array) => top-level keys = 4
    // owner: name, age => 2
    // database: server => 1
    // products: two tables each with name, price => 2 * 2 = 4
    // total = 4 + 2 + 1 + 4 = 11
    Ok(())
}
```

Notes:
- The function counts only mapping keys (table entries). Scalar values are not counted except as values paired with keys.
- Arrays are traversed because TOML supports arrays of tables ([[table]]).
- If your tomlet version uses a slightly different module path for deserialization, adapt the `use tomlet::de;` and `de::from_str` call accordingly.

