    // Create a regex automaton for the pattern
    let re = Regex::new(pattern).expect("Invalid regex pattern");
    let automaton = re.compile().expect("Failed to compile regex");

    let mut matches = Vec::new();
    let mut state = automaton.initial_state();
    let input_chars: Vec<char> = input.chars().collect();

    // Iterate through the input string
    for (i, c) in input_chars.iter().enumerate() {
        // Transition the automaton state
        state = automaton.transition(state, *c);

        // Check if we're in an accepting state
        if automaton.is_accepting(state) {
            // Find the start position of this match
