    let mut query = Query::new(df);
    query.group_by(key_columns.iter().map(|c| Column::new(c.to_string())).collect::<Vec<_>>());

    // Add count aggregation
    query.add_aggregation(Aggregation::new(
        "count",
        AggregationType::Count,
        Some(Column::new("*".to_string())),
    ));

    // Execute the query
    let result = db.execute(query)?;

    // Process the results
    let mut counts = HashMap::new();

    for row in result.rows()? {
        // Extract the key values (as strings for simplicity)
        let mut key_values = Vec::with_capacity(key_columns.len());
        for (i, col) in key_columns.iter().enumerate() {
