/// let entries = vec!["apple", "banana", "cherry"];
/// let patterns = vec![r"^b.*", r"^z"];
/// let matched = contains_any_pattern(&entries, &patterns).unwrap();
/// assert_eq!(matched, true); // "banana" matches "^b.*"
/// ```
pub fn contains_any_pattern<I, S>(
    entries: I,
    patterns: &[&str],
) -> Result<bool, Box<dyn Error>>
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    // If there are no patterns, nothing can match.
    if patterns.is_empty() {
        return Ok(false);
    }

    // Compile all patterns into a set for efficient multi-pattern matching.
    // This assumes fancy-lexer exposes a RegexSet-like API. If the actual API differs,
    // adapt the construction below to the crate's types.
    let set = fancy_lexer::RegexSet::new(patterns)
        .map_err(|e| -> Box<dyn Error> { Box::new(e) })?;

    for entry in entries {
        if set.is_match(entry.as_ref()) {
            return Ok(true);
        }
    }

    Ok(false)
