```rust
use arrow::{
    array::{Array, Int64Array},
    datatypes::{DataType, Field, Schema},
    record_batch::RecordBatch,
};
use std::collections::HashMap;

/// Generate a list of lists from a tabular dataset.
///
/// # Arguments
///
/// * `df0` - The input tabular dataset as a RecordBatch.
///
/// # Returns
///
/// A list of lists where each sublist contains a column's name followed by all values in that column.
fn generate_list_of_lists(df0: &RecordBatch) -> Vec<Vec<String>> {
    let mut result: Vec<Vec<String>> = Vec::new();

    // Iterate over each column in the RecordBatch
    for (i, column) in df0.columns().iter().enumerate() {
        let column_name = df0.schema().field(i).name();
        let mut sublist: Vec<String> = Vec::new();

        // Add the column name to the sublist
        sublist.push(column_name.to_string());

        // Convert the column values to strings and add them to the sublist
        match column.data_type() {
            DataType::Int64 => {
                let array = column.as_any().downcast_ref::<Int64Array>().unwrap();
                for value in array.iter() {
