use std::collections::HashMap;
use std::hash::Hash;

/// A simple record type with fields A, B, and C.
/// Generic so it works for many key/value types.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Record<A, B, C> {
    a: A,
    b: B,
    c: C,
}

/// Keep, for each distinct (a, b) pair, the record with the largest c.
/// Returns the surviving records in arbitrary order.
fn keep_max_c_by_ab<A, B, C, I>(records: I) -> Vec<Record<A, B, C>>
where
    A: Eq + Hash + Clone,
    B: Eq + Hash + Clone,
    C: Ord + Clone,
    I: IntoIterator<Item = Record<A, B, C>>,
{
    let mut map: HashMap<(A, B), Record<A, B, C>> = HashMap::new();

    for rec in records {
        let key = (rec.a.clone(), rec.b.clone());
        match map.get_mut(&key) {
            Some(existing) => {
                // Keep the record with the larger C
                if rec.c > existing.c {
                    *existing = rec;
                }
            }
            None => {
                map.insert(key, rec);
            }
        }
    }

    // Return the kept records (order is arbitrary)
    map.into_values().collect()
}

