/// let chunk = Chunk::new(vec![Box::new(array)]);
/// let result = find_row_index(&chunk, &schema, "var0", "banana");
/// assert_eq!(result, Ok(1));
/// ```
pub fn find_row_index(
    df0: &Chunk<Box<dyn Array>>,
    schema: &arrow2::datatypes::Schema,
    var0: &str,
    var1: &str,
) -> Result<usize, String> {
    // Find the column index by name
    let column_index = schema
        .fields
        .iter()
        .position(|field| field.name == var0)
        .ok_or_else(|| format!("Column '{}' not found in schema", var0))?;

    // Get the array for the specified column
    let array = &df0.arrays()[column_index];

    // Match on the data type and search for the value
    match array.data_type() {
        DataType::Utf8 | DataType::LargeUtf8 => {
            let utf8_array = array
                .as_any()
                .downcast_ref::<arrow2::array::Utf8Array<i32>>()
                .ok_or("Failed to downcast to Utf8Array")?;

            for (idx, value) in utf8_array.iter().enumerate() {
                if let Some(v) = value {
                    if v == var1 {
                        return Ok(idx);
                    }
                }
            }

            Err(format!(
                "No entry found in column '{}' with value '{}'",
                var0, var1
            ))
        }
        DataType::Int32 => {
            let int_array = array
                .as_any()
                .downcast_ref::<arrow2::array::PrimitiveArray<i32>>()
                .ok_or("Failed to downcast to Int32Array")?;

            if let Ok(search_val) = var1.parse::<i32>() {
                for (idx, value) in int_array.iter().enumerate() {
                    if let Some(v) = value {
                        if v == &search_val {
                            return Ok(idx);
                        }
                    }
                }
            }

            Err(format!(
                "No entry found in column '{}' with value '{}'",
                var0, var1
            ))
        }
        _ => Err(format!(
            "Unsupported data type: {:?}",
            array.data_type()
        )),
    }
}
