use ndarray::Array1;
use std::collections::HashMap;

/// Assigns ranks to elements in a list. Elements with equal values receive the same rank
/// (average of their positions). The original list order is preserved.
///
/// # Arguments
/// * `lst0` - A slice of f64 values to rank
///
/// # Returns
/// * `Array1<f64>` - Array of rank values corresponding to each element in the input
///
/// # Example
/// ```
/// use ndarray::array;
/// let data = array![3.0, 1.0, 4.0, 1.0, 5.0, 9.0, 2.0, 6.0];
/// let ranks = rank_list(&data);
/// // Ranks: [4.0, 1.5, 5.0, 1.5, 6.0, 8.0, 3.0, 7.0]
/// ```
pub fn rank_list(lst0: &Array1<f64>) -> Array1<f64> {
    let n = lst0.len();
    if n == 0 {
        return Array1::from_vec(vec![]);
    }

    // Create vector of (value, original_index) pairs
    let mut indexed_values: Vec<(f64, usize)> = lst0
        .iter()
        .enumerate()
        .map(|(i, &val)| (val, i))
        .collect();

    // Sort by value (this is the single sort operation)
    indexed_values.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());

    // Initialize result array
    let mut ranks = Array1::<f64>::zeros(n);

    // Process sorted values to assign ranks
    let mut i = 0;
    while i < n {
        let current_value = indexed_values[i].0;
        let mut j = i;

        // Find all elements with the same value
        while j < n && (indexed_values[j].0 - current_value).abs() < f64::EPSILON {
            j += 1;
        }

        // Calculate average rank for tied values
        // Rank starts at 1, so we use (i + 1 + j) / 2.0
        let avg_rank = (i + 1 + j) as f64 / 2.0;

        // Assign the average rank to all tied elements at their original positions
        for k in i..j {
            let original_index = indexed_values[k].1;
            ranks[original_index] = avg_rank;
        }

        i = j;
    }

    ranks
}

