        let items = vec![
            Item { id: 1, name: "one" },
            Item { id: 2, name: "two" },
            Item { id: 3, name: "three" },
            Item { id: 4, name: "four" },
        ];

        // Desired order: 3, 1 (others keep their relative order: 2,4)
        let order = vec![3, 1];

        let map = reorder_items_by_ids(items, order, |it: &Item| it.id);

        // Collect the ids in order to assert
        let ids: Vec<u32> = map.keys().cloned().collect();
        assert_eq!(ids, vec![3, 1, 2, 4]);

        // And the values match their ids
        let names: Vec<&str> = map.values().map(|it| it.name).collect();
        assert_eq!(names, vec!["three", "one", "two", "four"]);
    }
}
```

