    let data: Value = serde_json::from_str(json_data)?;

    // Create a JMESMatch instance and compile the expression
    let matcher = JMESMatch::new(attribute_path)?;

    // Apply the JMESPath expression to extract the values
    let result = matcher.search(&data)?;

    // Convert the result back to a JSON string
    let output = serde_json::to_string(&result)?;

    Ok(output)
}

