use ndarray::{Array2, ArrayView1};

/// Sum the outer products of corresponding pairs of vectors.
///
/// - `xs` and `ys` must have the same number of vectors.
/// - All vectors in `xs` must have the same length (m).
/// - All vectors in `ys` must have the same length (n).
/// Returns an `m x n` Array2<f64> containing the elementwise sum of outer(x_i, y_i).
pub fn sum_outer_products(xs: &[&[f64]], ys: &[&[f64]]) -> Result<Array2<f64>, &'static str> {
    if xs.len() != ys.len() {
        return Err("xs and ys must contain the same number of vectors");
    }
    if xs.is_empty() {
        return Err("input sequences must be non-empty");
    }

    let m = xs[0].len();
    let n = ys[0].len();

    for x in xs {
        if x.len() != m {
            return Err("all vectors in xs must have the same length");
        }
    }
    for y in ys {
        if y.len() != n {
            return Err("all vectors in ys must have the same length");
        }
    }

    let mut sum = Array2::<f64>::zeros((m, n));
    for (x, y) in xs.iter().zip(ys.iter()) {
        let ax: ArrayView1<f64> = ArrayView1::from(*x);
        let ay: ArrayView1<f64> = ArrayView1::from(*y);
        // outer returns an m x n matrix
        sum += &ax.outer(&ay);
    }

    Ok(sum)
}

