use polars::prelude::*;

fn insert_column(df0: &mut DataFrame, var0: usize, var1: &str, var2: Series) -> Result<(), PolarsError> {
    // Check if the column position is valid
    if var0 > df0.width() {
        return Err(PolarsError::ComputeError(format!("Column position {} is out of bounds", var0).into()));
    }

    // Insert the new column at the specified position
    df0.with_column(var2.clone().alias(var1))?;
    let columns = df0.get_columns();
    let mut reordered_columns = Vec::with_capacity(columns.len());

    // Reorder columns to place the new column at the correct position
    for (i, col) in columns.iter().enumerate() {
        if i == var0 {
            reordered_columns.push(Series::new(var1, var2.clone()));
        }
        reordered_columns.push(col.clone());
    }

    // If the new column should be the last one, add it after the loop
    if var0 == df0.width() - 1 {
        reordered_columns.push(Series::new(var1, var2.clone()));
    }

    *df0 = DataFrame::new(reordered_columns)?;

    Ok(())
}

