use polars::prelude::*;

/// Insert a new column into a DataFrame at a specified position
/// 
/// # Arguments
/// * `df` - The input DataFrame
/// * `position` - The column position where the new column should be inserted (0-indexed)
/// * `column_name` - The name of the new column
/// * `column_data` - The Series containing the data for the new column
///
/// # Returns
/// * `Result<DataFrame>` - The DataFrame with the new column inserted, or an error
fn insert_column_at_position(
    mut df: DataFrame,
    position: usize,
    column_name: &str,
    column_data: Series,
) -> Result<DataFrame> {
    // Validate position
    if position > df.width() {
        return Err(PolarsError::ComputeError(
            format!("Position {} is out of bounds for DataFrame with {} columns", position, df.width())
                .into(),
        ));
    }

    // Validate that the series has the same length as the DataFrame
    if column_data.len() != df.height() {
        return Err(PolarsError::ComputeError(
            format!(
                "Series length {} does not match DataFrame height {}",
                column_data.len(),
                df.height()
            )
            .into(),
        ));
    }

    // Get all columns
    let mut columns: Vec<Series> = df.get_columns().to_vec();

    // Insert the new column at the specified position
    columns.insert(position, column_data.rename(column_name));

    // Create a new DataFrame from the modified columns
    DataFrame::new(columns)
}

