use std::collections::HashMap;

/// Partition strings into groups keyed by their first five characters.
/// Shorter strings use their entire content as the key.
///
/// - `input` can be any iterator producing `String`s (e.g. a Vec<String>).
/// - Returns a Vec of groups; each group is a Vec<String>.
pub fn partition_by_first_five<I>(input: I) -> Vec<Vec<String>>
where
    I: IntoIterator<Item = String>,
{
    let mut map: HashMap<String, Vec<String>> = HashMap::new();

    for s in input {
        // Build the key as the first five characters (or the whole string if shorter).
        let key: String = s.chars().take(5).collect();
        map.entry(key).or_default().push(s);
    }

    // Collect groups into a Vec. Order of groups is arbitrary (hashmap order).
    map.into_values().collect()
}

// Small example usage
fn main() {
    let items = vec![
        "applepie".to_string(),
        "appletart".to_string(),
        "banana".to_string(),
        "banter".to_string(),
        "app".to_string(),
        "banish".to_string(),
    ];

    let groups = partition_by_first_five(items);

    for (i, group) in groups.iter().enumerate() {
        println!("Group {}: {:?}", i + 1, group);
    }
}
```

Notes:
