use linfa::prelude::*;
use linfa_preprocessing::OneHotEncoder;
use ndarray::Array2;
use std::collections::HashMap;

/// Convert categorical columns in a DataFrame to one-hot encoded binary columns.
/// 
/// # Arguments
/// * `df0` - Input DataFrame containing potentially categorical columns
/// * `categorical_columns` - List of column names that should be treated as categorical
/// 
/// # Returns
/// * A new DataFrame with categorical columns replaced by one-hot encoded binary columns
/// 
/// # Panics
/// * If any specified categorical column doesn't exist in the DataFrame
/// * If the DataFrame is empty
pub fn one_hot_encode_categorical(
    df0: &DataFrame,
    categorical_columns: &[&str],
) -> DataFrame {
    // Validate that all specified columns exist
    for col_name in categorical_columns {
        if !df0.column_names().contains(col_name) {
            panic!("Column '{}' not found in DataFrame", col_name);
        }
    }

    // Separate categorical and numerical columns
    let all_columns: Vec<&str> = df0.column_names().iter().map(|s| s.as_str()).collect();
    let numerical_columns: Vec<&str> = all_columns
        .iter()
        .filter(|col| !categorical_columns.contains(col))
        .copied()
        .collect();

    // If no categorical columns, return original DataFrame
    if categorical_columns.is_empty() {
        return df0.clone();
    }

    // Extract categorical data as a 2D array
    let n_rows = df0.nrows();
    let n_cat_cols = categorical_columns.len();

    // Create a matrix of categorical values (as strings)
    let mut cat_data: Vec<Vec<String>> = Vec::with_capacity(n_rows);
    for i in 0..n_rows {
        let mut row: Vec<String> = Vec::with_capacity(n_cat_cols);
        for col_name in categorical_columns {
            let value = df0[col_name].get(i).unwrap();
            row.push(value.to_string());
        }
        cat_data.push(row);
    }

    // Collect all unique categories for each column
    let mut unique_categories: Vec<Vec<String>> = Vec::with_capacity(n_cat_cols);
    for col_idx in 0..n_cat_cols {
        let mut categories: Vec<String> = cat_data
            .iter()
            .map(|row| row[col_idx].clone())
            .collect();
        categories.sort();
        categories.dedup();
        unique_categories.push(categories);
    }

    // Calculate total number of new binary columns
    let total_binary_cols: usize = unique_categories.iter().map(|cats| cats.len()).sum();

    // Create one-hot encoded matrix
    let mut one_hot_matrix = Array2::<f64>::zeros((n_rows, total_binary_cols));
    let mut col_offset = 0;

    for col_idx in 0..n_cat_cols {
        let categories = &unique_categories[col_idx];
        for (cat_idx, category) in categories.iter().enumerate() {
            for row_idx in 0..n_rows {
                if cat_data[row_idx][col_idx] == *category {
                    one_hot_matrix[[row_idx, col_offset + cat_idx]] = 1.0;
                }
            }
        }
        col_offset += categories.len();
    }

    // Create new column names for binary columns
    let mut new_column_names: Vec<String> = Vec::new();

    // Add numerical columns first
    for col_name in &numerical_columns {
        new_column_names.push(col_name.to_string());
    }

    // Add one-hot encoded column names
    for col_idx in 0..n_cat_cols {
        let col_name = categorical_columns[col_idx];
        let categories = &unique_categories[col_idx];
        for category in categories {
            new_column_names.push(format!("{}_{}", col_name, category));
        }
    }

    // Build the new DataFrame
    let mut new_df = DataFrame::new();

    // Add numerical columns
    for col_name in &numerical_columns {
        let col_data = df0[col_name].as_slice().unwrap().to_vec();
        new_df.insert_column(col_name.to_string(), col_data).unwrap();
    }

    // Add one-hot encoded columns
    for (col_idx, col_name) in new_column_names.iter().enumerate().skip(numerical_columns.len()) {
        let col_data: Vec<f64> = one_hot_matrix.column(col_idx - numerical_columns.len()).to_vec();
        new_df.insert_column(col_name.clone(), col_data).unwrap();
    }

    new_df
}

