use ndarray::arr2;

let records = arr2(&[
    [0.0, 100.5],
    [1.0, 200.3],
    [2.0, 150.7],
]);
let targets = Array1::from_vec(vec![0, 1, 0]);

let dataset = DatasetBase::new(records, targets);
let encoded_dataset = one_hot_encode_categorical(dataset);

println!("{:?}", encoded_dataset.records());
```

**Note**: Adjust the categorical detection threshold in the heuristic (`unique_vals.len() < (n_rows / 2).max(3)`) based on your data characteristics. For more robust categorical detection, consider passing column metadata or using string-based categorical types.

