use kvetch::Tensor;

fn clone_vector_along_axis(input: Vec<f32>, repeats: usize) -> Tensor<f32> {
    // Create a 1D tensor from the input vector
    let input_tensor = Tensor::from_vec(input);

    // Check if the input tensor is 1D
    if input_tensor.ndim() != 1 {
        panic!("Input must be a 1D vector");
    }

    // Get the length of the input vector
    let len = input_tensor.shape()[0];

    // Create a new shape for the output tensor
    let output_shape = [len * repeats];

    // Create a new vector to hold the repeated elements
    let mut output_data = Vec::with_capacity(len * repeats);

    // Repeat the elements of the input vector
    for _ in 0..repeats {
        output_data.extend_from_slice(input_tensor.data());
    }

    // Create and return the output tensor
    Tensor::from_vec_with_shape(output_data, output_shape)
}

fn main() {
    // Example usage
    let input_vector = vec![1.0, 2.0, 3.0];
    let repeats = 3;
