use serde_json::Value;

/// Normalize a JSON value by producing a new Value where all object keys are
/// inserted in sorted order (recursively). Arrays keep their order, but their
/// elements are normalized as well.
fn normalize_json(value: &Value) -> Value {
    match value {
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            let mut normalized_map = serde_json::Map::with_capacity(map.len());
            for k in keys {
                normalized_map.insert(k.clone(), normalize_json(&map[k]));
            }
            Value::Object(normalized_map)
        }
        Value::Array(arr) => {
            let normalized_arr: Vec<Value> = arr.iter().map(normalize_json).collect();
            Value::Array(normalized_arr)
        }
        // primitives (String, Number, Bool, Null)
        other => other.clone(),
    }
}

/// Returns true if two JSON texts represent equal JSON values when treating
/// objects as unordered maps (i.e., property order does not matter).
///
/// - `a_json` and `b_json` are JSON texts (e.g., `{"b":2,"a":1}`).
/// - Returns `false` if either input is not valid JSON.
pub fn json_objects_equal(a_json: &str, b_json: &str) -> bool {
    let a_val: Value = match serde_json::from_str(a_json) {
        Ok(v) => v,
        Err(_) => return false,
    };
    let b_val: Value = match serde_json::from_str(b_json) {
        Ok(v) => v,
        Err(_) => return false,
    };

    normalize_json(&a_val) == normalize_json(&b_val)
}

