/// let obj2 = json!({"age": 30, "name": "Alice"});
/// 
/// assert!(compare_json_objects(&obj1, &obj2).is_ok());
/// ```
fn compare_json_objects(obj1: &Value, obj2: &Value) -> Result<(), String> {
    // Use assert_json_eq to compare the objects
    // This macro will panic on inequality, so we catch it
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        assert_json_eq!(obj1, obj2);
    })) {
        Ok(_) => Ok(()),
        Err(_) => Err(format!(
            "JSON objects are not equal:\nExpected: {}\nActual: {}",
            obj1, obj2
        )),
    }
}

