# Rust Function for Cartesian Product Grid

```rust
use itertools::Itertools;

/// Generate a grid of points representing the Cartesian product of two intervals.
/// 
/// # Arguments
/// * `var0` - Start of first interval (inclusive)
/// * `var1` - End of first interval (inclusive)
/// * `var2` - Start of second interval (inclusive)
/// * `var3` - End of second interval (inclusive)
/// 
/// # Returns
/// A vector of tuples representing all points in the Cartesian product grid
fn cartesian_product_grid(var0: f64, var1: f64, var2: f64, var3: f64) -> Vec<(f64, f64)> {
    let x_range = linspace(var0, var1, 10);
    let y_range = linspace(var2, var3, 10);

    x_range
        .into_iter()
        .cartesian_product(y_range)
        .collect()
}

/// Helper function to generate a linearly spaced sequence
fn linspace(start: f64, end: f64, num_points: usize) -> Vec<f64> {
    if num_points == 0 {
        return vec![];
    }
    if num_points == 1 {
        return vec![start];
    }

    let step = (end - start) / (num_points - 1) as f64;
    (0..num_points)
        .map(|i| start + i as f64 * step)
        .collect()
}

fn main() {
    // Example usage
    let grid = cartesian_product_grid(0.0, 2.0, 0.0, 3.0);

    println!("Cartesian product grid points:");
    for point in &grid {
        println!("({:.2}, {:.2})", point.0, point.1);
    }

    println!("\nTotal points: {}", grid.len());
}
