/// map1.insert("a", 1);
/// map1.insert("b", 2);
///
/// let mut map2 = HashMap::new();
/// map2.insert("a", "value_a");
/// map2.insert("b", "value_b");
///
/// let result = match_mappings(&map1, &map2);
/// assert_eq!(result.get("a"), Some(&"value_a"));
/// ```
fn match_mappings<K, V1, V2>(
    first_map: &HashMap<K, V1>,
    second_map: &HashMap<K, V2>,
) -> HashMap<K, V2>
