use std::io::{Read, Write};
use csv::{ReaderBuilder, WriterBuilder, StringRecord};

/// Read a CSV from `reader` whose first two rows are the two-level header,
/// select only columns whose second-level header equals `str0`,
/// and write the filtered table to `writer`.
///
/// Returns csv::Error if reading/writing fails.
pub fn select_columns_by_second_level<R: Read, W: Write>(
    reader: R,
    writer: W,
    str0: &str,
) -> csv::Result<()> {
    // Create reader/writer (adjust delimiter or other settings as needed)
    let mut rdr = ReaderBuilder::new().has_headers(false).from_reader(reader);
    let mut wtr = WriterBuilder::new().from_writer(writer);

    // Read the first two records as the two header rows
    let mut records_iter = rdr.records();

    let header1 = match records_iter.next() {
        Some(Ok(rec)) => rec,
        Some(Err(e)) => return Err(e),
        None => return Ok(()), // empty input
    };

    let header2 = match records_iter.next() {
        Some(Ok(rec)) => rec,
        Some(Err(e)) => return Err(e),
        None => {
            // Only one header row present — nothing to match against
            return Ok(());
        }
    };

    // Determine column indices whose second-level header equals str0
    let mut keep_indices: Vec<usize> = Vec::new();
    for (i, field) in header2.iter().enumerate() {
        if field == str0 {
            keep_indices.push(i);
        }
    }

    // If nothing to keep, write empty output (or just the two header rows with no columns)
    // Write filtered header1 and header2
    let mut out_h1 = StringRecord::new();
    let mut out_h2 = StringRecord::new();
    for &idx in &keep_indices {
        out_h1.push_field(header1.get(idx).unwrap_or(""));
        out_h2.push_field(header2.get(idx).unwrap_or(""));
    }
    wtr.write_record(&out_h1)?;
    wtr.write_record(&out_h2)?;

    // Write remaining data rows, selecting the kept columns
    for result in records_iter {
        let rec = result?;
        let mut out_rec = StringRecord::new();
        for &idx in &keep_indices {
            out_rec.push_field(rec.get(idx).unwrap_or(""));
        }
        wtr.write_record(&out_rec)?;
    }

    wtr.flush()?;
    Ok(())
}

