/// * `key_fn` - A function that extracts a comparable key from each item
/// 
/// # Returns
/// A new vector containing the sorted elements
/// 
/// # Example
/// ```
/// let numbers = vec![3, 1, 4, 1, 5];
/// let sorted = sort_by_key(numbers, |x| x);
/// assert_eq!(sorted, vec![1, 1, 3, 4, 5]);
/// ```
fn sort_by_key<T: Clone, K: Ord>(items: Vec<T>, key_fn: fn(&T) -> K) -> Vec<T> {
    // Create a SortedMap where keys are indices and values are the items
    // We use a wrapper to make the key function work with the sorted map
    let mut sorted_map: SortedMap<Vec<u8>, T> = SortedMap::new();

    // Alternative approach: collect into a vec, sort, and return
    let mut indexed_items: Vec<(T, K)> = items
        .into_iter()
        .map(|item| {
            let key = key_fn(&item);
            (item, key)
        })
        .collect();

    // Sort by the extracted keys
    indexed_items.sort_by(|a, b| a.1.cmp(&b.1));

    // Extract just the items in sorted order
    indexed_items.into_iter().map(|(item, _)| item).collect()
}

// More direct approach using SortedMap with tuples:
/// Alternative implementation using SortedMap more directly
fn sort_by_key_with_sorted_map<T: Clone + Ord, K: Ord>(
    items: Vec<T>,
    key_fn: fn(&T) -> K,
) -> Vec<T> {
