use simdize::prelude::*;
use std::simd::{Simd, LaneCount, SupportedLaneCount};

fn compare_sequences(lst0: &[i32], lst1: &[i32]) -> Vec<bool> {
    assert_eq!(lst0.len(), lst1.len(), "Input slices must be of equal length");

    let mut results = vec![false; lst0.len()];

    // Process data in chunks using SIMD
    let simd_size = <Simd<i32, LaneCount<4>>::LANE_COUNT>::to_usize();

    let mut i = 0;
    while i < lst0.len() {
        // Load elements into SIMD registers
        let end = std::cmp::min(i + simd_size, lst0.len());

        let simd_lst0 = Simd::from_slice(&lst0[i..end]);
        let simd_lst1 = Simd::from_slice(&lst1[i..end]);

        // Compare the slices using SIMD
        let comparisons = simd_lst0.lt(simd_lst1);

        // Store results
        results[i..end].copy_from_slice(&comparisons.to_array());

        i += simd_size;
    }

    results
}

