/// let lst1 = [2, 3, 4, 5, 6];
/// let result = compare_less_than(&lst0, &lst1);
/// assert_eq!(result, [false, false, false, false, false]);
/// ```
pub fn compare_less_than<T, const N: usize>(lst0: &[T; N], lst1: &[T; N]) -> [bool; N]
where
    T: SimdInt + SimdPartialOrd,
{
    // Convert the arrays to SIMD vectors
    let v0 = SimdArray::from_slice(lst0);
    let v1 = SimdArray::from_slice(lst1);

    // Compare each element and return the result as a boolean vector
    let result = v0 < v1;

    // Convert the SIMD boolean vector back to a regular array
    result.into()
}

