/// A vector of booleans where true means lst0[i] < lst1[i]
///
/// # Panics
/// Panics if the sequences have different lengths
pub fn elementwise_less_than<T>(lst0: &[T], lst1: &[T]) -> Vec<bool>
where
    T: SimdElement + PartialOrd,
    T::Simd: SimdVec,
    LaneCount<{ T::Simd::LANES }>: SupportedLaneCount,
{
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "Sequences must have equal lengths"
    );

    let len = lst0.len();
    let simd_lanes = T::Simd::LANES;
    let mut result = vec![false; len];

    // Process in SIMD chunks
    let chunks = len / simd_lanes;
    let remainder = len % simd_lanes;

    for i in 0..chunks {
        let start = i * simd_lanes;
        let end = start + simd_lanes;

        // Load SIMD vectors
        let vec0 = T::Simd::from_slice(&lst0[start..end]);
        let vec1 = T::Simd::from_slice(&lst1[start..end]);

        // Compare element-wise
        let comparison = vec0.simd_lt(vec1);

        // Store results
        for j in 0..simd_lanes {
            result[start + j] = comparison.test(j);
        }
    }

    // Handle remaining elements
    if remainder > 0 {
        let start = chunks * simd_lanes;
        for i in 0..remainder {
            result[start + i] = lst0[start + i] < lst1[start + i];
        }
    }

    result
}

