use simdize::Simd;

/// Compares two sequences element-wise and returns a vector of booleans
/// indicating whether each element in lst0 is strictly less than the corresponding
/// element in lst1.
///
/// # Arguments
/// * `lst0` - First sequence of comparable elements
/// * `lst1` - Second sequence of comparable elements (must be same length as lst0)
///
/// # Returns
/// A vector of booleans where result[i] = (lst0[i] < lst1[i])
///
/// # Panics
/// Panics if lst0 and lst1 have different lengths
fn compare_less_than(lst0: &[f32], lst1: &[f32]) -> Vec<bool> {
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "Input sequences must have equal length"
    );

    let mut result = vec![false; lst0.len()];

    // Process SIMD lanes
    let lanes = Simd::<f32>::lanes();
    let chunks = lst0.len() / lanes;

    for i in 0..chunks {
        let idx = i * lanes;
        let v0 = Simd::from_slice_unaligned(&lst0[idx..]);
        let v1 = Simd::from_slice_unaligned(&lst1[idx..]);

        let cmp = v0.lt(v1);

        for j in 0..lanes {
            result[idx + j] = cmp.extract(j);
        }
    }

    // Handle remaining elements that don't fit in a full SIMD lane
    let remaining_start = chunks * lanes;
    for i in remaining_start..lst0.len() {
        result[i] = lst0[i] < lst1[i];
    }

    result
}

