use rayon::prelude::*;

/// Returns the indices of elements in a sequence whose values lie within 
/// a specified inclusive range [min_bound, max_bound].
///
/// # Arguments
///
/// * `sequence` - A slice of comparable elements
/// * `min_bound` - The minimum value (inclusive) of the range
/// * `max_bound` - The maximum value (inclusive) of the range
///
/// # Returns
///
/// A vector of indices where elements fall within the specified range
///
/// # Example
///
/// ```
/// let data = vec![1, 5, 3, 8, 2, 9, 4];
/// let result = find_indices_in_range(&data, 3, 7);
/// assert_eq!(result, vec![2, 4]); // indices of 3, 5, 4
/// ```
fn find_indices_in_range<T: PartialOrd + Send + Sync>(
    sequence: &[T],
    min_bound: T,
    max_bound: T,
) -> Vec<usize> {
    sequence
        .par_iter()
        .enumerate()
        .filter(|(_, value)| **value >= min_bound && **value <= max_bound)
        .map(|(index, _)| index)
        .collect()
}

