fn average_squared_differences<T>(lst0: &[T], lst1: &[T]) -> Option<f64>
where
    T: Copy + std::ops::Sub<Output = T> + Into<f64>,
{
    if lst0.len() != lst1.len() {
        return None; // return None if lists are not of the same length
    }

    let squared_differences: Vec<f64> = lst0
