/// Groups rows in a DataFrame by the values in column `var0` and sums the remaining columns
/// for each group.
///
/// # Arguments
/// * `var1` - The input DataFrame to be grouped and summed
/// * `var0` - The name of the column to group by
///
/// # Returns
/// * `Result<DataFrame, String>` - A new DataFrame with one row per group, containing the
///   group key and summed values for all other columns
///
/// # Example
/// ```rust
/// use datameld::prelude::*;
/// 
/// let df = DataFrame::from_rows(vec![
///     vec!["A".into(), "1".into(), "2".into()],
///     vec!["A".into(), "3".into(), "4".into()],
///     vec!["B".into(), "5".into(), "6".into()],
/// ]).unwrap();
/// 
/// let result = group_and_sum(df, "col0").unwrap();
/// ```
fn group_and_sum(var1: DataFrame, var0: &str) -> Result<DataFrame, String> {
    // Find the index of the grouping column
    let group_col_idx = var1
        .columns()
        .iter()
        .position(|c| c.name() == var0)
        .ok_or_else(|| format!("Column '{}' not found in DataFrame", var0))?;

    // Get the names of all other columns (to be summed)
    let sum_col_names: Vec<String> = var1
        .columns()
        .iter()
        .enumerate()
        .filter(|(i, _)| *i != group_col_idx)
        .map(|(_, c)| c.name().to_string())
        .collect();

    // HashMap to store group key -> vector of sums
    let mut group_sums: HashMap<String, Vec<f64>> = HashMap::new();

    // Iterate through all rows
    for row_idx in 0..var1.nrows() {
        // Get the group key
        let group_key = var1
            .get(row_idx, group_col_idx)
            .ok_or_else(|| format!("Missing value at row {}, col {}", row_idx, group_col_idx))?
            .to_string();

        // Initialize sums for this group if not present
        group_sums.entry(group_key.clone())
            .or_insert_with(|| vec![0.0; sum_col_names.len()]);

        // Add values from this row to the group sums
        if let Some(sums) = group_sums.get_mut(&group_key) {
            for (sum_idx, col_name) in sum_col_names.iter().enumerate() {
                let col_idx = var1
                    .columns()
                    .iter()
                    .position(|c| c.name() == col_name)
                    .ok_or_else(|| format!("Column '{}' not found", col_name))?;

                let value = var1
                    .get(row_idx, col_idx)
                    .ok_or_else(|| format!("Missing value at row {}, col {}", row_idx, col_idx))?;

                // Try to parse as f64, default to 0.0 if not possible
                if let Ok(num) = value.to_string().parse::<f64>() {
                    sums[sum_idx] += num;
                }
            }
        }
    }

    // Build the result DataFrame
    let mut result_rows: Vec<Vec<Value>> = Vec::new();

    for (group_key, sums) in group_sums {
        let mut row = vec![Value::String(group_key)];
        row.extend(sums.into_iter().map(|s| Value::Float(s)));
