fn missing_percentage<T: Array>(array: &T) -> f64 {
    let total_entries = array.len();
    let null_entries = num_nulls(array);

    if total_entries == 0 {
        return 0.0; // Avoid division by zero
    }

    (null_entries as f64 / total_entries as f64) * 100.0
}

