/// - rows: slice of rows; each row is a Vec<String>.
/// - If rows have different lengths, missing cells are ignored.
/// - Ties keep the first-seen longest entry.
pub fn longest_in_columns(rows: &[Vec<String>]) -> Vec<String> {
    // Determine number of columns present in any row.
    let cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);

