# Rust Function: Find Longest Text in Each Column

```rust
/// Given a 2D list of text values, returns the longest text from each column.
/// 
/// # Arguments
/// * `data` - A 2D vector where each inner vector represents a row
/// 
/// # Returns
/// A vector containing the longest string from each column
/// 
/// # Example
/// ```
/// let data = vec![
///     vec!["a", "hello", "x"],
///     vec!["longer", "hi", "example"],
///     vec!["b", "world!", "xy"],
/// ];
/// let result = longest_in_columns(&data);
/// assert_eq!(result, vec!["longer", "hello", "example"]);
/// ```
fn longest_in_columns(data: &[Vec<&str>]) -> Vec<String> {
    if data.is_empty() {
        return Vec::new();
    }

    // Determine the number of columns from the first row
    let num_cols = data[0].len();

    // Initialize result vector with empty strings
    let mut longest: Vec<String> = vec![String::new(); num_cols];

    // Iterate through each row
    for row in data {
        // Iterate through each column in the row
        for (col_idx, &cell) in row.iter().enumerate() {
            // Update the longest string for this column if current cell is longer
            if cell.len() > longest[col_idx].len() {
                longest[col_idx] = cell.to_string();
            }
        }
    }

    longest
}

fn main() {
    // Example usage
    let data = vec![
        vec!["apple", "hello", "x"],
        vec!["longer", "hi", "example"],
        vec!["b", "world!", "xy"],
    ];

    let result = longest_in_columns(&data);

    println!("Input data:");
    for row in &data {
        println!("{:?}", row);
    }

    println!("\nLongest text in each column:");
    for (idx, longest) in result.iter().enumerate() {
        println!("Column {}: '{}'", idx, longest);
    }
}
```

