            let entry = aggregated.entry(key.clone()).or_insert_with(V::default);
            *entry = *entry + *value;
        }
    }

    // Convert to Vec and sort by value
    let mut result: Vec<(K, V)> = aggregated.into_iter().collect();
    result.sort_by(|a, b| a.1.cmp(&b.1));

    result
}

