// Function to update values in df0 based on corresponding values in df1
// Assumes df0 and df1 have the same structure (same columns and indices)
// and we want to replace values in df0 where the indices match.
pub fn update_df0_from_df1(df0: &mut DataFrame, df1: &DataFrame) -> Result<(), dataarray::Error> {
    // Check if df0 and df1 have the same number of columns
    if df0.columns().len() != df1.columns().len() {
        return Err(dataarray::Error::new("DataFrames must have the same number of columns"));
    }

    // Iterate over each column and update values in df0 where indices match
    for (col_name, col_data) in df1.columns() {
        let df0_col = df0.column_mut(col_name).ok_or_else(|| {
            dataarray::Error::new(format!("Column '{}' not found in df0", col_name))
        })?;

        // Get the corresponding column from df1
        let df1_col = df1.column(col_name).ok_or_else(|| {
            dataarray::Error::new(format!("Column '{}' not found in df1", col_name))
        })?;

        // Update df0's column with df1's values (assuming same indices)
        df0_col.set_values(df1_col.values().clone())?;
    }

    Ok(())
}

