use polars::prelude::*;

/// Updates specific cells in df0 based on corresponding cells in df1.
///
/// # Arguments
///
/// * `df0`: The DataFrame to update.
/// * `df1`: The DataFrame containing the new values.
/// * `column_names`: The names of the columns to update.
///
/// # Returns
///
/// The updated DataFrame.
fn update_cells(df0: DataFrame, df1: DataFrame, column_names: Vec<String>) -> DataFrame {
    let mut updated_df = df0.clone();

    for column_name in column_names {
        let s0 = updated_df.column(&column_name).unwrap();
        let s1 = df1.column(&column_name).unwrap();

        // Ensure both series have the same length
        assert_eq!(s0.len(), s1.len());

        let updated_series = s0
            .into_iter()
            .zip(s1.into_iter())
            .map(|(old_value, new_value)| match (old_value, new_value) {
                (Some(old), Some(new)) => Some(new),
                (old, None) => old,
                (None, Some(new)) => Some(new),
                (None, None) => None,
            })
            .collect::<Vec<_>>();

        updated_df = updated_df.with_column(column_name, Series::new(column_name, updated_series));
    }

    updated_df
}

fn main() -> Result<(), PolarsError> {
