    let df0_columns = df0.columns();
    let df1_columns = df1.columns();

    // Process each mapping
    for ((target_row, target_col), (source_row, source_col)) in row_col_mapping {
        // Validate target column exists in df0
        if !df0_columns.contains(target_col) {
            return Err(format!("Column '{}' not found in df0", target_col));
        }

        // Validate source column exists in df1
        if !df1_columns.contains(source_col) {
            return Err(format!("Column '{}' not found in df1", source_col));
        }

        // Validate row indices are within bounds
        let df0_rows = df0.nrows();
        let df1_rows = df1.nrows();

        if *target_row >= df0_rows {
            return Err(format!(
                "Row index {} out of bounds for df0 (max: {})",
                target_row,
