            ));
        }

        if *source_row >= df1_rows {
            return Err(format!(
                "Row index {} out of bounds for df1 (max: {})",
                source_row,
                df1_rows - 1
            ));
        }

        // Get the value from df1
        let source_value = df1.get(*source_row, source_col)
            .ok_or_else(|| format!(
                "Failed to get value from df1 at row {}, column '{}'",
                source_row, source_col
            ))?;

        // Set the value in df0
        df0.set(*target_row, target_col, source_value)
            .map_err(|e| format!(
                "Failed to set value in df0 at row {}, column '{}': {}",
                target_row, target_col, e
            ))?;
    }

