    rule expression = { term ((">" | "<" | ">=" | "<=" | "!=" | "~=") term)* }

    rule term =
        { number }
        / { "(" expression ")" }
        / { "between" number "and" number }
        / { "more than" number }
        / { "less than" number }
        / { "greater than" number }
        / { "not" ("more" | "less") "than" number }

    rule number = { _:DIGIT+ (_:DIGIT*)? ("." _:DIGIT+)? (_:DIGIT*)? }
"]
pub struct NumericalExpressionParser;

pub fn extract_numerical_comparisons(input: &str) -> Vec<(String, String)> {
    // Parse the input string
    let pairs = NumericalExpressionParser::parse(Rule::expression, input)
        .expect("Failed to parse input");

    let mut results = Vec::new();

    // Process each top-level expression
    for pair in pairs {
        let mut left = String::new();
        let mut right = String::new();
