        // Handle special cases like "between", "more than", etc.
        for child in pair.into_inner() {
            match child.as_rule() {
                Rule::between => {
                    let mut children = child.into_inner();
                    if let (Some(low), Some(high)) = (children.next(), children.next()) {
                        if let (Ok(low_str), Ok(high_str)) = (low.as_str().to_string(), high.as_str().to_string()) {
                            results.push((low_str, format!("between {} and {}", low_str, high_str)));
                        }
                    }
                }
                Rule::more_than => {
                    if let Some(number) = child.into_inner().next() {
                        if let Ok(number_str) = number.as_str().to_string() {
                            results.push((number_str, format!("more than {}", number_str)));
                        }
                    }
                }
                Rule::less_than => {
                    if let Some(number) = child.into_inner().next() {
                        if let Ok(number_str) = number.as_str().to_string() {
                            results.push((number_str, format!("less than {}", number_str)));
                        }
                    }
                }
                Rule::greater_than => {
                    if let Some(number) = child.into_inner().next() {
                        if let Ok(number_str) = number.as_str().to_string() {
                            results.push((number_str, format!("greater than {}", number_str)));
                        }
                    }
                }
                Rule::not_more_than | Rule::not_less_than => {
                    let mut children = child.into_inner();
                    if let Some(negation) = children.next() {
                        if let Some(number) = children.next() {
                            if let (Ok(neg_str), Ok(number_str)) = (negation.as_str().to_string(), number.as_str().to_string()) {
                                let op = if child.as_rule() == Rule::not_more_than {
                                    "not more than"
                                } else {
                                    "not less than"
                                };
                                results.push((number_str, op.to_string()));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }

