```rust
use pest::{Parser, Span};
use pest_derive::Parser;

// Define the grammar for our parser
#[derive(Parser)]
#[grammar_inline = r#"
    num = { "0" | "1".."9" ~ ("0".."9")* }
    comparison = { "less" | "greater" | "between" | "more" }
    range_expr = { "between" ~ num ~ "and" ~ num }
    expr = { num ~ comparison? | range_expr }
"#]
struct ComparisonParser;

fn extract_numerical_values(var0: &str) -> Vec<(String, Option<String>, Option<String>)> {
    let mut result = Vec::new();
    let pairs = ComparisonParser::parse(Rule::expr, var0).unwrap_or_else(|e| panic!("{}", e));

    for pair in pairs {
        let span = pair.as_span();
        let text = span.as_str();

        let mut parts = text.split_whitespace();
        let num = parts.next().unwrap().to_string();

        let comparison = if let Some(comparison_term) = parts.next() {
            Some(comparison_term.to_string())
        } else {
            None
        };

        let range = if text.contains("between") {
            let mut range_parts = text.split("between").nth(1).unwrap().split("and");
            let start = range_parts.next().unwrap().trim().to_string();
            let end = range_parts.next().unwrap().trim().to_string();
            Some((start, end))
        } else {
            None
        };

        result.push((num, comparison, range.map(|(start, end)| format!("{}-{}", start, end))));
    }

    result
}

fn main() {
    let var0 = "10 less than 20 between 30 and 40";
    let result = extract_numerical_values(var0);

    for (num, comparison, range) in result {
        println!("Number: {}, Comparison: {:?}, Range: {:?}", num, comparison, range);
    }
}
```

