Code:

```rust
use pest::Parser;
use pest::iterators::Pair;

#[derive(Parser)]
#[grammar_inline = r#"
WHITESPACE = _{ " " | "\t" | "\n" }

root = { SOI ~ item* ~ EOI }
item = { expression | ANY }

expression = { range | cmp_prefix | cmp_suffix | number }

range = { between | from_to }
between = { "between" ~ ws+ ~ number ~ ws+ ~ ("and" | "-") ~ ws+ ~ number }
from_to = { "from" ~ ws+ ~ number ~ ws+ ~ ("to" | "-") ~ ws+ ~ number }

cmp_prefix = { comp_words ~ ws* ~ number }
cmp_suffix = { number ~ ws* ~ symbols }

comp_words = {
      "less" ~ ws+ ~ "than"
    | "more" ~ ws+ ~ "than"
    | "greater" ~ ws+ ~ "than"
    | "at" ~ ws+ ~ "least"
    | "at" ~ ws+ ~ "most"
    | "no" ~ ws+ ~ "more" ~ ws+ ~ "than"
    | "no" ~ ws+ ~ "less" ~ ws+ ~ "than"
}

symbols = { ">=" | "<=" | ">" | "<" | "=" | "≥" | "≤" }

number = { sign? ~ num_core ~ perc? }
sign = { "+" | "-" }
perc = { "%" }
num_core = {
      ASCII_DIGIT+ ~ ("," ~ ASCII_DIGIT{3})* ~ frac?
}
frac = { "." ~ ASCII_DIGIT+ }

ws = _{ WHITESPACE+ }
"#]
struct ExprParser;

pub fn extract_numbers_with_comparisons(var0: &str) -> Vec<String> {
    // Work on lowercase for keyword matching, but use original for slicing results
    let lower = var0.to_lowercase();

    let mut results = Vec::new();

    let parse_result = ExprParser::parse(Rule::root, &lower);
    let pairs = match parse_result {
        Ok(p) => p,
        Err(_) => return results, // parsing failure -> return empty
    };

    // recursive visitor to collect expression spans
    fn visit(pair: Pair<Rule>, original: &str, results: &mut Vec<String>) {
        match pair.as_rule() {
            Rule::expression => {
                let span = pair.as_span();
                // map indices from lowercase input back to original string slice
                let start = span.start();
                let end = span.end();
                // Safety: indices align because the lowercase copy has same length as original
                if let Some(slice) = original.get(start..end) {
                    results.push(slice.to_string());
                }
            }
            _ => {
                for inner in pair.into_inner() {
                    visit(inner, original, results);
                }
            }
        }
    }

    for top in pairs {
        visit(top, var0, &mut results);
    }

    results
}

