struct NumberParser;

#[derive(Debug, Clone, PartialEq)]
pub enum ComparisonType {
    LessThan,
    LessThanOrEqual,
    GreaterThan,
    GreaterThanOrEqual,
    Equal,
    NotEqual,
    Between(f64, f64),
    Range(f64, f64),
    Exact(f64),
}

#[derive(Debug, Clone, PartialEq)]
pub struct ExtractedValue {
