pub fn extract_numerical_values(text: &str) -> Result<Vec<ExtractedValue>, PestifyError> {
    let mut results = Vec::new();

    // Parse the input text using pestify
    let pairs = NumberParser::parse(Rule::main, text)?;

    for pair in pairs {
        match pair.as_rule() {
            Rule::value_expression => {
                let inner = pair.into_inner().next().unwrap();
                match inner.as_rule() {
                    Rule::range_expression => {
                        let range_parts: Vec<&str> = inner.as_str().split_whitespace().collect();
                        if range_parts.len() >= 3 {
                            // Handle "between X and Y" or "from X to Y" or "X to Y" or "X-Y"
                            let numbers: Vec<f64> = range_parts.iter()
                                .filter_map(|s| s.parse::<f64>().ok())
                                .collect();

                            if numbers.len() == 2 {
                                results.push(ExtractedValue {
                                    value: numbers[0],
                                    comparison: Some(ComparisonType::Between(numbers[0], numbers[1])),
                                    original_text: inner.as_str().to_string(),
                                });
                                results.push(ExtractedValue {
                                    value: numbers[1],
                                    comparison: Some(ComparisonType::Between(numbers[0], numbers[1])),
                                    original_text: inner.as_str().to_string(),
                                });
                            }
                        }
                    }
                    Rule::comparison_expression => {
                        let mut parts = inner.into_inner();
                        let comparison_term = parts.next().unwrap();
                        let number = parts.next().unwrap();

                        let value: f64 = number.as_str().parse().unwrap();
                        let comparison = parse_comparison_term(comparison_term.as_str());

                        results.push(ExtractedValue {
                            value,
                            comparison: Some(comparison),
                            original_text: inner.as_str().to_string(),
                        });
