fn add_grouped_statistics(df: &DataFrame) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Ensure the input DataFrame has necessary columns
    if !df.has_column("var0") || !df.has_column("var1") {
        return Err("DataFrame must contain columns 'var0' and 'var1'".into());
    }

    // Group by 'var0' and calculate mean and sum of 'var1'
    let grouped_mean = df
        .groupby("var0")?
        .agg(&[("var1", "mean")])?
