        .arrays()
        .iter()
        .position(|_| true)
        .ok_or_else(|| "No columns in chunk".to_string())?;

    let filter_array = &chunk.arrays()[col0_index];
    let sum_array = &chunk.arrays()[col1_index];

    let mut count = 0;
    let mut sum = 0.0;

    // Process numeric filter column
