            process_filtering(filter_values, sum_array, threshold0, &mut count, &mut sum)?;
        }
        DataType::Int64 => {
            let filter_values = filter_array
                .as_any()
                .downcast_ref::<arrow2::array::Int64Array>()
                .ok_or("Failed to cast to Int64Array")?;

            process_filtering(filter_values, sum_array, threshold0, &mut count, &mut sum)?;
        }
        DataType::Float32 => {
            let filter_values = filter_array
                .as_any()
                .downcast_ref::<arrow2::array::Float32Array>()
                .ok_or("Failed to cast to Float32Array")?;

            process_filtering(filter_values, sum_array, threshold0, &mut count, &mut sum)?;
        }
        DataType::Float64 => {
            let filter_values = filter_array
                .as_any()
                .downcast_ref::<arrow2::array::Float64Array>()
                .ok_or("Failed to cast to Float64Array")?;

            process_filtering(filter_values, sum_array, threshold0, &mut count, &mut sum)?;
        }
        _ => return Err(format!("Unsupported data type for filtering: {:?}", filter_array.data_type())),
    }

    Ok((count, sum))
}

/// Helper function to process filtering and summing
fn process_filtering<T: arrow2::types::NativeType + PartialOrd + Into<f64> + Copy>(
    filter_values: &arrow2::array::PrimitiveArray<T>,
    sum_array: &Box<dyn Array>,
    threshold0: f64,
    count: &mut usize,
    sum: &mut f64,
) -> Result<(), String> {
    let threshold = T::from(threshold0).ok_or("Cannot convert threshold")?;

    match sum_array.data_type() {
        DataType::Float64 => {
            let sum_values = sum_array
                .as_any()
                .downcast_ref::<arrow2::array::Float64Array>()
                .ok_or("Failed to cast sum array to Float64Array")?;

            for (i, filter_val) in filter_values.iter().enumerate() {
                if let Some(fv) = filter_val {
                    if *fv > threshold {
                        *count += 1;
                        if let Some(sv) = sum_values.get(i) {
                            *sum += sv;
                        }
                    }
                }
            }
        }
        _ => return Err("Unsupported sum column data type".to_string()),
    }

    Ok(())
}

