use ndarray::{arr2, ArrayView2, Axis};

/// For each row in `arr` returns the column name (from `col_names`)
/// that contains the highest value in that row.
///
/// - `arr` must be shape (n_rows, n_cols).
/// - `col_names.len()` must equal `n_cols`.
/// Ties are resolved by picking the first (leftmost) maximum.
fn max_col_per_row(arr: ArrayView2<f64>, col_names: &[&str]) -> Vec<String> {
    let shape = arr.shape();
    assert!(
        shape.len() == 2,
        "expected a 2D array (rows x cols)"
    );
    let n_rows = shape[0];
    let n_cols = shape[1];
    assert_eq!(
        n_cols,
        col_names.len(),
        "number of column names must match number of columns in the array"
    );

    let mut result = Vec::with_capacity(n_rows);
    for row in arr.axis_iter(Axis(0)) {
        // Handle empty row / zero columns
        if n_cols == 0 {
            result.push(String::new());
            continue;
        }

        // initialize with first element
        let mut max_idx = 0usize;
        let mut max_val = row[0];

        // scan remaining columns
        for (i, &v) in row.iter().enumerate().skip(1) {
            if v > max_val {
                max_val = v;
                max_idx = i;
            }
        }

        result.push(col_names[max_idx].to_string());
    }

    result
}

fn main() {
    // example data: 3 rows x 3 cols
    let a = arr2(&[
        [1.0, 4.0, 2.0],
        [3.0, 3.0, 1.0],
        [0.5, 0.2, 0.8],
    ]);

