/// Removes columns from a sparse matrix based on the indices in `columns_to_delete`.
///
/// # Arguments
/// * `mat0` - The input sparse matrix (CSR format)
/// * `columns_to_delete` - A sorted vector of column indices to remove (0-based)
///
/// # Returns
/// A new sparse matrix with the specified columns removed.
pub fn remove_columns(mat0: &CSRMatrix<f64>, columns_to_delete: Vec<usize>) -> CSRMatrix<f64> {
    // Ensure columns_to_delete is sorted and unique
    let mut columns_to_delete: Vec<usize> = columns_to_delete.into_iter().collect();
    columns_to_delete.sort();
    columns_to_delete.dedup();

    // Create a mapping from old column indices to new column indices
    let mut new_col_map = Vec::with_capacity(mat0.ncols());
    let mut new_col_idx = 0;
    for old_col in 0..mat0.ncols() {
        if !columns_to_delete.contains(&old_col) {
            new_col_map.push(new_col_idx);
            new_col_idx += 1;
        } else {
            new_col_map.push(usize::MAX); // Mark as deleted
        }
    }

    // Rebuild the CSR matrix with new column indices
    let mut new_rows = Vec::new();
    let mut new_col_ptr = Vec::new();
    let mut new_indices = Vec::new();
    let mut new_values = Vec::new();

    // Copy the original row pointers
    new_col_ptr.push(0);
    for &row_ptr in &mat0.col_ptr {
        new_col_ptr.push(row_ptr);
    }

    // Process each row
    for (row, &start) in mat0.row_ptr.iter().enumerate() {
        let end = mat0.row_ptr[row + 1];
        let mut new_row_start = new_col_ptr[row];
        let mut new_row_end = new_col_ptr[row + 1];

        for i in start..end {
            let old_col = mat0.indices[i];
            if let Some(new_col) = new_col_map.get(old_col).and_then(|&x| if x != usize::MAX { Some(x) } else { None }) {
