/// - `mat` : input sparse matrix (any storage order).
/// - `columns_to_delete` : slice of column indices to remove (0-based).
///
/// Returns a new CsMat in CSR format with the remaining columns.
///
/// Panics if any index in `columns_to_delete` is >= mat.cols().
pub fn remove_columns<N: Clone>(mat: &CsMat<N>, columns_to_delete: &[usize]) -> CsMat<N> {
    let nrows = mat.rows();
    let ncols = mat.cols();

    // Build deletion mask, checking indices are in range
    let mut delete_mask = vec![false; ncols];
    for &c in columns_to_delete {
        if c >= ncols {
            panic!("column index out of range: {}", c);
        }
        delete_mask[c] = true;
    }

    // Build mapping from old column index to new column index
    let mut mapping = vec![usize::MAX; ncols];
    let mut kept_cols = 0usize;
    for j in 0..ncols {
        if !delete_mask[j] {
            mapping[j] = kept_cols;
            kept_cols += 1;
        }
    }

    // Work column-wise: convert to CSC for efficient column access
    let csc = mat.to_csc();

    // Create a triplet (COO) builder for the resulting matrix
    let mut tri: TriMat<N> = TriMat::with_capacity((nrows, kept_cols), csc.nnz());

    let indptr = csc.indptr();
    let indices = csc.indices();
    let data = csc.data();

    for old_col in 0..ncols {
        if delete_mask[old_col] {
            continue;
        }
        let new_col = mapping[old_col];
        let start = indptr[old_col];
        let end = indptr[old_col + 1];
        for idx in start..end {
            let row = indices[idx];
            let value = data[idx].clone();
            tri.add_triplet(row, new_col, value);
        }
    }

    // Convert the triplet to CSR (row-major) and return
    tri.to_csr()
}

