                new_data.extend(row_data);
                new_indptr.push(Iptr::from_usize(new_indices.len()).unwrap());
            }
        }
        sparse::CompressedStorage::CSC => {
            // For CSC format, iterate column by column
            new_indptr.push(Iptr::from_usize(0).unwrap());

