use sprs::CsMat;

/// Removes columns from a sparse matrix based on the provided indices.
///
/// # Arguments
/// * `mat0` - The input sparse matrix
/// * `columns_to_delete` - A sequence of column indices to remove
///
/// # Returns
/// A new sparse matrix with the specified columns removed
fn remove_columns<T: Clone + Default>(
    mat0: &CsMat<T>,
    columns_to_delete: &[usize],
) -> CsMat<T> {
    let num_rows = mat0.rows();
    let num_cols = mat0.cols();

    // Create a set of columns to delete for O(1) lookup
    let delete_set: std::collections::HashSet<usize> = columns_to_delete.iter().cloned().collect();

    // Build mapping from old column indices to new column indices
    let mut col_mapping = vec![None; num_cols];
    let mut new_col_idx = 0;

    for old_col_idx in 0..num_cols {
        if !delete_set.contains(&old_col_idx) {
            col_mapping[old_col_idx] = Some(new_col_idx);
            new_col_idx += 1;
        }
    }

    let new_num_cols = new_col_idx;

    // Build the new matrix by iterating through non-zero elements
    let mut new_mat = CsMat::empty(sprs::CompressedStorage::ColMajor, num_rows, new_num_cols);
    let mut col_data: Vec<Vec<(usize, T)>> = vec![Vec::new(); new_num_cols];

    // Iterate through each column of the original matrix
    for (old_col_idx, col_vec) in mat0.iter() {
        // Check if this column should be kept
        if let Some(new_col_idx) = col_mapping[old_col_idx] {
            // Copy all elements from this column to the new matrix
            for (row_idx, &value) in col_vec.iter() {
                col_data[new_col_idx].push((row_idx, value.clone()));
            }
        }
    }

    // Convert collected data into a proper sparse matrix
    let mut row_indices = Vec::new();
    let mut data = Vec::new();
    let mut col_ptrs = vec![0];

    for col_vec in col_data {
        for (row_idx, value) in col_vec {
            row_indices.push(row_idx);
            data.push(value);
        }
        col_ptrs.push(data.len());
    }

    CsMat::new(
        sprs::CompressedStorage::ColMajor,
        (num_rows, new_num_cols),
        col_ptrs,
        row_indices,
        data,
    )
}

