use arrow::datatypes::{DataType, Field};
use arrow::record_batch::RecordBatch;

fn remove_nested_subcolumn(
    mut batch: RecordBatch,
    primary_column: &str,
    subcolumn: &str,
) -> Result<RecordBatch, Box<dyn std::error::Error>> {
    // Get the schema and find the primary column
    let schema = batch.schema();
    let primary_field_idx = schema
        .fields()
        .iter()
        .position(|f| f.name() == primary_column)
        .ok_or(format!("Column '{}' not found", primary_column))?;

    let primary_field = schema.field(primary_field_idx);

    // Ensure the primary column is a struct type
    let struct_type = match primary_field.data_type() {
        DataType::Struct(fields) => fields,
        _ => return Err(format!(
            "Column '{}' is not a struct type",
            primary_column
        )
        .into()),
    };

    // Filter out the subcolumn to remove
    let new_fields: Vec<Field> = struct_type
        .iter()
        .filter(|f| f.name() != subcolumn)
        .cloned()
        .collect();

    if new_fields.len() == struct_type.len() {
        return Err(format!(
            "Subcolumn '{}' not found in '{}'",
            subcolumn, primary_column
        )
        .into());
    }

    // Create new field with filtered struct
    let new_primary_field =
        Field::new(primary_column, DataType::Struct(new_fields), primary_field.is_nullable());

    // Rebuild schema with the modified primary column
    let mut new_fields_schema = schema.fields().to_vec();
    new_fields_schema[primary_field_idx] = new_primary_field;

    let new_schema = arrow::datatypes::Schema::new(new_fields_schema);

    // Get the struct array and filter its columns
    let struct_array = batch
        .column(primary_field_idx)
        .as_any()
        .downcast_ref::<arrow::array::StructArray>()
        .ok_or("Failed to downcast to StructArray")?;

    // Filter the struct array columns
    let new_columns: Vec<arrow::array::ArrayRef> = struct_array
        .columns()
        .iter()
        .enumerate()
        .filter(|(i, _)| struct_type[*i].name() != subcolumn)
        .map(|(_, col)| col.clone())
        .collect();

    let new_struct_array =
        arrow::array::StructArray::new(DataType::Struct(new_fields), new_columns, None);

    // Rebuild the record batch with the modified struct column
    let mut new_batch_columns = batch.columns().to_vec();
    new_batch_columns[primary_field_idx] = std::sync::Arc::new(new_struct_array);

    RecordBatch::try_new(std::sync::Arc::new(new_schema), new_batch_columns)
        .map_err(|e| Box::new(e) as Box<dyn std::error::Error>)
}

