/// of an input table and return a list of tuples where each tuple contains the value pair and its count.
fn compute_pair_frequencies(table: Vec<TableRow>) -> Vec<(ValuePair, usize)> {
    let mut frequency_map: HashMap<ValuePair, usize> = HashMap::new();
    let mut bloom_filter = Bloom::new(1000, 0.01); // Initialize a bloom filter

