# Rust Function: Group and Gather with Iterator Tools

```rust
use std::collections::HashMap;

/// Groups rows of a table-like dataset by values in column var0,
/// and for each group gathers entries from column var1 into a list.
///
/// # Arguments
/// * `df0` - A vector of tuples where each tuple represents a row (var0, var1)
///
/// # Returns
/// A HashMap where keys are var0 values and values are Vec of var1 entries
fn group_and_gather(df0: Vec<(String, String)>) -> HashMap<String, Vec<String>> {
    df0.into_iter()
        .fold(HashMap::new(), |mut acc, (var0, var1)| {
            acc.entry(var0)
                .or_insert_with(Vec::new)
                .push(var1);
            acc
        })
}

#[cfg(test)]
mod tests {
