```rust
use std::collections::HashMap;
use std::hash::Hash;

/// Generic version that works with any hashable key type and any value type
fn group_and_gather_generic<K, V>(data: Vec<(K, V)>) -> HashMap<K, Vec<V>>
where
    K: Hash + Eq,
{
    data.into_iter()
        .fold(HashMap::new(), |mut acc, (key, value)| {
