```rust
use chrono::{DateTime, Duration, Utc};
use std::cmp::Ordering;

/// Compute a time-based moving average over `values` using `timestamps` and a window of duration `window`.
///
/// - `timestamps`: slice of DateTime<Utc> (can be unsorted; the function sorts them internally and keeps alignment).
/// - `values`: slice of f64 values aligned with `timestamps`.
/// - `window`: chrono::Duration representing the length of the backward-looking window (e.g., Duration::seconds(60)).
///
/// Returns a Vec<Option<f64>> with the same length as the input; each element is the average of values
/// in the window ending at that timestamp. If there are no points in the window, the entry is None.
///
/// NaN behavior: values that are NaN are ignored (they are not counted in the average). If all values in a
/// window are NaN or the window is empty, result is None.
pub fn time_based_moving_average(
    timestamps: &[DateTime<Utc>],
    values: &[f64],
    window: Duration,
) -> Vec<Option<f64>> {
    assert_eq!(
        timestamps.len(),
        values.len(),
        "timestamps and values must have same length"
    );

    let n = timestamps.len();
    if n == 0 {
        return Vec::new();
    }

    // Create index vector and sort by timestamps so we work in temporal order.
    let mut idx: Vec<usize> = (0..n).collect();
    idx.sort_by(|&i, &j| timestamps[i].cmp(&timestamps[j]));

    // Build sorted arrays of timestamps and values
    let mut t_sorted: Vec<DateTime<Utc>> = Vec::with_capacity(n);
    let mut v_sorted: Vec<f64> = Vec::with_capacity(n);
    for &i in &idx {
        t_sorted.push(timestamps[i]);
        v_sorted.push(values[i]);
    }

    let mut out_sorted: Vec<Option<f64>> = vec![None; n];

    let mut left = 0usize;
    let mut sum = 0.0f64;
    let mut count = 0usize;

    for right in 0..n {
        // include the right value if it's not NaN
        let vr = v_sorted[right];
        if !vr.is_nan() {
            sum += vr;
            count += 1;
        }

        // window is [t_right - window, t_right] inclusive for points with timestamp >= start
        let start = t_sorted[right] - window;

        // move left forward while t_sorted[left] < start
        while left <= right && t_sorted[left].lt(&start) {
            let vl = v_sorted[left];
            if !vl.is_nan() {
                sum -= vl;
                count -= 1;
            }
            left += 1;
        }

        if count > 0 {
            out_sorted[right] = Some(sum / (count as f64));
        } else {
            out_sorted[right] = None;
        }
    }

    // Reorder results to original input order
    let mut result: Vec<Option<f64>> = vec![None; n];
    for (pos_sorted, &original_index) in idx.iter().enumerate() {
        result[original_index] = out_sorted[pos_sorted];
    }

    result
}

