///
/// let means = calculate_column_means(&data, &column_names);
/// assert_eq!(means.get("A").unwrap(), &5.0);
/// assert_eq!(means.get("B").unwrap(), &11.0);
/// ```
pub fn calculate_column_means(data: &Array2<f64>, column_names: &[String]) -> HashMap<String, f64> {
    // Group columns by their names
    let mut column_groups: HashMap<String, Vec<usize>> = HashMap::new();
    for (i, name) in column_names.iter().enumerate() {
        column_groups.entry(name.clone()).or_insert_with(Vec::new).push(i);
    }

    // Calculate means for each group
    let mut means = HashMap::new();
    for (name, indices) in column_groups {
        // Extract the columns for this group
        let columns: Vec<Array<f64, _>> = indices
            .iter()
            .map(|&col_idx| data.column(col_idx))
            .collect();

        // Stack the columns vertically to calculate mean across all values
        let stacked = ndarray::stack(ndarray::Axis(1), &columns).unwrap();

        // Calculate the mean
        let mean = stacked.mean().unwrap();
        means.insert(name, mean);
    }

    means
}

