use ndarray::{Array2, Axis};
use ndarray_stats::SummaryStatisticsExt;
use std::collections::HashMap;

/// Given a 2D numeric table `data` (rows x cols) and a slice of column names `col_names` (length == cols),
/// compute the mean of each group of columns that share the same name.
/// 
/// For a group of columns with the same name, the mean is the mean of all values across those columns
/// (equivalently, the average of the individual column means since all columns have the same number of rows).
/// If there are zero rows (empty data), the returned mean for each group is NaN.
///
/// Example:
/// let data = array![[1.0, 2.0, 4.0],
///                   [3.0, 4.0, 6.0]]; // 2 rows x 3 cols
/// let names = vec!["a", "a", "b"];
/// let means = grouped_column_means(&data, &names);
/// // means["a"] == (mean([1,3]) + mean([2,4])) / 2 = (2.0 + 3.0) / 2 = 2.5
/// // means["b"] == mean([4,6]) = 5.0
pub fn grouped_column_means(data: &Array2<f64>, col_names: &[&str]) -> HashMap<String, f64> {
    assert_eq!(
        data.ncols(),
        col_names.len(),
        "number of column names must equal number of columns in data"
    );

    // Group column indices by name
    let mut groups: HashMap<&str, Vec<usize>> = HashMap::new();
    for (j, &name) in col_names.iter().enumerate() {
        groups.entry(name).or_insert_with(Vec::new).push(j);
    }

    // For each group, compute mean across all columns in the group.
    // Use ndarray-stats mean() on each column (1-D view), then average those means.
    let mut result: HashMap<String, f64> = HashMap::new();
    for (name, indices) in groups {
        let mut sum_of_col_means = 0.0_f64;
        let mut valid_cols = 0_usize;
        for &col_idx in &indices {
            let col = data.index_axis(Axis(1), col_idx);
            match col.mean() {
                Some(m) => {
                    sum_of_col_means += m;
                    valid_cols += 1;
                }
                None => {
                    // empty column (e.g., zero rows) -> result is NaN for the group
                    sum_of_col_means = f64::NAN;
                    valid_cols = 0;
                    break;
                }
            }
        }

        let group_mean = if valid_cols == 0 {
            f64::NAN
        } else {
            sum_of_col_means / (valid_cols as f64)
        };
        result.insert(name.to_string(), group_mean);
    }

    result
}

