                    Value::from(series.get(row_idx)?)
                }
                DataType::Utf8 => {
                    let series = col_data.downcast_str()?;
                    Value::from(series.get(row_idx)?.to_string())
                }
                DataType::Boolean => {
                    let series = col_data.downcast_bool()?;
                    Value::from(series.get(row_idx)?)
                }
