use serde_value_map::ValueMap;
use serde_json::Value;
use std::collections::BTreeMap;

/// Represents a labeled tabular dataset
#[derive(Debug, Clone)]
pub struct DataFrame {
    /// Column names
    pub columns: Vec<String>,
    /// Row data, where each inner Vec represents a row's values
    pub data: Vec<Vec<Value>>,
    /// Optional row indices (if None, uses 0-based indexing)
    pub index: Option<Vec<Value>>,
}

/// Converts a DataFrame into a list of dictionaries, each containing the row's
/// index and column-value pairs.
///
/// # Arguments
/// * `df` - The DataFrame to convert
///
/// # Returns
/// * `Vec<ValueMap>` - A vector of ValueMaps, each representing one row
///
/// # Panics
/// * If any row has a different number of values than the number of columns
pub fn dataframe_to_dict_list(df: &DataFrame) -> Vec<ValueMap> {
    let num_columns = df.columns.len();
    let mut result = Vec::with_capacity(df.data.len());

    for (row_idx, row_values) in df.data.iter().enumerate() {
        if row_values.len() != num_columns {
            panic!(
                "Row {} has {} values, but expected {} (number of columns)",
                row_idx,
                row_values.len(),
                num_columns
            );
        }

        let mut row_map = ValueMap::new();

        // Add the row index
        let index_value = match &df.index {
            Some(indices) => {
                if row_idx < indices.len() {
                    indices[row_idx].clone()
                } else {
                    Value::Number((row_idx as u64).into())
                }
            }
            None => Value::Number((row_idx as u64).into()),
        };
        row_map.insert("index".to_string(), index_value);

        // Add column-value pairs
        for (col_idx, column_name) in df.columns.iter().enumerate() {
            row_map.insert(column_name.clone(), row_values[col_idx].clone());
        }

        result.push(row_map);
    }

    result
}

