/// let codes = assign_codes(&v); // -> [0, 1, 0, 2]
pub fn assign_codes<T: Eq + Hash + Clone>(lst0: &[T]) -> Vec<usize> {
    let mut map: HashMap<T, usize> = HashMap::new();
    let mut next_code: usize = 0;
    let mut codes = Vec::with_capacity(lst0.len());

    for item in lst0.iter().cloned() {
