fn assign_integer_codes(lst0: Vec<i32>) -> Vec<usize> {
    let mut element_to_code: HashMap<i32, usize> = HashMap::new();
    let mut next_code: usize = 0;
    let mut result: Vec<usize> = Vec::new();

    for &element in &lst0 {
        // If we haven't seen this element before, assign it a new code
        if !element_to_code.contains_key(&element) {
            element_to_code.insert(element, next_code);
            next_code += 1;
        }

        // Add the code for this element to the result
        result.push(*element_to_code.get(&element).unwrap());
    }

    result
}

