/// * `missing_value` - The value considered as missing (default is `f64::NAN`)
///
/// # Returns
/// A new 2D array with missing values replaced by column averages
pub fn replace_missing_with_column_means<T: Data + Copy + QuantileExt>(
    data: ArrayView2<T>,
    missing_value: T,
) -> Array2<T>
where
    T: PartialEq + std::ops::Add<Output = T> + std::ops::Div<Output = T> + std::ops::Sub<Output = T>,
    <T as QuantileExt>::Statistics: Default,
{
    // Get dimensions
    let (rows, cols) = data.shape();

    // Create a new array for the result
    let mut result = Array2::zeros((rows, cols));

    // For each column
    for col in 0..cols {
        // Extract the column
        let column = data.column(col);

        // Count non-missing values and sum them
        let (sum, count): (T, usize) = column
            .iter()
            .fold((T::zero(), 0), |(sum, count), &val| {
                if val != missing_value {
                    (sum + val, count + 1)
                } else {
                    (sum, count)
                }
