/// Replace missing entries (Option::None) in each column with the column's mean
/// computed over non-missing values. Columns that are entirely missing are filled
/// with NaN.
///
/// - Input: 2-D Array of Option<f64> (missing values represented by None)
/// - Output: 2-D Array of f64 with missing entries replaced by column means.
///
/// Requires the `ndarray` and `ndarray-stats` crates.
///
/// Example:
/// ```
/// use ndarray::array;
/// let a = array![
///     [Some(1.0), None,      Some(5.0)],
///     [Some(2.0), Some(3.0), None     ],
///     [None,      Some(7.0), Some(9.0)],
/// ];
/// let imputed = impute_column_means(&a);
/// // imputed =
/// // [[1.0, 5.0, 5.0],
/// //  [2.0, 3.0, 7.0],
/// //  [1.5, 7.0, 9.0]]
/// ```
pub fn impute_column_means(input: &Array2<Option<f64>>) -> Array2<f64> {
    let (nrows, ncols) = input.dim();

    // Compute mean for each column using ndarray-statistics
    let mut col_means = Vec::with_capacity(ncols);
    for j in 0..ncols {
        let col = input.index_axis(Axis(1), j);
        // collect non-missing values
        let vals: Vec<f64> = col.iter().filter_map(|opt| *opt).collect();

        let mean = if !vals.is_empty() {
            // Use SummaryStatisticsExt::mean from ndarray-stats
            Array1::from(vals).mean().unwrap_or(f64::NAN)
        } else {
            // If the whole column is missing, use NaN
            f64::NAN
        };
        col_means.push(mean);
    }

    // Build output array, replacing None with the computed column mean
    let mut out = Array2::<f64>::zeros((nrows, ncols));
    for i in 0..nrows {
        for j in 0..ncols {
            out[(i, j)] = input[(i, j)].unwrap_or(col_means[j]);
        }
    }

    out
}

