use ndarray::{Array2, Array1};
use ndarray_stats::QuantileExt;
use std::f64::NAN;

/// Imputes missing values in a 2D dataset by replacing them with the column mean.
/// 
/// Missing values are represented as NaN. This function calculates the mean of
/// non-missing values in each column and uses those means to fill in the NaN entries.
/// 
/// # Arguments
/// * `data` - A 2D array where missing values are represented as NaN
/// 
/// # Returns
/// A new 2D array with NaN values replaced by their respective column means
/// 
/// # Panics
/// Panics if a column contains only NaN values (no mean can be computed)
pub fn impute_missing_with_column_mean(data: &Array2<f64>) -> Array2<f64> {
    let mut result = data.clone();

    // Iterate over each column
    for col_idx in 0..data.ncols() {
        let column = data.column(col_idx);

        // Filter out NaN values and compute mean
        let non_nan_values: Vec<f64> = column
            .iter()
            .filter(|&&x| !x.is_nan())
            .copied()
            .collect();

        if non_nan_values.is_empty() {
            panic!("Column {} contains only NaN values, cannot compute mean", col_idx);
        }

        // Compute the mean using ndarray-statistics
        let mean = non_nan_values.iter().sum::<f64>() / non_nan_values.len() as f64;

        // Replace NaN values with the mean
        for row_idx in 0..data.nrows() {
            if result[[row_idx, col_idx]].is_nan() {
                result[[row_idx, col_idx]] = mean;
            }
        }
    }

    result
}

