use cgmath::{BaseFloat, Zero};

/// Compute the Euclidean (straight-line) distance between two points in N-dimensional space.
///
/// - `a` and `b` are slices containing the coordinates of the two points.
/// - Returns `None` if the slices have different lengths, otherwise returns the distance as `T`.
///
/// Example:
/// ```
/// let p = [1.0f32, 2.0, 3.0];
/// let q = [4.0f32, 6.0, 3.0];
/// let d = euclidean_distance(&p, &q).unwrap();
/// assert!((d - 5.0).abs() < 1e-6);
/// ```
pub fn euclidean_distance<T>(a: &[T], b: &[T]) -> Option<T>
where
    T: BaseFloat + Zero + Copy,
{
    if a.len() != b.len() {
        return None;
    }

    let mut sum = T::zero();
    for (&x, &y) in a.iter().zip(b.iter()) {
        let d = x - y;
        sum = sum + d * d;
    }

    Some(sum.sqrt())
}

