/// Minimal SortedVec: keeps elements sorted according to a comparator.
/// We store the comparator as a boxed Fn so it can be customized per instance.
struct SortedVec<T> {
    v: Vec<T>,
    cmp: Box<dyn Fn(&T, &T) -> Ordering>,
}

impl<T> SortedVec<T> {
    /// Create a new SortedVec with the provided comparator.
    fn new<F>(cmp: F) -> Self
    where
        F: Fn(&T, &T) -> Ordering + 'static,
    {
        SortedVec {
            v: Vec::new(),
            cmp: Box::new(cmp),
        }
    }

    /// Insert an item while maintaining sorted order (binary search + insert).
    fn insert(&mut self, item: T) {
        let pos = self
            .v
            .binary_search_by(|x| (self.cmp)(x, &item))
            .unwrap_or_else(|e| e);
        self.v.insert(pos, item);
    }

    /// Consume and return the underlying Vec (sorted).
    fn into_vec(self) -> Vec<T> {
        self.v
    }
}

