///
/// If an element from `seq0` is not found in `seq1`.
pub fn find_positions<T: Eq + std::hash::Hash + Copy>(seq0: &[T], seq1: &[T]) -> Vec<usize> {
    // Create a map to store the positions of elements in seq1
    let mut pos_map: HashMap<T, usize> = HashMap::new();
