```rust
use csv::{ReaderBuilder, WriterBuilder};
use std::fs::File;
use std::path::Path;

/// Filter rows from a tabular dataset where the value in a specified column
/// is not contained in a given list.
///
/// # Arguments
///
/// * `input_file` - Path to the input CSV file.
/// * `output_file` - Path to the output CSV file.
/// * `column_name` - Name of the column to filter on.
/// * `values_to_keep` - List of values to keep in the specified column.
fn filter_rows(
    input_file: &str,
    output_file: &str,
    column_name: &str,
    values_to_keep: Vec<String>,
) -> csv::Result<()> {
    let input_path = Path::new(input_file);
    let output_path = Path::new(output_file);

    let mut reader = ReaderBuilder::new()
        .has_headers(true)
        .from_reader(File::open(input_path).unwrap());

    let mut writer = WriterBuilder::new()
        .from_writer(File::create(output_path).unwrap());

    let headers = reader.headers()?;
    let column_index = headers
        .iter()
        .position(|h| h == &column_name)
        .expect("Column not found");

    writer.write_record(headers)?;

    for result in reader.records() {
        let record = result?;
        let value = record.get(column_index).expect("Column index out of bounds");

        if values_to_keep.contains(&value.to_string()) {
            writer.write_record(&record)?;
        }
    }

    Ok(())
}

