/// assert_eq!(filtered.shape(), &[2, 3]);
/// assert_eq!(filtered[[0, 0]], 1.0);
/// assert_eq!(filtered[[1, 0]], 4.0);
/// ```
pub fn filter_nonzero_rows(df0: &Array2<f64>) -> Array2<f64> {
    // Get the number of columns from the input array
    let ncols = df0.ncols();

    // Collect rows that have non-zero sums
    let filtered_rows: Vec<Vec<f64>> = df0
        .rows()
        .into_iter()
        .filter(|row| {
            // Calculate the sum of elements in this row
            let row_sum: f64 = row.iter().sum();
            // Keep rows where the sum is not zero (using a small epsilon for floating point comparison)
            row_sum.abs() > f64::EPSILON
        })
        .map(|row| row.to_vec())
        .collect();

    // Get the number of rows that passed the filter
    let nrows = filtered_rows.len();

    // If no rows passed the filter, return an empty array with the correct number of columns
    if nrows == 0 {
        return Array2::from_shape_vec((0, ncols), vec![]).unwrap();
    }

    // Flatten the filtered rows into a single vector
    let flat_data: Vec<f64> = filtered_rows.into_iter().flatten().collect();

    // Create and return the new 2D array
    Array2::from_shape_vec((nrows, ncols), flat_data).unwrap()
}

