use ndmatrix::NDMatrix;

fn filter_rows_by_nonzero_sum(df0: &NDMatrix<f64>) -> NDMatrix<f64> {
    let rows = df0.rows();
    let cols = df0.cols();

    // Collect row indices where sum is non-zero
    let valid_rows: Vec<usize> = (0..rows)
        .filter(|&row_idx| {
            let row_sum: f64 = (0..cols)
                .map(|col_idx| df0.get(row_idx, col_idx).unwrap_or(0.0))
                .sum();
            row_sum != 0.0
        })
        .collect();

    // Create a new matrix with only valid rows
    let mut result = NDMatrix::new(valid_rows.len(), cols, 0.0);

    for (new_row_idx, &old_row_idx) in valid_rows.iter().enumerate() {
        for col_idx in 0..cols {
            if let Some(&value) = df0.get(old_row_idx, col_idx) {
                result.set(new_row_idx, col_idx, value);
            }
        }
    }

    result
}

// Example usage:
