        let mut df0 = NDMatrix::new(4, 3, 0.0);

        // Row 0: [1.0, 2.0, 3.0] -> sum = 6.0 (non-zero, keep)
        df0.set(0, 0, 1.0);
        df0.set(0, 1, 2.0);
        df0.set(0, 2, 3.0);

        // Row 1: [0.0, 0.0, 0.0] -> sum = 0.0 (zero, filter out)

        // Row 2: [1.0, -1.0, 0.0] -> sum = 0.0 (zero, filter out)
        df0.set(2, 0, 1.0);
        df0.set(2, 1, -1.0);

