        df0.set(3, 0, 2.0);
        df0.set(3, 1, 3.0);
        df0.set(3, 2, 4.0);

        let result = filter_rows_by_nonzero_sum(&df0);

        // Result should have 2 rows (rows 0 and 3 from original)
        assert_eq!(result.rows(), 2);
        assert_eq!(result.cols(), 3);
    }
}
