/// A runtime type specification that determines the element type of the output sequence.
/// Add variants as needed for other target element types.
#[derive(Debug, Clone, Copy)]
pub enum TypeSpec {
    Str,
    I64,
    F64,
    Bool,
}

/// Homogeneous tuple element types. Every element in the result Vec will be one of these variants.
/// Each variant stores (key, value) with the value converted to the indicated type.
#[derive(Debug, Clone)]
pub enum OutputTuple {
    StrStr(String, String),
    StrI64(String, i64),
    StrF64(String, f64),
    StrBool(String, bool),
}

/// Error information returned when one or more conversions fail.
#[derive(Debug)]
pub enum MapError {
    ParseErrors(Vec<(String, String)>), // (key, error message)
}

/// Transform a key->string-value map into a homogeneous Vec of two-element tuples.
/// The element type is chosen by `type_spec`.
///
/// - input: map from key -> value (both strings).
/// - type_spec: chosen target type for the values in the output tuples.
/// Returns Ok(vec) on success, or Err(MapError::ParseErrors) with the failed keys and messages.
pub fn map_kv_to_sequence(
    input: &HashMap<String, String>,
    type_spec: TypeSpec,
) -> Result<Vec<OutputTuple>, MapError> {
    let mut out = Vec::with_capacity(input.len());
    let mut errs: Vec<(String, String)> = Vec::new();

    for (k, v) in input.iter() {
        match type_spec {
            TypeSpec::Str => {
                out.push(OutputTuple::StrStr(k.clone(), v.clone()));
            }
            TypeSpec::I64 => match v.parse::<i64>() {
                Ok(n) => out.push(OutputTuple::StrI64(k.clone(), n)),
                Err(e) => errs.push((k.clone(), format_parse_err(&e))),
            },
            TypeSpec::F64 => match v.parse::<f64>() {
                Ok(f) => out.push(OutputTuple::StrF64(k.clone(), f)),
                Err(e) => errs.push((k.clone(), format_parse_err(&e))),
            },
            TypeSpec::Bool => match v.parse::<bool>() {
                Ok(b) => out.push(OutputTuple::StrBool(k.clone(), b)),
                Err(e) => errs.push((k.clone(), format_parse_err(&e))),
            },
        }
    }

    if errs.is_empty() {
        Ok(out)
    } else {
        Err(MapError::ParseErrors(errs))
    }
}

fn format_parse_err<E: std::fmt::Display>(e: &E) -> String {
    format!("{}", e)
}

