/// map.insert("b", 2);
///
/// let result: Vec<(&str, i32)> = map_to_tuples(map);
/// assert_eq!(result.len(), 2);
/// ```
fn map_to_tuples<K, V>(map: HashMap<K, V>) -> Vec<(K, V)>
where
    K: Clone,
    V: Clone,
{
    map.into_iter().collect()
}

