            DataType::Int8
                | DataType::Int16
                | DataType::Int32
                | DataType::Int64
                | DataType::UInt8
                | DataType::UInt16
                | DataType::UInt32
                | DataType::UInt64
                | DataType::Float32
                | DataType::Float64
        ))
        .map(|f| f.name().clone())
        .collect();

    // Build aggregation expressions: for each numeric column, compute mean and alias as "<col>_mean".
    let mut aggs: Vec<Expr> = Vec::with_capacity(numeric_cols.len());
    for col_name in numeric_cols {
        aggs.push(col(&col_name).mean().alias(&format!("{}_mean", col_name)));
