use num_bigint::BigInt;
use num_traits::Zero;

/// Concatenate the decimal digits of each integer in `nums` (in order) into a single BigInt.
///
/// Notes:
/// - Negative signs are ignored (the absolute digit sequences are concatenated).
/// - An empty slice returns 0.
///
/// Example:
/// let v = vec![12, 34, 5];
/// let r = concat_digits(&v); // r == 12345 (as BigInt)
pub fn concat_digits<T: ToString>(nums: &[T]) -> BigInt {
    let ten = BigInt::from(10u32);
    let mut acc = BigInt::zero();

    for item in nums {
        let mut s = item.to_string();
        // strip leading '-' if any (we only concatenate digit sequences)
        if let Some(rest) = s.strip_prefix('-') {
            s = rest.to_string();
        }

        if s.is_empty() {
            continue;
        }

        let len = s.len() as u32;
        let pow10 = ten.pow(len);
        let segment = BigInt::parse_bytes(s.as_bytes(), 10).unwrap_or_else(|| BigInt::zero());

        acc = acc * pow10 + segment;
    }

    acc
}

