use fast_float::parse;

/// Sort a slice of strings by their floating-point value (ascending).
/// Strings that fail to parse are treated as NaN and placed after all valid numbers.
///
/// Input: slice of Strings (or &String)
/// Returns: a new Vec<String> sorted by numeric value
pub fn sort_by_float_strings(lst0: &[String]) -> Vec<String> {
    // Pair each original string with its parsed f64 value (or NaN on parse failure)
    let mut items: Vec<(String, f64)> = lst0
        .iter()
        .map(|s| {
            // fast_float::parse parses from bytes; return NaN on error
            let v = parse::<f64>(s.as_bytes()).unwrap_or(f64::NAN);
            (s.clone(), v)
        })
        .collect();

    // Sort by the parsed value. Put NaNs at the end.
    items.sort_by(|a, b| {
        match (a.1.is_nan(), b.1.is_nan()) {
            (true, true) => std::cmp::Ordering::Equal,
            (true, false) => std::cmp::Ordering::Greater,
            (false, true) => std::cmp::Ordering::Less,
            (false, false) => a.1.total_cmp(&b.1),
        }
    });

    // Return the original strings in the new order
    items.into_iter().map(|(s, _)| s).collect()
}

