use ordered_map::OrderedMap;
use std::cmp::Ordering;

fn sort_by_position<K, V>(map: &OrderedMap<K, Vec<V>>, position: usize) -> OrderedMap<K, Vec<V>>
where
    K: Ord + Clone,
    V: PartialOrd + Clone,
{
    // Collect the key-value pairs into a vector for sorting
    let mut entries: Vec<(K, Vec<V>)> = map.iter().map(|(k, v)| (k.clone(), v.clone())).collect();

