        let b_value = b.1.get(position);

        match (a_value, b_value) {
            (Some(a_val), Some(b_val)) => a_val.partial_cmp(b_val).unwrap_or(Ordering::Equal),
            (None, Some(_)) => Ordering::Greater,
            (Some(_), None) => Ordering::Less,
            (None, None) => Ordering::Equal,
        }
    });

