    let mut entries: Vec<(K, Vec<T>)> = map.drain().collect();

    // Sort by the element at the specified position
    entries.sort_by(|(_, seq_a), (_, seq_b)| {
        let elem_a = seq_a.get(position).expect("Sequence too short for specified position");
        let elem_b = seq_b.get(position).expect("Sequence too short for specified position");
        elem_a.cmp(elem_b)
    });

    // Re-insert sorted entries
    for (key, value) in entries {
        map.insert(key, value);
    }
}

/// Alternative version that returns a new sorted OrderedMap without modifying the original
pub fn sorted_by_sequence_position<K, V, T>(map: &OrderedMap<K, Vec<T>>, position: usize) -> OrderedMap<K, Vec<T>>
where
    K: Ord + Clone,
    V: Ord + Clone,
    T: Ord + Clone,
{
    let mut entries: Vec<(&K, &Vec<T>)> = map.iter().collect();

    entries.sort_by(|(_, seq_a), (_, seq_b)| {
        let elem_a = seq_a.get(position).expect("Sequence too short for specified position");
        let elem_b = seq_b.get(position).expect("Sequence too short for specified position");
        elem_a.cmp(elem_b)
    });

    let mut result = OrderedMap::new();
    for (key, value) in entries {
        result.insert((*key).clone(), (*value).clone());
    }
    result
}

