/// Apply `func` to each element of `df0`, iterating along `axis`.
///
/// - `axis == 0`: iterate column-by-column (vary row fastest within each column)
/// - `axis == 1`: iterate row-by-row (vary column fastest within each row)
///
/// Returns a new Matrix<f64> with the same shape as `df0` where each element
/// has been replaced by `func(original_value)`.
///
/// Panics if `axis` is not 0 or 1.
pub fn apply_func_along_axis<F>(df0: &Matrix<f64>, axis: usize, mut func: F) -> Matrix<f64>
where
    F: FnMut(f64) -> f64,
{
    let rows = df0.rows();
    let cols = df0.cols();

    if axis != 0 && axis != 1 {
        panic!("axis must be 0 or 1, got {}", axis);
    }

    // Output buffer in row-major order (Matrix::new expects row-major data)
    let mut out_data = vec![0.0f64; rows * cols];

    if axis == 0 {
        // Column-major traversal: for each column, iterate rows
        for c in 0..cols {
            for r in 0..rows {
                // index into underlying row-major layout
                // out_data[r*cols + c] is the element at (r, c)
                let val = df0[(r, c)];
                out_data[r * cols + c] = func(val);
