///           0 = iterate over rows (apply func to each row)
///           1 = iterate over columns (apply func to each column)
/// * `func` - A closure that takes a vector and returns a value
/// 
/// # Returns
/// A vector containing the results of applying func to each element along the axis
fn apply_along_axis<F, T>(df0: &Matrix<f64>, var0: usize, func: F) -> Vec<T>
where
    F: Fn(Vec<f64>) -> T,
{
    match var0 {
        0 => {
            // Iterate over rows
            df0.iter_rows()
                .map(|row| func(row.iter().copied().collect()))
                .collect()
        }
        1 => {
            // Iterate over columns
            df0.iter_cols()
                .map(|col| func(col.iter().copied().collect()))
                .collect()
        }
        _ => panic!("Invalid axis: {}. Must be 0 (rows) or 1 (columns).", var0),
    }
}

