            4.0, 5.0, 6.0,
            7.0, 8.0, 9.0,
        ]);

        // Sum each row
        let sums = apply_along_axis(&matrix, 0, |row| row.iter().sum::<f64>());
        assert_eq!(sums, vec![6.0, 15.0, 24.0]);
