use tch::{Kind, Tensor, TchError, Result as TchResult};

/// Compare two tensors elementwise and return a Vec<bool> indicating equality at each position.
///
/// Both tensors must have the same shape.
///
/// Example:
/// let a = Tensor::of_slice(&[1i64, 2, 3]);
/// let b = Tensor::of_slice(&[1i64, 0, 3]);
/// let eqs = elementwise_equal_bools(&a, &b)?;
/// assert_eq!(eqs, vec![true, false, true]);
pub fn elementwise_equal_bools(a: &Tensor, b: &Tensor) -> TchResult<Vec<bool>> {
    // Check shapes match
    let a_size = a.size();
    let b_size = b.size();
    if a_size != b_size {
        return Err(TchError::Kind(format!(
            "shape mismatch: {:?} vs {:?}",
            a_size, b_size
        )));
    }

    // Elementwise equality -> tensor of 0/1 (or booleans depending on backend)
    // Use eq_tensor to compare two tensors (elementwise).
    let eq_tensor = a.eq_tensor(b);

    // Convert to a byte tensor (Uint8) so we can extract values as u8.
    let eq_u8 = eq_tensor.to_kind(Kind::Uint8);

    // Convert the tensor into a Vec<u8> and map nonzero -> true.
    // Vec::from(Tensor) converts the flattened tensor data into the requested element type.
    let bytes: Vec<u8> = Vec::from(eq_u8);
    Ok(bytes.into_iter().map(|v| v != 0).collect())
}

