/// let mut elements = vec![String::from("apple"), String::from("orange"), String::from("banana")];
/// let positions = Some(vec![0, 2]);
/// sort_elements(&mut elements, positions);
/// assert_eq!(elements, vec![String::from("orange"), String::from("banana"), String::from("apple")]);
/// ```
fn sort_elements(elements: &mut Vec<String>, positions: Option<Vec<usize>>) {
    let mut descending_indices = positions.unwrap_or_else(|| vec![]);

    // Create a boolean vector to keep track of which indices to sort descending
    let mut to_descend = vec![false; elements.len()];

    for &pos in &descending_indices {
        if pos < elements.len() {
            to_descend[pos] = true;
        }
    }

    // Sort all elements
    pdqsort(elements);

    // Sort specified positions in descending order
    let mut descending_elements: Vec<String> = descending_indices
        .iter()
        .filter_map(|&pos| elements.get(pos).cloned())
        .collect();

    pdqsort(&mut descending_elements);
    descending_elements.reverse();  // Reverse to get descending order

    // Place sorted descending elements back into the original vector
    for (i, &pos) in descending_indices.iter().enumerate() {
        if pos < elements.len() {
            elements[pos] = descending_elements[i].clone();
        }
    }
}

