    let mut indices: Vec<usize> = (0..texts.len()).collect();

    // Define a custom comparator
    let comparator = |i: &usize, j: &usize| {
        let pos_i = positions.map_or(false, |pos| pos.contains(i));
        let pos_j = positions.map_or(false, |pos| pos.contains(j));

        if pos_i && pos_j {
            // Both in positions - descending
            texts[*i].cmp(texts[*j]).reverse()
        } else if pos_i {
            // Only i in positions - i should come after
            texts[*i].cmp(texts[*j]).reverse()
        } else if pos_j {
            // Only j in positions - j should come after
            texts[*j].cmp(texts[*i]).reverse()
        } else {
            // Neither in positions - ascending
            texts[*i].cmp(texts[*j])
        }
    };

    // Use pdqsorter for better performance
    PdqSorter::new()
        .with_comparator(&comparator)
        .sort(&mut indices);

    // Create the sorted result
    indices.into_iter()
        .map(|i| texts[i])
        .collect()
}

