/// Sorts `items` using pdqsort. By default sorts ascending. If `positions` is Some(vec),
/// elements that were originally at those indices are compared with reverse ordering
/// when both compared elements are marked; otherwise comparisons are ascending.
/// Out-of-range indices in `positions` are ignored.
///
/// Returns a newly sorted Vec<String>.
pub fn sort_texts_pdq(mut items: Vec<String>, positions: Option<Vec<usize>>) -> Vec<String> {
    // Pair each item with its original index so we can detect which were requested as "descending".
    let mut paired: Vec<(usize, String)> = items.into_iter().enumerate().collect();

    match positions {
        None => {
            // Sort all ascending by text
            pdqsort::sort_by(&mut paired, |a, b| a.1.cmp(&b.1));
        }
        Some(pos_vec) => {
            // Build a set of valid indices (ignore out-of-bounds indices)
            let len = paired.len();
            let desc_set: HashSet<usize> = pos_vec.into_iter().filter(|&i| i < len).collect();

