        .unwrap_or_default()
        .into_iter()
        .filter(|&pos| pos < texts.len())
        .collect();

    if desc_set.is_empty() {
        pdqsort::sort(texts);
    } else {
        // Create index array to track original positions
        let mut indexed: Vec<(usize, &str)> = texts
            .iter()
            .enumerate()
            .map(|(i, &text)| (i, text))
            .collect();

