    // in a max-heap (BinaryHeap). The heap keeps the k largest values seen so far.
    let mut heap: BinaryHeap<Reverse<(T, usize)>> = BinaryHeap::new();

    for (i, v) in lst0.iter().cloned().enumerate() {
        if heap.len() < k {
            heap.push(Reverse((v, i)));
        } else if let Some(Reverse((smallest_val, _))) = heap.peek() {
            if &v > smallest_val {
                // new value is larger than current smallest among top-k -> replace it
                heap.pop();
                heap.push(Reverse((v, i)));
            }
