///     vec![1, 10],
///     vec![4, 20],
///     vec![2, 30],
///     vec![3, 50],
/// ]);
/// ```
fn insert_sorted_sublist(list: &mut Vec<Vec<i32>>, new_sublist: Vec<i32>) {
