fn strip_currency_and_convert(table: &mut Vec<Vec<String>>) -> Result<Vec<Vec<f64>>, Box<dyn Error>> {
    // Ensure there's at least two columns
    if table.is_empty() || table[0].len() < 2 {
        return Err("The table must have at least two columns".into());
    }

    let penultimate_col_index = table[0].len() - 2;
    let mut result = Vec::new();

    for row in table.iter() {
        let mut new_row = row.clone();
        if let Some(value) = new_row.get_mut(penultimate_col_index) {
