use datafusion::arrow::datatypes::Schema;
use datafusion::arrow::record_batch::RecordBatch;
use datafusion::error::Result;
use std::sync::Arc;

async fn unpivot(df0: DataFrame, lst0: Vec<&str>, var0: &str, var1: &str) -> Result<DataFrame> {
    let session_ctx = SessionContext::new();

    // Get the schema of the original DataFrame
    let schema = df0.schema();

    // Collect columns that will remain unchanged
    let fixed_columns: Vec<&Field> = schema.fields().iter()
        .filter(|field| !lst0.contains(&field.name().as_str()))
        .collect();

    // Create a new DataFrame for each column to be unpivoted
    let mut unpivoted_dfs = vec![];

    for col_name in lst0 {
        // Create a new column for the variable names
        let var0_lit = lit(col_name).alias(var0);

        // Select the fixed columns and the current column to unpivot
        let unpivoted_df = df0.clone()
