            let str_iter = column.utf8()
                .map_err(|e| PolarsError::ComputeError(format!("Failed to read string column: {}", e).into()))?;

            for opt_val in str_iter.into_iter() {
                match opt_val {
                    Some(val) => *freq_map.entry(val.to_string()).or_insert(0) += 1,
                    None => *freq_map.entry("null".to_string()).or_insert(0) += 1,
                }
            }
        },
        DataType::Int64 => {
            let int_iter = column.i64()
                .map_err(|e| PolarsError::ComputeError(format!("Failed to read int64 column: {}", e).into()))?;

            for opt_val in int_iter.into_iter() {
                match opt_val {
