                    None => *freq_map.entry("null".to_string()).or_insert(0) += 1,
                }
            }
        },
        DataType::Float64 => {
            let float_iter = column.f64()
                .map_err(|e| PolarsError::ComputeError(format!("Failed to read float64 column: {}", e).into()))?;

            for opt_val in float_iter.into_iter() {
                match opt_val {
                    Some(val) => *freq_map.entry(val.to_string()).or_insert(0) += 1,
                    None => *freq_map.entry("null".to_string()).or_insert(0) += 1,
                }
            }
        },
        DataType::Boolean => {
            let bool_iter = column.bool()
                .map_err(|e| PolarsError::ComputeError(format!("Failed to read boolean column: {}", e).into()))?;

            for opt_val in bool_iter.into_iter() {
                match opt_val {
                    Some(val) => *freq_map.entry(val.to_string()).or_insert(0) += 1,
                    None => *freq_map.entry("null".to_string()).or_insert(0) += 1,
                }
            }
        },
        _ => {
            // For other types, convert to string representation
            let str_series = column.cast(&DataType::Utf8)
                .map_err(|e| PolarsError::ComputeError(format!("Failed to convert column to string: {}", e).into()))?;

            let str_iter = str_series.utf8()
                .map_err(|e| PolarsError::ComputeError(format!("Failed to read converted string column: {}", e).into()))?;

            for opt_val in str_iter.into_iter() {
                match opt_val {
                    Some(val) => *freq_map.entry(val.to_string()).or_insert(0) += 1,
                    None => *freq_map.entry("null".to_string()).or_insert(0) += 1,
                }
            }
        }
    }

