/// let cols = vec![0, 1];
/// let sorted = sort_by_columns(&data, &cols);
/// assert_eq!(sorted, vec![vec![1,3], vec![2,0], vec![2,1]]);
pub fn sort_by_columns<T: Ord + Clone>(
    data0: &[Vec<T>],
    col0: &[usize],
) -> Vec<Vec<T>> {
    // Enumerate to preserve stability on ties by using original index as final tie-breaker.
    data0
        .iter()
        .cloned()
        .enumerate()
        .sorted_by(|(i, a), (j, b)| {
            for &col in col0 {
                match (a.get(col), b.get(col)) {
                    (Some(x), Some(y)) => match x.cmp(y) {
                        Ordering::Less => return Ordering::Less,
                        Ordering::Greater => return Ordering::Greater,
                        Ordering::Equal => continue,
                    },
                    // Define ordering when one row is missing the column:
                    // row missing the column is considered smaller.
                    (None, Some(_)) => return Ordering::Less,
                    (Some(_), None) => return Ordering::Greater,
                    (None, None) => continue,
                }
            }
            // All specified columns equal -> preserve original order
            i.cmp(j)
        })
        .map(|(_, row)| row)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_sort() {
        let data = vec![
            vec![2, 1],
            vec![1, 3],
            vec![2, 0],
            vec![2], // shorter row
        ];
        let cols = vec![0, 1];
        let sorted = sort_by_columns(&data, &cols);
        assert_eq!(
            sorted,
            vec![vec![1, 3], vec![2], vec![2, 0], vec![2, 1]]
        );
    }
}

