/// # Returns
/// * A new vector of vectors with the sorted data
///
/// # Panics
/// * If any column index in `col0` is out of bounds for any row
/// * If rows have inconsistent lengths
fn sort_by_columns(data0: Vec<Vec<i32>>, col0: Vec<usize>) -> Vec<Vec<i32>> {
