    if let Some(first_row_len) = data0.first().map(|row| row.len()) {
        for (row_idx, row) in data0.iter().enumerate() {
            assert_eq!(
                row.len(), first_row_len,
                "Row {} has length {}, expected {}",
                row_idx, row.len(), first_row_len
