fn extract_elements<T>(arr0: &DVector<T>, condition: impl Fn(&T) -> bool) -> DVector<T>
where
    T: Clone + nalgebra::Scalar,
{
    let filtered: Vec<T> = arr0
        .iter()
        .filter(|element| condition(element))
        .cloned()
        .collect();

    DVector::from_vec(filtered)
}

