/// Extract a contiguous slice of columns from `df0`.
///
/// This function returns a new Matrix containing columns start_column0 ..= end_column0 (inclusive).
/// Panics if start_column0 > end_column0 or end_column0 is >= df0.ncols().
///
/// Notes / assumptions about the lineargebra API used here:
/// - `Matrix<T>` supports `nrows()` and `ncols()` methods returning usize.
/// - `Matrix<T>` supports indexing by `(row, col)` as `&T` via `matrix[(r, c)]`.
/// - `Matrix::from_vec(rows, cols, Vec<T>)` exists and consumes a Vec in row-major order.
///
/// If your version of lineargebra uses slightly different method names (for example `rows()` / `cols()`
/// or `get((r, c))` / `set((r, c), val)`), adjust the calls below accordingly.
pub fn extract_column_slice<T: Clone>(
    df0: &Matrix<T>,
    start_column0: usize,
    end_column0: usize,
) -> Matrix<T> {
    assert!(
        start_column0 <= end_column0,
        "start_column0 must be <= end_column0"
    );
    let nrows = df0.nrows();
    let ncols = df0.ncols();
    assert!(
        end_column0 < ncols,
        "end_column0 out of bounds (got {}, but ncols = {})",
        end_column0,
        ncols
    );

    let out_cols = end_column0 - start_column0 + 1;
    let mut data: Vec<T> = Vec::with_capacity(nrows * out_cols);

    // Collect data column by column into row-major order for the output matrix.
    for r in 0..nrows {
        for c in start_column0..=end_column0 {
            data.push(df0[(r, c)].clone());
        }
    }

    Matrix::from_vec(nrows, out_cols, data)
}

