use std::collections::HashMap;

/// Assigns unique integer codes to distinct values in two columns
/// 
/// # Arguments
/// * `var0` - Vector of values for the first column
/// * `var1` - Vector of values for the second column
/// 
/// # Returns
/// A tuple containing two vectors of integer codes (lst0, lst1)
fn assign_codes<T: Eq + std::hash::Hash + Clone>(
    var0: Vec<T>,
    var1: Vec<T>,
) -> (Vec<usize>, Vec<usize>) {
    let mut code_map: HashMap<T, usize> = HashMap::new();
    let mut next_code = 0;

    let mut lst0 = Vec::new();
    let mut lst1 = Vec::new();

    // Process var0
    for value in var0 {
        let code = *code_map.entry(value).or_insert_with(|| {
            let code = next_code;
            next_code += 1;
            code
        });
        lst0.push(code);
    }

    // Process var1
    for value in var1 {
        let code = *code_map.entry(value).or_insert_with(|| {
            let code = next_code;
            next_code += 1;
            code
        });
        lst1.push(code);
    }

    (lst0, lst1)
}

