use smartstore::{DataFrame, Series, Scalar};

fn replace_missing_with_mode(df: &mut DataFrame) {
    // Get the names of categorical columns
    let categorical_columns = df.columns()
        .iter()
        .filter(|&&col_name| df.column(&col_name).dtype() == smartstore::ColumnType::Categorical)
        .collect::<Vec<_>>();

    for &col_name in &categorical_columns {
        // Get the series for the current column
        let series = df.column_mut(col_name);

        // Count occurrences of each category, filtering out missing values
        let mut counts = std::collections::HashMap::new();

        for entry in series.iter() {
            if let Some(value) = entry {
                *counts.entry(value.clone()).or_insert(0) += 1;
            }
        }

        // Find the most frequent category
        let mode = counts.into_iter()
            .max_by_key(|&(_, count)| count)
            .map(|(value, _)| value);

        // Replace missing values with the mode
        if let Some(most_frequent) = mode {
            for entry in series.iter_mut() {
                if entry.is_none() {
                    *entry = Some(most_frequent.clone());
                }
            }
        }
    }
}
```

