use twoway;

/// Replace the second whole-word occurrence of "cat" with "Bull,".
/// Word boundaries are determined by ASCII/Unicode alphanumeric characters and underscore:
/// a "word" character is c.is_alphanumeric() || c == '_'.
///
/// Returns the modified string (original string if there are fewer than two whole-word "cat" occurrences).
pub fn replace_second_cat(input: &str) -> String {
    let needle = "cat";
    let needle_len = needle.len();
    let mut count = 0usize;
    let mut search_start = 0usize;

    while search_start <= input.len() {
        match twoway::find_str(&input[search_start..], needle) {
            Some(rel_pos) => {
                let start = search_start + rel_pos;
                let end = start + needle_len;

                // Check previous character (if any) is not a "word" char
                let prev_is_word = if start == 0 {
                    false
                } else {
                    input[..start]
                        .chars()
                        .rev()
                        .next()
                        .map(|c| c.is_alphanumeric() || c == '_')
                        .unwrap_or(false)
                };

                // Check next character (if any) is not a "word" char
                let next_is_word = if end >= input.len() {
                    false
                } else {
                    input[end..]
                        .chars()
                        .next()
                        .map(|c| c.is_alphanumeric() || c == '_')
                        .unwrap_or(false)
                };

                if !prev_is_word && !next_is_word {
                    count += 1;
                    if count == 2 {
                        // Construct result with replacement
                        let mut result = String::with_capacity(input.len() + ("Bull,".len() - needle_len));
                        result.push_str(&input[..start]);
                        result.push_str("Bull,");
                        result.push_str(&input[end..]);
                        return result;
                    }
                }

                // Advance search_start to end to avoid infinite loop and allow overlapping behavior
                search_start = end;
            }
            None => break,
        }
    }

    // Fewer than two whole-word occurrences -> return input unchanged
    input.to_string()
}

