use std::collections::HashMap;

/// Divides a dataset into separate subsets based on distinct values in a specified column.
///
/// # Arguments
/// * `df0` - A Chunk containing the tabular dataset
/// * `var0_index` - The index of the column to partition by
///
/// # Returns
/// A HashMap where keys are the distinct values from var0 column (as strings),
/// and values are Chunks containing the rows matching each distinct value.
fn divide_by_column(
    df0: &Chunk<Box<dyn Array>>,
    var0_index: usize,
) -> Result<HashMap<String, Chunk<Box<dyn Array>>>, Box<dyn std::error::Error>> {
    let var0_array = &df0.arrays()[var0_index];
    let mut subsets: HashMap<String, Vec<usize>> = HashMap::new();

    // Build a map of distinct values to row indices
    for i in 0..var0_array.len() {
        let key = format_array_value(var0_array, i)?;
        subsets.entry(key).or_insert_with(Vec::new).push(i);
    }

    // Create chunks for each subset
    let mut result: HashMap<String, Chunk<Box<dyn Array>>> = HashMap::new();

    for (key, indices) in subsets {
        let filtered_arrays: Vec<Box<dyn Array>> = df0
            .arrays()
            .iter()
            .map(|array| filter_array_by_indices(array.as_ref(), &indices))
            .collect();

        result.insert(key, Chunk::new(filtered_arrays));
    }

    Ok(result)
}

/// Helper function to format a value from an array at a given index as a string.
fn format_array_value(
    array: &Box<dyn Array>,
    index: usize,
) -> Result<String, Box<dyn std::error::Error>> {
    use arrow2::array::*;

    if array.is_null(index) {
        return Ok("NULL".to_string());
    }

    match array.data_type() {
        DataType::Int32 => {
            let arr = array.as_any().downcast_ref::<Int32Array>().unwrap();
            Ok(arr.value(index).to_string())
        }
        DataType::Int64 => {
            let arr = array.as_any().downcast_ref::<Int64Array>().unwrap();
            Ok(arr.value(index).to_string())
        }
        DataType::Float32 => {
            let arr = array.as_any().downcast_ref::<Float32Array>().unwrap();
            Ok(arr.value(index).to_string())
        }
        DataType::Float64 => {
            let arr = array.as_any().downcast_ref::<Float64Array>().unwrap();
            Ok(arr.value(index).to_string())
        }
        DataType::Utf8 | DataType::LargeUtf8 => {
            let arr = array.as_any().downcast_ref::<Utf8Array<i32>>().unwrap();
            Ok(arr.value(index).to_string())
        }
        DataType::Boolean => {
            let arr = array.as_any().downcast_ref::<BooleanArray>().unwrap();
            Ok(arr.value(index).to_string())
        }
        _ => Ok(format!("Value at index {}", index)),
    }
}

/// Helper function to filter an array by indices.
fn filter_array_by_indices(array: &dyn Array, indices: &[usize]) -> Box<dyn Array> {
    use arrow2::array::*;

    match array.data_type() {
        DataType::Int32 => {
            let arr = array.as_any().downcast_ref::<Int32Array>().unwrap();
            let filtered: Vec<Option<i32>> = indices
                .iter()
                .map(|&i| if arr.is_null(i) { None } else { Some(arr.value(i)) })
                .collect();
            Box::new(Int32Array::from(filtered))
        }
        DataType::Int64 => {
            let arr = array.as_any().downcast_ref::<Int64Array>().unwrap();
            let filtered: Vec<Option<i64>> = indices
                .iter()
                .map(|&i| if arr.is_null(i) { None } else { Some(arr.value(i)) })
                .collect();
            Box::new(Int64Array::from(filtered))
        }
        DataType::Utf8 | DataType::LargeUtf8 => {
            let arr = array.as_any().downcast_ref::<Utf8Array<i32>>().unwrap();
            let filtered: Vec<Option<&str>> = indices
                .iter()
                .map(|&i| if arr.is_null(i) { None } else { Some(arr.value(i)) })
                .collect();
            Box::new(Utf8Array::<i32>::from(filtered))
        }
        DataType::Boolean => {
            let arr = array.as_any().downcast_ref::<BooleanArray>().unwrap();
            let filtered: Vec<Option<bool>> = indices
                .iter()
                .map(|&i| if arr.is_null(i) { None } else { Some(arr.value(i)) })
                .collect();
            Box::new(BooleanArray::from(filtered))
        }
        _ => array.to_boxed(),
    }
}
