use ndmatrix::Matrix;
use std::collections::HashMap;

/// Groups a dataset by a specified column, applies an aggregation function,
/// and returns the result as a 2D matrix.
///
/// # Arguments
///
/// * `df0` - A 2D matrix where each row is a record and each column is a field
/// * `var0_col` - The column index to group by
/// * `agg_col` - The column index to aggregate
/// * `agg_function` - A closure that takes a vector of f64 values and returns an aggregated f64
///
/// # Returns
///
/// A 2D matrix with two columns: the group keys and their aggregated values
pub fn group_and_aggregate<F>(
    df0: &Matrix<f64>,
    var0_col: usize,
    agg_col: usize,
    agg_function: F,
) -> Matrix<f64>
where
    F: Fn(Vec<f64>) -> f64,
{
    // Create a HashMap to group values by the grouping column
    let mut groups: HashMap<String, Vec<f64>> = HashMap::new();

    // Iterate through rows and group by var0_col
    for row_idx in 0..df0.rows() {
        let group_key = df0[[row_idx, var0_col]].to_string();
        let agg_value = df0[[row_idx, agg_col]];

        groups
            .entry(group_key)
            .or_insert_with(Vec::new)
            .push(agg_value);
    }

    // Convert groups to a sorted vector for consistent output
    let mut group_vec: Vec<(String, f64)> = groups
        .into_iter()
        .map(|(key, values)| (key, agg_function(values)))
        .collect();

    // Sort by group key for consistent ordering
    group_vec.sort_by(|a, b| {
        a.0.parse::<f64>()
            .unwrap_or(0.0)
            .partial_cmp(&b.0.parse::<f64>().unwrap_or(0.0))
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    // Create a 2D matrix with results (n_groups x 2)
    let n_groups = group_vec.len();
    let mut result = Matrix::new(n_groups, 2, 0.0);

    for (idx, (key, agg_value)) in group_vec.iter().enumerate() {
        result[[idx, 0]] = key.parse::<f64>().unwrap_or(0.0);
        result[[idx, 1]] = *agg_value;
    }

    result
}

fn main() {
    // Example usage
    let data = vec![
        1.0, 100.0, 1.0, 150.0, 2.0, 200.0, 2.0, 250.0, 1.0, 175.0,
    ];
    let df0 = Matrix::new(5, 2, data);

    // Group by column 0, aggregate column 1 using sum
    let result = group_and_aggregate(&df0, 0, 1, |values| values.iter().sum());

    println!("Grouped and aggregated result:");
    for row_idx in 0..result.rows() {
        println!(
            "Group: {}, Aggregated Value: {}",
            result[[row_idx, 0]], result[[row_idx, 1]]
        );
    }

    // Example with average aggregation
    let result_avg = group_and_aggregate(&df0, 0, 1, |values| {
        let sum: f64 = values.iter().sum();
        sum / values.len() as f64
    });

    println!("\nGrouped with average aggregation:");
    for row_idx in 0..result_avg.rows() {
        println!(
            "Group: {}, Average Value: {}",
            result_avg[[row_idx, 0]], result_avg[[row_idx, 1]]
        );
    }
}
```

