fn sum_sequences<T>(seq1: &[T], seq2: &[T]) -> Vec<T>
where
    T: Num + Copy, // Ensure T is a number type and can be copied
{
    // Check that the lengths of both sequences are the same
    assert_eq!(seq1.len(), seq2.len(), "Sequences must be of equal length");

    // Create a new Vec to hold the sums
    let mut result = Vec::with_capacity(seq1.len());

    // Iterate over both sequences and sum the corresponding elements
    for i in 0..seq1.len() {
