use sprs::CsMat;

/// Compute the average row index and average column index (0-based) of all nonzero
/// entries in the sparse matrix `df0`.
///
/// Returns None if the matrix has no nonzero entries.
///
/// Example:
/// let df0 = CsMat::new((3, 3),
///     vec![0, 1, 1, 2],   // indptr (CSR)
///     vec![1, 0],         // indices
///     vec![1.0, 2.0]);    // data
/// let avg = avg_row_col_indices(&df0).unwrap();
/// // avg == ( (0 + 2) / 2 = 1.0, (1 + 0) / 2 = 0.5 )
fn avg_row_col_indices(df0: &CsMat<f64>) -> Option<(f64, f64)> {
    let nnz = df0.nnz();
    if nnz == 0 {
        return None;
    }

    let mut sum_rows: usize = 0;
    let mut sum_cols: usize = 0;

    // If CSR, outer iterator yields rows; if CSC, outer iterator yields columns.
    if df0.is_csr() {
        for (row_idx, row) in df0.outer_iterator().enumerate() {
            for &col in row.indices() {
                sum_rows += row_idx;
                sum_cols += col;
            }
        }
    } else {
        // CSC storage: outer_iterator gives columns
        for (col_idx, col) in df0.outer_iterator().enumerate() {
            for &row in col.indices() {
                sum_rows += row;
                sum_cols += col_idx;
            }
        }
    }

    Some((sum_rows as f64 / nnz as f64, sum_cols as f64 / nnz as f64))
}

