        }

        let row = &data[row_idx];
        let sum: f64 = col_indices
            .iter()
            .map(|&col_idx| {
                if col_idx >= row.len() {
                    panic!("Column index {} out of bounds", col_idx);
                }
                row[col_idx]
            })
            .sum();

        let mean = sum / col_indices.len() as f64;
        row_means.push(mean);
