    // Compute means for specified columns
    for &col_idx in col_indices {
        let sum: f64 = row_indices
            .iter()
            .map(|&row_idx| {
                if col_idx >= data[row_idx].len() {
                    panic!("Column index {} out of bounds", col_idx);
                }
                data[row_idx][col_idx]
            })
            .sum();

        let mean = sum / row_indices.len() as f64;
        col_means.push(mean);
