# Rust Function: Sort Inner Lists by Custom Mapping

```rust
use std::collections::HashMap;

/// Sorts each inner list according to a custom mapping that defines the desired order.
///
/// # Arguments
/// * `lists` - A vector of vectors containing comparable elements
/// * `order_map` - A HashMap that maps each element to its desired position
///
/// # Returns
/// A vector of vectors where each inner list is sorted according to the order_map
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut order = HashMap::new();
/// order.insert('a', 0);
/// order.insert('b', 1);
/// order.insert('c', 2);
///
/// let lists = vec![
///     vec!['c', 'a', 'b'],
///     vec!['b', 'c', 'a'],
/// ];
///
/// let result = sort_inner_lists_by_mapping(lists, &order);
/// assert_eq!(result, vec![
///     vec!['a', 'b', 'c'],
///     vec!['a', 'b', 'c'],
/// ]);
/// ```
fn sort_inner_lists_by_mapping<T: Clone + Eq + std::hash::Hash>(
    lists: Vec<Vec<T>>,
    order_map: &HashMap<T, usize>,
) -> Vec<Vec<T>> {
    lists
        .into_iter()
        .map(|mut inner_list| {
            inner_list.sort_by_key(|item| {
                order_map
                    .get(item)
                    .copied()
                    .unwrap_or(usize::MAX) // Elements not in map go to the end
            });
            inner_list
        })
        .collect()
}

fn main() {
    // Example 1: Sorting characters
    let mut char_order = HashMap::new();
    char_order.insert('a', 0);
    char_order.insert('b', 1);
    char_order.insert('c', 2);
    char_order.insert('d', 3);

    let char_lists = vec![
        vec!['d', 'b', 'a', 'c'],
        vec!['c', 'a', 'd', 'b'],
        vec!['b', 'd', 'a'],
    ];

    let sorted_chars = sort_inner_lists_by_mapping(char_lists, &char_order);
    println!("Sorted character lists:");
    for list in &sorted_chars {
        println!("{:?}", list);
    }
    // Output:
    // ['a', 'b', 'c', 'd']
    // ['a', 'b', 'c', 'd']
    // ['a', 'b', 'd']

    // Example 2: Sorting strings
    let mut string_order = HashMap::new();
    string_order.insert("apple".to_string(), 2);
    string_order.insert("banana".to_string(), 1);
    string_order.insert("cherry".to_string(), 0);

    let string_lists = vec![
        vec!["apple".to_string(), "cherry".to_string(), "banana".to_string()],
        vec!["banana".to_string(), "apple".to_string()],
