use std::collections::HashMap;

// Function to convert a RecordBatch into a HashMap where var0 is the key
pub fn batch_to_dict(
    df0: &RecordBatch,
    key_column_name: &str,
) -> Result<HashMap<String, Vec<Vec<Option<arrow::datatypes::DataType>>>>, String> {
    // Get the schema to check if the key column exists
    let schema = df0.schema();
    let key_field = schema
        .field_with_name(key_column_name)
        .ok_or_else(|| format!("Column '{}' not found", key_column_name))?;

    // Verify the key column is a String type
    if key_field.data_type() != &DataType::Utf8 {
        return Err(format!(
            "Key column '{}' must be of type Utf8 (String)",
            key_column_name
        ));
    }

    // Get the key array and value array (all columns except the key)
    let key_array = df0
        .column(key_column_name)
        .ok_or_else(|| format!("Failed to get column '{}'", key_column_name))?;

    // Get all other columns (values)
    let value_columns = df0
        .columns()
        .iter()
        .enumerate()
        .filter(|(i, _)| i != df0.schema().field_index(key_column_name).unwrap())
        .map(|(_, col)| col.clone())
        .collect::<Vec<_>>();

    // Create the result map
    let mut result = HashMap::new();

    // Iterate through each row
    for i in 0..key_array.len() {
        // Get the key value (must be String)
        let key = key_array
            .value(i)
            .and_then(|v| v.downcast_ref::<StringArray>())
            .and_then(|arr| arr.value(i))
            .ok_or_else(|| format!("Failed to get key value at row {}", i))?
            .to_string();

        // Get all values for this row
        let mut row_values = Vec::with_capacity(value_columns.len());
        for col in &value_columns {
            let value = col.value(i);
            row_values.push(value);
        }

        result.insert(key, row_values);
    }

    Ok(result)
}

