/// - `var0` is not a column in `df0`,
/// - any key value is null,
/// - duplicate keys are encountered.
///
/// Example:
/// let map = df0_to_map(&record_batch, "id")?;
pub fn df0_to_map(
    df0: &RecordBatch,
    var0: &str,
) -> Result<HashMap<String, Vec<Option<String>>>, ArrowError> {
    // find column index for var0
    let schema = df0.schema();
    let key_idx = schema
        .index_of(var0)
        .map_err(|_| ArrowError::ComputeError(format!("column '{}' not found", var0)))?;

    let num_rows = df0.num_rows();
    let num_cols = df0.num_columns();

    // collect array refs
    let arrays: Vec<ArrayRef> = (0..num_cols)
        .map(|i| df0.column(i).clone())
        .collect();

    let key_array = arrays[key_idx].clone();

    let mut map: HashMap<String, Vec<Option<String>>> = HashMap::with_capacity(num_rows);

    for row in 0..num_rows {
        // extract key
        let key_opt = array_value_to_string(&key_array, row);
        let key = match key_opt {
            Some(s) => s,
            None => {
                return Err(ArrowError::ComputeError(format!(
                    "null key encountered at row {}",
                    row
                )))
            }
        };

        // build row values excluding key column
        let mut row_vals: Vec<Option<String>> = Vec::with_capacity(num_cols - 1);
        for col in 0..num_cols {
            if col == key_idx {
                continue;
            }
            let val = array_value_to_string(&arrays[col], row);
            row_vals.push(val);
        }

        if map.insert(key.clone(), row_vals).is_some() {
            return Err(ArrowError::ComputeError(format!(
                "duplicate key '{}' encountered",
                key
            )));
        }
    }

    Ok(map)
}

