/// A HashMap where keys are the identifier values and values are HashMaps
/// containing column names mapped to their string representations.
pub fn convert_table_to_dict(
    batch: &RecordBatch,
    id_column: &str,
) -> Result<HashMap<String, HashMap<String, String>>, Box<dyn std::error::Error>> {
    let mut result: HashMap<String, HashMap<String, String>> = HashMap::new();

    // Find the index of the id column
    let id_col_index = batch
        .schema()
        .column_with_name(id_column)
        .ok_or(format!("Column '{}' not found", id_column))?
        .0;

    let id_array = batch.column(id_col_index);
    let num_rows = batch.num_rows();

    // Iterate through each row
    for row_idx in 0..num_rows {
        // Get the identifier for this row
        let id_value = arrow::array::Array::slice(id_array, row_idx, 1);
        let id_str = format_array_value(&id_value, 0)?;

        // Create a HashMap for this row's data
        let mut row_data: HashMap<String, String> = HashMap::new();

        // Iterate through all columns
        for (col_idx, field) in batch.schema().fields().iter().enumerate() {
            let col_name = field.name();
            let col_array = batch.column(col_idx);

            // Extract the value at this row
            let value_str = format_array_value(col_array, row_idx)?;
            row_data.insert(col_name.clone(), value_str);
        }

        result.insert(id_str, row_data);
    }

    Ok(result)
}

