use linked_hash_set::LinkedHashSet;
use std::hash::Hash;

/// Sort the keys of a mapping (provided as an iterator of (K,V) pairs in
/// the original insertion order) by their associated values.
///
/// Returns a Vec of (key, value, original_index).
///
/// K must be cloneable, hashable and comparable for equality. V must be
/// orderable and cloneable.
pub fn sort_keys_by_value<K, V, I>(entries: I) -> Vec<(K, V, usize)>
where
    I: IntoIterator<Item = (K, V)>,
    K: Eq + Hash + Clone,
    V: Ord + Clone,
{
    // Collect entries in original order
    let entries_vec: Vec<(K, V)> = entries.into_iter().collect();

    // Keep a LinkedHashSet of keys to preserve the original insertion order
    // (we'll use it to find original indices)
    let mut keys_in_order = LinkedHashSet::new();
    for (k, _) in &entries_vec {
        keys_in_order.insert(k.clone());
    }

    // Make a sortable copy and sort by value (ascending)
    let mut sorted = entries_vec.clone();
    sorted.sort_by(|a, b| a.1.cmp(&b.1));

    // Build result triples (key, value, original_index)
    let mut result = Vec::with_capacity(sorted.len());
    for (k, v) in sorted {
        // find original index of k by iterating the linked set (preserves insertion order)
        let original_index = keys_in_order
            .iter()
            .position(|kk| kk == &k)
            .expect("key in sorted list must exist in original keys set");
        result.push((k, v, original_index));
    }

    result
}

Example usage:

