fn find_duplicate_var0_rows(table: Vec<HashMap<String, String>>) -> Vec<HashMap<String, String>> {
    // Count occurrences of each var0 value
    let mut var0_counts: HashMap<String, usize> = HashMap::new();

    for row in &table {
