```rust
/// A small "substructure" module providing a Unicode-aware substring function.
mod substructure {
    /// Return a substring that starts at `start` (0-based character index)
    /// and spans `count` characters. If `start` is past the end of `text`,
    /// returns an empty string. If `count` extends past the end, returns
    /// until the end of `text`.
    pub fn slice(text: &str, start: usize, count: usize) -> String {
        if count == 0 {
            return String::new();
        }

        // Find the byte offset of the `start`-th character.
        let start_byte = match text.char_indices().nth(start).map(|(i, _)| i) {
            Some(i) => i,
            None => return String::new(), // start beyond end -> empty
        };

        // Find the byte offset after `count` characters from start_byte.
        let end_byte = match text[start_byte..].char_indices().nth(count).map(|(i, _)| start_byte + i) {
            Some(i) => i,
            None => text.len(), // take until end
        };

        text[start_byte..end_byte].to_string()
    }
}

/// Public function that uses the `substructure` module to extract the portion.
pub fn extract_portion(text: &str, start: usize, count: usize) -> String {
    substructure::slice(text, start, count)
}

