use tokio_stream::StreamExt;
use futures::stream::Stream;

/// Collect the next `n` items produced by `stream` into a Vec and return it.
///
/// - `stream` is a mutable reference to an object implementing `Stream<Item = T> + Unpin`.
/// - `n` is the maximum number of items to collect.
/// The function returns as soon as it has collected `n` items or the stream ends.
pub async fn collect_next<T, S>(stream: &mut S, n: usize) -> Vec<T>
where
    S: Stream<Item = T> + Unpin,
{
    let mut out = Vec::with_capacity(n);
    let mut remaining = n;

    while remaining > 0 {
        match stream.next().await {
            Some(item) => {
                out.push(item);
                remaining -= 1;
            }
            None => break, // stream ended early
        }
    }

    out
}

