/// Helper function to convert an async function into a Stream
fn async_fn_stream<T, F, Fut>(func: F) -> impl Stream<Item = T>
where
    F: Fn() -> Fut,
    Fut: std::future::Future<Output = T>,
{
    // Create a channel for streaming values
    let (tx, rx) = tokio::sync::mpsc::unbounded_channel::<T>();

    // Spawn a task that continuously calls the function and sends results
    tokio::spawn(async move {
        loop {
            let value = func().await;
            if tx.send(value).is_err() {
                break; // Receiver dropped
            }
        }
    });

    ReceiverStream::new(rx)
}

