/// 'A' and 'B' in-place on `df0`.
///
/// Returns Ok(()) on success or an error if:
/// - 'col0' does not exist
/// - any non-null cell in 'col0' is not a 2-element tuple
pub fn split_col0_into_a_b(df0: &mut Table) -> Result<(), Box<dyn Error>> {
    // Find the index of 'col0'
    let col_idx = df0
        .column_index("col0")
        .ok_or_else(|| format!("column 'col0' not found"))?;

    let nrows = df0.row_count();

    // Prepare vectors to collect values for new columns
    let mut a_vals: Vec<Value> = Vec::with_capacity(nrows);
    let mut b_vals: Vec<Value> = Vec::with_capacity(nrows);

    for row in 0..nrows {
