    let stdin = io::stdin();
    let mut reader = stdin.lock();

    let mut previous_row: Option<String> = None;
    let mut line = String::new();

    // Read the first line (header or first data row)
    reader.read_line(&mut line)?;
    if !line.is_empty() {
        println!("{}", line.trim_end());
        previous_row = Some(line.trim_end().to_string());
    }

    // Process remaining lines
    loop {
        line.clear();
        let bytes_read = reader.read_line(&mut line)?;

        if bytes_read == 0 {
            break; // EOF reached
        }

        let current_row = line.trim_end().to_string();

        // Only print if it's different from the previous row
        if previous_row.as_ref() != Some(&current_row) {
            println!("{}", current_row);
            previous_row = Some(current_row);
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    remove_consecutive_duplicates()
}
```

