///     vec!["2".to_string(), "4".to_string(), "5".to_string()],
/// ]);
/// df.set_column_names(vec!["x".to_string(), "y".to_string(), "z".to_string()]);
///
/// let result = divide_columns(&mut df, vec!["x".to_string(), "y".to_string()], "z".to_string());
/// ```
pub fn divide_columns(
    df0: &mut DataFrame,
    columns_list0: Vec<String>,
    column_name0: String,
) -> Result<(), Box<dyn Error>> {
    // Check if divisor column exists
    if !df0.column_names().contains(&column_name0) {
        return Err(format!("Column '{}' not found", column_name0).into());
    }

    // Check if all target columns exist
    for col in &columns_list0 {
        if !df0.column_names().contains(col) {
            return Err(format!("Column '{}' not found", col).into());
        }
    }

    // Get the divisor column as f64
    let divisor_col = df0.column(&column_name0)
        .ok_or("Failed to get divisor column")?
        .to_f64()?;

    // Process each target column
    for col_name in columns_list0 {
        let col = df0.column(&col_name)
            .ok_or(format!("Failed to get column '{}'", col_name))?;

        let mut new_col = Vec::new();
        let divisor_values = divisor_col.iter();

        for (i, (val, div)) in col.iter().zip(divisor_values) {
            match (val.parse::<f64>(), *div) {
                (Ok(num), div) if div != 0.0 => {
                    new_col.push((num / div).to_string());
                },
                (Ok(_), div) if div == 0.0 => {
                    return Err(format!("Division by zero in column '{}' at row {}", col_name, i).into());
                },
                (Err(_), _) => {
                    return Err(format!("Non-numeric value in column '{}' at row {}", col_name, i).into());
                }
            }
        }

        // Replace the column with the new values
        df0.replace_column(&col_name, new_col)?;
    }

    Ok(())
}
```

### Important Notes:

