use csv::ReaderBuilder;
use std::error::Error;
use std::io::Cursor;

/// Divides each value in specified columns by the corresponding value in a divisor column.
///
/// # Arguments
/// * `csv_data` - CSV data as a string
/// * `columns_list0` - List of column names to divide
/// * `column_name0` - Name of the column containing divisor values
///
/// # Returns
/// A CSV string with the divided values
fn divide_columns_by_column(
    csv_data: &str,
    columns_list0: Vec<&str>,
    column_name0: &str,
) -> Result<String, Box<dyn Error>> {
    let cursor = Cursor::new(csv_data);
    let mut reader = ReaderBuilder::new().from_reader(cursor);

    let headers = reader.headers()?.clone();
    let header_names: Vec<String> = headers.iter().map(|h| h.to_string()).collect();

    // Find the index of the divisor column
    let divisor_col_index = header_names
        .iter()
        .position(|h| h == column_name0)
        .ok_or(format!("Column '{}' not found", column_name0))?;

    // Find indices of columns to divide
    let mut divide_col_indices = Vec::new();
    for col_name in &columns_list0 {
        let index = header_names
            .iter()
            .position(|h| h == *col_name)
            .ok_or(format!("Column '{}' not found", col_name))?;
        divide_col_indices.push(index);
    }

    let mut result = String::new();

    // Write headers
    result.push_str(&header_names.join(","));
    result.push('\n');

    // Process each record
    for record in reader.records() {
        let mut row = record?;
        let divisor_str = &row[divisor_col_index];
        let divisor: f64 = divisor_str.parse()
            .map_err(|_| format!("Cannot parse divisor value '{}' as number", divisor_str))?;

        if divisor == 0.0 {
            return Err("Division by zero encountered".into());
        }

        // Divide specified columns
        for &col_index in &divide_col_indices {
            let value_str = &row[col_index];
            let value: f64 = value_str.parse()
                .map_err(|_| format!("Cannot parse value '{}' as number", value_str))?;

            let result_value = value / divisor;
            row[col_index] = result_value.to_string();
        }

        result.push_str(&row.iter().collect::<Vec<_>>().join(","));
        result.push('\n');
    }

    Ok(result)
}

