use tensorflow::{
    ops::{self, OneHot, Shape},
    Session,
    Tensor,
};
use std::collections::HashMap;

/// Expands a categorical column into binary indicator columns
///
/// # Arguments
/// * `df0` - Input tensor with shape [batch_size, num_features]
/// * `var0_index` - Index of the categorical column to expand
///
/// # Returns
/// A new tensor with shape [batch_size, num_distinct_values] containing binary indicators
///
/// # Example
/// ```
/// let session = Session::new(&DefaultConfig::default())?;
/// let input = Tensor::of_slice(&[
///     vec![1, 2, 3],  // row 0
///     vec![1, 2, 1],  // row 1
///     vec![3, 3, 2],  // row 2
/// ]);
/// let output = expand_categorical_column(&session, &input, 0)?;
/// ```
pub fn expand_categorical_column(session: &Session, input: &Tensor, var0_index: usize) -> Result<Tensor, Box<dyn std::error::Error>> {
    // Get the categorical column values
    let var0 = input.select(&ops::Squeeze::new([var0_index as i64])).run(&session)?;

    // Get unique values and their counts
    let unique_values = var0.as_slice::<i64>()?
        .iter()
        .cloned()
        .collect::<HashMap<_, usize>>()
        .keys()
        .cloned()
        .collect::<Vec<_>>();

    // Create one-hot encoding
    let depth = unique_values.len() as i64;
    let one_hot = OneHot::new()
        .axis(0)
        .depth(depth)
        .on_value(1.0)
        .off_value(0.0)
        .run(&session, &var0)?;

    // Reshape to [batch_size, num_distinct_values]
    let reshaped = ops::Reshape::new([-1, depth])
        .run(&session, &one_hot)?;

    Ok(reshaped)
}

// Helper function to demonstrate usage with a DataFrame-like structure
pub fn create_indicator_columns(
    session: &Session,
    df0: &Tensor,
    var0_index: usize,
) -> Result<Tensor, Box<dyn std::error::Error>> {
    // Ensure we have at least the specified column
    if df0.shape()[1] <= var0_index as i64 {
        return Err("Column index out of bounds".into());
    }

    expand_categorical_column(session, df0, var0_index)
}

