use tensorflow::{Graph, Session, SessionOptions, Tensor, TensorType, Output, Operation};
use std::collections::HashMap;

/// One-hot encode a column from a table.
/// 
/// # Arguments
/// * `df0` - A 2D tensor representing the input table (rows x columns)
/// * `var0_col_idx` - The index of the column to one-hot encode
/// 
/// # Returns
/// A new 2D tensor with the original columns plus binary indicator columns
/// for each distinct value in var0
fn one_hot_encode_column(df0: &Tensor<i32>, var0_col_idx: usize) -> Result<Tensor<i32>, Box<dyn std::error::Error>> {
    // Get dimensions of input table
    let shape = df0.dims();
    let num_rows = shape[0];
    let num_cols = shape[1];

    // Extract the column to encode
    let var0_values: Vec<i32> = df0
        .iter()
        .enumerate()
        .filter(|(i, _)| i % num_cols == var0_col_idx)
        .map(|(_, val)| *val)
        .collect();

    // Find distinct values and create mapping
    let mut distinct_values: Vec<i32> = var0_values.clone();
    distinct_values.sort();
    distinct_values.dedup();

    let num_distinct = distinct_values.len();

    // Create value to index mapping
    let value_to_idx: HashMap<i32, usize> = distinct_values
        .iter()
        .enumerate()
        .map(|(i, val)| (*val, i))
        .collect();

    // Create new tensor with original columns + one-hot columns
    let new_num_cols = num_cols + num_distinct;
    let mut new_data = Vec::with_capacity(num_rows * new_num_cols);

    for row in 0..num_rows {
        // Copy original row values
        for col in 0..num_cols {
            let idx = row * num_cols + col;
            new_data.push(df0[idx]);
        }

        // Add one-hot encoding for var0 value
        let var0_val = var0_values[row];
        for distinct_idx in 0..num_distinct {
            if value_to_idx[&var0_val] == distinct_idx {
                new_data.push(1);
            } else {
                new_data.push(0);
            }
        }
    }

    // Create output tensor
    let output_shape = vec![num_rows as u64, new_num_cols as u64];
    let mut output_tensor = Tensor::<i32>::new(&output_shape);

    for (i, val) in new_data.iter().enumerate() {
        output_tensor[i] = *val;
    }

    Ok(output_tensor)
}

