use fxhash::FxHashMap;
use std::cmp::Ordering;

fn sort_according_to_b<A: Eq + std::hash::Hash + Ord, B: AsRef<[A]>>(a: &mut Vec<A>, b: B) {
    // Create a hashmap for the order defined by list B
    let order_map: FxHashMap<_, _> = b
        .as_ref()
        .iter()
        .enumerate()
        .map(|(index, item)| (item, index))
        .collect();

