    // Items not in B will be ordered before those in B
    a.sort_unstable_by(|x, y| {
        let x_order = order_map.get(x).map_or(usize::MAX, |&index| index);
        let y_order = order_map.get(y).map_or(usize::MAX, |&index| index);

