use fxhash::FxHashMap;

fn sort_by_order<T: Eq + std::hash::Hash + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    // Create a hashmap to store the index of each element in B
    let mut order_map = FxHashMap::default();
    for (index, item) in b.iter().enumerate() {
        order_map.insert(item, index);
    }

    // Partition A into two vectors: one with elements in B and one without
    let mut in_b = Vec::new();
    let mut not_in_b = Vec::new();

    for item in a {
        if order_map.contains_key(item) {
            in_b.push(item.clone());
        } else {
            not_in_b.push(item.clone());
        }
    }

    // Sort the 'in_b' vector based on the order defined by B
    in_b.sort_by_key(|item| *order_map.get(item).unwrap());

    // Concatenate 'not_in_b' and 'in_b'
    let mut result = not_in_b;
    result.extend(in_b);

    result
}

