use std::hash::Hash;
use fxhash::{FxHashMap, FxHashSet};

/// Sort `a` according to the order defined by `b` (which is already sorted).
/// Elements in `a` that are NOT present in `b` are placed at the beginning.
/// The relative order is preserved among elements not in `b`, and among elements
/// that map to the same position in `b` (stable behavior).
///
/// Complexity: O(|A| + min(|B|, |unique(A)|)) time for building the rank map
/// and O(|A| log |A|) for the sort. Memory: O(min(|B|, |unique(A)|)) for ranks.
///
/// Requires T: Eq + Hash + Clone because we clone from `a` and `b`.
pub fn sort_by_b<T>(a: &[T], b: &[T]) -> Vec<T>
where
    T: Eq + Hash + Clone,
{
    // Set of distinct items in A (so we only record ranks for B items that actually appear in A)
    let mut present: FxHashSet<T> = FxHashSet::default();
    present.reserve(a.len());
    for item in a {
        present.insert(item.clone());
    }

    // Map each value from B (only if present in A) to its index in B.
    let mut rank: FxHashMap<T, usize> = FxHashMap::default();
    rank.reserve(std::cmp::min(b.len(), present.len()));
    for (i, item) in b.iter().enumerate() {
        if present.contains(item) {
            // Only insert the first occurrence in B as its rank
            rank.entry(item.clone()).or_insert(i);
        }
    }

    // Sort indices of A by a key:
    //  - items not in B -> key (0, original_index) (they come first, preserving original order)
    //  - items in B     -> key (1, rank, original_index) (ordered by B, stable for equal ranks)
    let mut idxs: Vec<usize> = (0..a.len()).collect();
    idxs.sort_by_key(|&i| match rank.get(&a[i]) {
        Some(&r) => (1u8, r, i),
        None => (0u8, 0usize, i),
    });

    idxs.into_iter().map(|i| a[i].clone()).collect()
}

Example usage:

fn main() {
    let a = vec!["x", "b", "y", "a", "c", "b"];
    let b = vec!["a", "b", "c", "d", "e"]; // B defines desired order: a < b < c < d < e
    let sorted = sort_by_b(&a, &b);
    // Elements not in B ("x", "y") come first, preserving their original order.
    // Then elements present in B are ordered as in B: "a", "b", "b", "c".
    assert_eq!(sorted, vec!["x", "y", "a", "b", "b", "c"]);
    println!("{:?}", sorted);
}

If you prefer an in-place sort over a Vec<T> with fewer clones, the function can be adapted accordingly; this version is simple and safe and keeps the work on B minimal when B is very large.

