/// let result = sort_by_reference(a, b);
/// assert_eq!(result, vec![9, 1, 1, 2, 3, 4, 5, 6]);
/// ```
pub fn sort_by_reference<T: Eq + std::hash::Hash + Clone>(
    mut a: Vec<T>,
    b: &[T],
) -> Vec<T> {
    // Create a hash map with position indices for O(1) lookups
    let mut position_map: FxHashMap<T, usize> = FxHashMap::default();

    for (index, item) in b.iter().enumerate() {
        position_map.insert(item.clone(), index);
    }

    // Partition: items not in B go to the front, items in B maintain relative order
    let mut result = Vec::with_capacity(a.len());
    let mut items_in_b = Vec::new();

    for item in a.into_iter() {
        if let Some(&pos) = position_map.get(&item) {
            items_in_b.push((pos, item));
        } else {
            result.push(item);
        }
    }

    // Sort items that appear in B by their position in B
    items_in_b.sort_by_key(|(pos, _)| *pos);

    // Append sorted items from B
    for (_, item) in items_in_b {
        result.push(item);
    }

    result
}

