/// let sum = conditional_column_sum(csv, "salary", "age", "30").unwrap();
/// assert_eq!(sum, 105000.0); // Alice and Charlie both have age 30
/// ```
pub fn conditional_column_sum(
    csv_data: &str,
    column_name: &str,
    condition_column: &str,
    condition_value: &str,
) -> Result<f64, Box<dyn Error>> {
    let cursor = Cursor::new(csv_data);
    let mut reader = Reader::from_reader(cursor);

    // Get headers
    let headers = reader.headers()?.clone();

    // Find column indices
    let sum_col_index = headers
        .iter()
        .position(|h| h == column_name)
        .ok_or(format!("Column '{}' not found", column_name))?;

    let condition_col_index = headers
        .iter()
        .position(|h| h == condition_column)
        .ok_or(format!("Column '{}' not found", condition_column))?;

    let mut total: f64 = 0.0;

    // Iterate through records and apply filtering
    for result in reader.records() {
        let record = result?;

        // Check if condition matches
        if let Some(cond_value) = record.get(condition_col_index) {
            if cond_value == condition_value {
                // Get the value to sum
                if let Some(value_str) = record.get(sum_col_index) {
                    if let Ok(value) = value_str.parse::<f64>() {
                        total += value;
                    } else {
                        return Err(format!(
                            "Cannot parse '{}' as f64 in column '{}'",
                            value_str, column_name
                        )
                        .into());
                    }
                }
            }
        }
    }

    Ok(total)
}

