use prettytable::{Table, Row, Cell};
use prettytable::format::{Alignment, FormatBuilder};

/// Function to convert multiple lists into a 2D table with custom column headers.
///
/// # Arguments
///
/// * `column_headers`: List of column headers.
/// * `data`: List of lists containing the table data.
///
/// # Returns
///
/// A `Table` instance representing the 2D table.
fn convert_lists_to_table(column_headers: Vec<String>, data: Vec<Vec<String>>) -> Table {
    let mut table = Table::new();
    let format = FormatBuilder::new()
        .column_separator(' ')
        .borders('|')
        .padding(1)
        .alignment(Alignment::LEFT)
        .build();

    // Add column headers
    let mut header_row = Row::new(vec![]);
    for header in &column_headers {
        header_row.add_cell(Cell::new(header).with_format(format.clone()));
    }
    table.add_row(header_row);

    // Add data rows
    for row_data in &data {
        let mut row = Row::new(vec![]);
        for cell_data in row_data {
            row.add_cell(Cell::new(cell_data).with_format(format.clone()));
        }
        table.add_row(row);
    }

    table
}

fn main() {
    let column_headers = vec!["Name".to_string(), "Age".to_string(), "City".to_string()];
    let data = vec![
        vec!["John".to_string(), "25".to_string(), "New York".to_string()],
        vec!["Alice".to_string(), "30".to_string(), "Los Angeles".to_string()],
        vec!["Bob".to_string(), "35".to_string(), "Chicago".to_string()],
