use arrow2::array::{Array, PrimitiveArray, Utf8Array};
use arrow2::compute::sort::sort_to_indices;
use arrow2::datatypes::{DataType, Field, Schema};
use arrow2::record_batch::RecordBatch;
use std::sync::Arc;

fn sort_record_batch_by_columns(df0: RecordBatch, col_names: [&str; 2]) -> Result<RecordBatch, String> {
    // Get the indices of the columns to sort by
    let col_indices: Vec<usize> = col_names
        .iter()
        .map(|name| df0.schema().index_of(name).ok_or_else(|| format!("Column {} not found", name)))
        .collect::<Result<_, _>>()?;

    // Extract the arrays from the record batch
    let mut sort_keys = Vec::with_capacity(col_indices.len());
    for &index in &col_indices {
        let array = df0.column(index);
        sort_keys.push((array.clone(), true)); // true for ascending order
    }

    // Sort the indices based on the columns
    let sort_order = sort_to_indices(&sort_keys, None)
        .map_err(|e| format!("Error sorting record batch: {}", e))?;

    // Reorder the columns based on the sorted indices
    let sorted_columns = df0
        .columns()
        .iter()
        .map(|array| reorder_array(array, &sort_order))
        .collect::<Result<Vec<_>, _>>()?;

    // Create a new sorted record batch
    let sorted_df = RecordBatch::try_new(df0.schema().clone(), sorted_columns)
        .map_err(|e| format!("Error creating sorted record batch: {}", e))?;

    Ok(sorted_df)
}

fn reorder_array(array: &Arc<dyn Array>, sort_order: &[usize]) -> Result<Arc<dyn Array>, String> {
    match array.data_type() {
        DataType::Utf8 => {
            let utf8_array = array.as_any().downcast_ref::<Utf8Array<i32>>().unwrap();
