# Rust function to sort tabular data by columns

```rust
use arrow2::array::Array;
use arrow2::chunk::Chunk;
use arrow2::datatypes::Schema;

/// Sorts a tabular data object (Chunk) by var0 and var1 columns
/// 
/// # Arguments
/// * `df0` - A Chunk containing the tabular data to sort
/// * `var0_index` - Column index for the first sorting variable
/// * `var1_index` - Column index for the second sorting variable
///
/// # Returns
/// A new Chunk sorted by var0 and var1
pub fn sort_by_columns(
    df0: &Chunk<Box<dyn Array>>,
    var0_index: usize,
    var1_index: usize,
) -> Chunk<Box<dyn Array>> {
    let num_rows = df0.len();

    // Create indices array and sort it based on the two columns
    let mut indices: Vec<usize> = (0..num_rows).collect();

    indices.sort_by(|&a, &b| {
        let var0_col = &df0.arrays()[var0_index];
        let var1_col = &df0.arrays()[var1_index];

        // Compare var0 first
        let cmp = compare_values(var0_col, a, b);

        // If var0 values are equal, compare var1
        if cmp == std::cmp::Ordering::Equal {
            compare_values(var1_col, a, b)
        } else {
            cmp
        }
    });

    // Reorder all columns according to sorted indices
    let sorted_arrays: Vec<Box<dyn Array>> = df0
        .arrays()
        .iter()
        .map(|array| take_indices(array.as_ref(), &indices))
        .collect();

    Chunk::new(sorted_arrays)
}

/// Helper function to compare values at two indices in an array
fn compare_values(array: &dyn Array, a: usize, b: usize) -> std::cmp::Ordering {
    use arrow2::array::{
        Int32Array, Int64Array, Float32Array, Float64Array, Utf8Array,
    };

    if let Some(arr) = array.as_any().downcast_ref::<Int32Array>() {
        arr.value(a).cmp(&arr.value(b))
    } else if let Some(arr) = array.as_any().downcast_ref::<Int64Array>() {
        arr.value(a).cmp(&arr.value(b))
    } else if let Some(arr) = array.as_any().downcast_ref::<Float32Array>() {
        arr.value(a).partial_cmp(&arr.value(b)).unwrap_or(std::cmp::Ordering::Equal)
    } else if let Some(arr) = array.as_any().downcast_ref::<Float64Array>() {
        arr.value(a).partial_cmp(&arr.value(b)).unwrap_or(std::cmp::Ordering::Equal)
    } else if let Some(arr) = array.as_any().downcast_ref::<Utf8Array<i32>>() {
        arr.value(a).cmp(&arr.value(b))
    } else {
        std::cmp::Ordering::Equal
    }
}

/// Helper function to reorder array elements by indices
fn take_indices(array: &dyn Array, indices: &[usize]) -> Box<dyn Array> {
    arrow2::compute::take::take(array, &arrow2::array::UInt32Array::from_vec(
        indices.iter().map(|&i| i as u32).collect(),
    ))
    .expect("Failed to take indices")
}
```

## Usage Example:

