```rust
use std::collections::HashMap;

/// Group table columns by their labels and sum values per group.
///
/// # Arguments
/// * `table`  - slice of rows, each row is a Vec<f64> with the same length (number of columns)
/// * `labels` - Vec<String> giving the label for each column (length must equal number of columns)
///
/// # Returns
/// On success returns (group_labels, grouped_table)
/// * group_labels: Vec<String> - distinct labels in encountered order
/// * grouped_table: Vec<Vec<f64>> - rows x groups, where each cell is the sum of original columns in that group
///
/// # Errors
/// Returns Err if labels length doesn't match number of columns or rows have inconsistent lengths.
fn group_columns_sum(
    table: &[Vec<f64>],
    labels: &[String],
) -> Result<(Vec<String>, Vec<Vec<f64>>), String> {
    if table.is_empty() {
        // nothing to do: zero rows -> return zero rows and distinct labels in encountered order
        // but if there are no rows, we still need to check labels are consistent (we can accept any labels)
        // return empty grouped_table (0 rows) and distinct labels.
        let mut group_indices = HashMap::new();
        let mut group_labels = Vec::new();
        for label in labels {
            if !group_indices.contains_key(label) {
                group_indices.insert(label.clone(), group_labels.len());
                group_labels.push(label.clone());
            }
        }
        return Ok((group_labels, Vec::new()));
    }

    let n_rows = table.len();
    let n_cols = table[0].len();

    if labels.len() != n_cols {
        return Err(format!(
            "labels length ({}) does not match number of columns ({})",
            labels.len(),
            n_cols
        ));
    }

    // Build map from label -> group index, preserving first-seen order
    let mut group_indices: HashMap<String, usize> = HashMap::new();
    let mut group_labels: Vec<String> = Vec::new();
    let mut groups_for_col: Vec<usize> = Vec::with_capacity(n_cols);

    for label in labels {
        if let Some(&idx) = group_indices.get(label) {
            groups_for_col.push(idx);
        } else {
            let idx = group_labels.len();
            group_indices.insert(label.clone(), idx);
            group_labels.push(label.clone());
            groups_for_col.push(idx);
        }
