        // Iterate through all rows
        for row in &data {
            // Sum values in columns that belong to this group
            for (_, col_idx) in indices_group.iter() {
                if *col_idx < row.len() {
                    group_sum += row[*col_idx];
                }
            }
        }

        result.insert(label, group_sum);
    }

    result
