use ndarray_statistics::QuantileExt;
use std::collections::BinaryHeap;

fn indices_of_n_highest_values(arr: &Array1<f64>, n: usize) -> Vec<usize> {
    if n == 0 || arr.len() == 0 {
        return Vec::new();
    }

    // Create a max heap to store the indices and their corresponding values
    let mut heap = BinaryHeap::with_capacity(arr.len());

    // Push all elements with their indices into the heap
