use ndarray::Array1;
use std::cmp::Ordering;

/// Return indices of the `n` highest values in `values` (descending order).
/// Ties are broken by the sort stability of `sort_unstable_by`.
/// NaNs are treated as smaller than any numeric value (so they appear at the end).
pub fn top_n_indices(values: &Array1<f64>, n: usize) -> Vec<usize> {
    let len = values.len();
    let mut idxs: Vec<usize> = (0..len).collect();

    // Sort indices by comparing the corresponding values in `values`,
    // producing descending order (largest first).
    idxs.sort_unstable_by(|&i, &j| {
        let a = values[i];
        let b = values[j];

        let a_nan = a.is_nan();
        let b_nan = b.is_nan();

        // If either is NaN, put NaNs at the end (i.e., treat them as very small).
        match (a_nan, b_nan) {
            (true, true) => Ordering::Equal,
            (true, false) => Ordering::Greater, // a (i) after b (j)
            (false, true) => Ordering::Less,    // a (i) before b (j)
            (false, false) => {
                // For descending order compare b to a
                b.partial_cmp(&a).unwrap_or(Ordering::Equal)
            }
        }
    });

    idxs.truncate(n.min(idxs.len()));
    idxs
}

fn main() {
    let values = Array1::from(vec![3.2, 7.1, 5.5, f64::NAN, 7.1, 1.0]);
    let top3 = top_n_indices(&values, 3);
    println!("Top 3 indices: {:?}", top3);
    // Example output: Top 3 indices: [1, 4, 2]  (indices of values 7.1, 7.1, 5.5)
}
```

This function works directly with ndarray::Array1 and returns a Vec<usize> of positions of the top N values.

