# Rust Function to Find Indices of N Highest Values

```rust
use ndarray::{Array1, ArrayView1};
use ndarray_statistics::QuantileExt;

/// Finds the indices of the N highest values in an array.
///
/// # Arguments
/// * `data` - A slice of comparable values
/// * `n` - The number of highest values to find
///
/// # Returns
/// A Vec of indices corresponding to the N highest values, sorted in descending order by value
///
/// # Example
/// ```
/// let data = vec![10.5, 3.2, 7.8, 15.1, 2.3, 9.4];
/// let top_3_indices = find_n_highest_indices(&data, 3);
/// assert_eq!(top_3_indices, vec![3, 0, 5]); // 15.1, 10.5, 9.4
/// ```
pub fn find_n_highest_indices(data: &[f64], n: usize) -> Vec<usize> {
    if data.is_empty() || n == 0 {
        return Vec::new();
    }

    let n = n.min(data.len());
    let array = Array1::from_slice(data);

    // Create a vector of (index, value) pairs
    let mut indexed: Vec<(usize, f64)> = array
        .iter()
        .enumerate()
        .map(|(idx, &val)| (idx, val))
        .collect();

    // Sort by value in descending order
    indexed.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    // Extract the first n indices
    indexed.iter().take(n).map(|(idx, _)| *idx).collect()
}

/// Alternative implementation using quantile for finding threshold
pub fn find_n_highest_indices_quantile(data: &[f64], n: usize) -> Vec<usize> {
    if data.is_empty() || n == 0 {
        return Vec::new();
    }

    let n = n.min(data.len());
    let array = Array1::from_slice(data);

    // Calculate the quantile threshold for the top N values
    let quantile_pos = 1.0 - (n as f64 / data.len() as f64);
    let threshold = array.quantile_axis_mut(
        ndarray::Axis(0),
        quantile_pos,
        &ndarray_statistics::interpolate::Linear,
    );

    let threshold_val = threshold.item();

    // Collect indices where value is >= threshold, then sort by value
    let mut result: Vec<(usize, f64)> = array
        .iter()
        .enumerate()
        .filter(|(_, &val)| val >= threshold_val)
        .map(|(idx, &val)| (idx, val))
        .collect();

    result.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
    result.iter().take(n).map(|(idx, _)| *idx).collect()
}

#[cfg(test)]
