# Rust Function for Categorical to Integer Mapping using IndexedMap

```rust
use indexmap::IndexMap;

/// Maps categorical values in a column to unique integer indices.
///
/// Given a two-dimensional data table (Vec of Vecs) with categorical values
/// in a specified column, this function creates a mapping from each unique
/// category to a unique integer index and replaces the original values with
/// their corresponding indices.
///
/// # Arguments
///
/// * `df0` - A mutable 2D vector where each inner vector represents a row
/// * `col_index` - The index of the column to process (0-based)
///
/// # Returns
///
/// A mapping from the original categorical values to their assigned integer indices
///
/// # Example
///
/// ```
/// let mut df = vec![
///     vec!["apple".to_string(), "10".to_string()],
///     vec!["banana".to_string(), "20".to_string()],
///     vec!["apple".to_string(), "15".to_string()],
///     vec!["cherry".to_string(), "25".to_string()],
/// ];
///
/// let mapping = map_categorical_to_indices(&mut df, 0);
/// // df[0][0] is now "0", df[1][0] is now "1", etc.
/// // mapping contains: "apple" -> 0, "banana" -> 1, "cherry" -> 2
/// ```
fn map_categorical_to_indices(
    df0: &mut Vec<Vec<String>>,
    col_index: usize,
) -> IndexMap<String, usize> {
    // Create an IndexMap to store the mapping from category to index
    // IndexMap maintains insertion order, ensuring consistent indexing
    let mut category_map: IndexMap<String, usize> = IndexMap::new();
    let mut next_index = 0;

    // First pass: build the mapping of unique categories
    for row in df0.iter() {
        if col_index < row.len() {
            let category = row[col_index].clone();

            // If this category hasn't been seen before, assign it a new index
            if !category_map.contains_key(&category) {
                category_map.insert(category, next_index);
                next_index += 1;
            }
        }
    }

    // Second pass: replace categories with their indices
    for row in df0.iter_mut() {
        if col_index < row.len() {
            let category = &row[col_index];
            if let Some(&index) = category_map.get(category) {
                row[col_index] = index.to_string();
            }
        }
    }

    category_map
}

