fn remove_zero_columns(matrix: ArrayView2<f64>) -> Array2<f64> {
    // Iterate over each column and check if it contains only zeros
    let non_zero_columns: Vec<usize> = matrix
        .axis_iter(ndarray::Axis(1))
        .enumerate()
        .filter(|(_, col)| !col.iter().all(|&x| x == 0.0))
        .map(|(idx, _)| idx)
