/// Deletes all columns from the input matrix that contain only zero values.
/// 
/// # Arguments
/// * `matrix` - A reference to the input matrix
/// 
/// # Returns
/// A new matrix with zero-only columns removed
/// 
/// # Example
/// ```
/// use ndmatrix::Matrix;
/// 
/// let data = vec![
///     vec![1.0, 0.0, 3.0],
///     vec![2.0, 0.0, 4.0],
///     vec![5.0, 0.0, 6.0],
/// ];
/// let matrix = Matrix::from_vec(3, 3, data.into_iter().flatten().collect()).unwrap();
/// let result = delete_zero_columns(&matrix);
/// assert_eq!(result.cols(), 2); // Middle column removed
/// ```
fn delete_zero_columns(matrix: &Matrix<f64>) -> Matrix<f64> {
    let rows = matrix.rows();
    let cols = matrix.cols();

    // Identify which columns are all zeros
    let mut non_zero_cols = Vec::new();

    for col_idx in 0..cols {
        let mut is_all_zero = true;

        for row_idx in 0..rows {
            if let Ok(value) = matrix.get(row_idx, col_idx) {
                if *value != 0.0 {
                    is_all_zero = false;
                    break;
                }
            }
        }

        if !is_all_zero {
            non_zero_cols.push(col_idx);
        }
    }

    // Build new matrix with only non-zero columns
    let mut new_data = Vec::new();

    for row_idx in 0..rows {
        for &col_idx in &non_zero_cols {
            if let Ok(value) = matrix.get(row_idx, col_idx) {
                new_data.push(*value);
            }
        }
    }

    // Create new matrix with filtered columns
    let new_cols = non_zero_cols.len();
    Matrix::from_vec(rows, new_cols, new_data).unwrap_or_else(|_| {
        // If no columns remain, return empty matrix with same rows
        Matrix::from_vec(rows, 0, Vec::new()).unwrap()
    })
}

