use arrow::array::{Array, BooleanArray, Float64Array, StringArray};
use arrow::compute::kernels::zip::zip;
use arrow::datatypes::{DataType, Field, Schema};
use arrow::record_batch::RecordBatch;
use std::sync::Arc;

/// Replaces missing values (nulls) in a specified column with values from another column.
///
/// # Arguments
/// * `batch` - The input RecordBatch containing the data
/// * `target_column` - The name of the column where missing values should be replaced
/// * `source_column` - The name of the column providing replacement values
///
/// # Returns
/// * `Result<RecordBatch, ArrowError>` - A new RecordBatch with the target column's missing values replaced
///
/// # Panics
/// * If either column name doesn't exist in the schema
/// * If the columns have different data types
/// * If the columns have different lengths
pub fn replace_missing_values(
    batch: &RecordBatch,
    target_column: &str,
    source_column: &str,
) -> Result<RecordBatch, arrow::error::ArrowError> {
    // Get column indices
    let schema = batch.schema();
    let target_idx = schema.index_of(target_column)?;
    let source_idx = schema.index_of(source_column)?;

    // Get the arrays
    let target_array = batch.column(target_idx);
    let source_array = batch.column(source_idx);

    // Verify data types match
    let target_type = target_array.data_type();
    let source_type = source_array.data_type();

    if target_type != source_type {
        return Err(arrow::error::ArrowError::InvalidArgumentError(
            format!(
                "Column types must match. Target column '{}' has type {:?}, source column '{}' has type {:?}",
                target_column, target_type, source_column, source_type
            )
        ));
    }

    // Create a boolean mask for null values in the target column
    let null_mask = target_array.is_null();

    // Use zip to combine values: take from target where not null, from source where null
    let replaced_array = zip(&null_mask, target_array.as_ref(), source_array.as_ref())?;

    // Build new columns
    let mut new_columns: Vec<Arc<dyn Array>> = Vec::with_capacity(batch.num_columns());

    for i in 0..batch.num_columns() {
        if i == target_idx {
            new_columns.push(replaced_array);
        } else {
            new_columns.push(batch.column(i).clone());
        }
    }

    // Create new RecordBatch
    RecordBatch::try_new(schema, new_columns)
}

