use std::collections::HashSet;
use std::hash::Hash;

/// Compare two sequences and return indices in seq0 where elements also appear in seq1.
///
/// This function uses a HashSet for efficient membership checks.
///
/// # Arguments
///
/// * `seq0` - The sequence to find indices in.
/// * `seq1` - The sequence to check for membership.
///
/// # Returns
///
/// A vector of indices in `seq0` where the element at that position also appears in `seq1`.
pub fn compare_sequences<T: Eq + Hash + Clone>(seq0: &[T], seq1: &[T]) -> Vec<usize> {
