/// ```
pub fn filter_not_empty<F, A>(lst0: F) -> F
where
    F: Foldable + Pure<A>,
    A: Monoid + PartialEq,
{
    lst0.fold_left(F::pure(), |acc, elem| {
        if elem != A::mempty() {
            // We need to append the element to the accumulator
            // Since we're using fp-base, we can use the monoid instance for collections
            acc.mappend(F::pure(elem))
        } else {
            acc
        }
    })
}

