use linfa::prelude::*;
use linfa_forest::DecisionTreeClassifier;
use std::fmt;

// Helper trait to format decision tree rules in a human-readable way
trait DecisionTreeRuleFormatter {
    fn format_rules(&self, feature_names: &[String]) -> Vec<String>;
}

// Implement the trait for DecisionTreeClassifier
impl DecisionTreeRuleFormatter for DecisionTreeClassifier {
    fn format_rules(&self, feature_names: &[String]) -> Vec<String> {
        let mut rules = Vec::new();

        // Helper function to recursively traverse the tree and build rules
        fn build_rules(
            node: &linfa_forest::DecisionTreeNode,
            feature_names: &[String],
            current_rule: &mut String,
            rules: &mut Vec<String>,
        ) {
            // If this is a leaf node, add the rule with the predicted class
            if node.is_leaf() {
                let rule = format!("{} => {}", current_rule, node.predicted_class());
                rules.push(rule);
                return;
            }

            // Get the feature index and threshold for this split
            let feature_idx = node.split_feature();
            let threshold = node.split_threshold();

            // Get the feature name
            let feature_name = if feature_idx < feature_names.len() {
                feature_names[feature_idx].clone()
            } else {
                format!("feature_{}", feature_idx)
            };

            // Create the condition for the left branch
            let condition = format!("{} <= {}", feature_name, threshold);

            // Add the condition to the current rule
            if !current_rule.is_empty() {
                current_rule.push_str(" AND ");
            }
            current_rule.push_str(&condition);

            // Recursively process left and right branches
            if let Some(left_node) = node.left() {
                build_rules(left_node, feature_names, current_rule, rules);
            }

            if let Some(right_node) = node.right() {
                let mut right_rule = current_rule.clone();
                right_rule.push_str(&format!(" AND {} > {}", feature_name, threshold));
                build_rules(right_node, feature_names, &mut right_rule, rules);
            }
        }

        // Start building rules from the root
        build_rules(&self.tree, feature_names, &mut String::new(), &mut rules);

        rules
    }
}

