pub fn extract_decision_rules(tree: &Tree, feature_names: &[String]) -> Vec<String> {
    let mut rules = Vec::new();

    // Define a recursive function to extract rules from the tree
    extract_rules_recursive(tree, feature_names, &mut rules, Vec::new());

    rules
