/// Recursively extract rules from the decision tree.
fn extract_rules_recursive(
    tree: &Tree,
    feature_names: &[String],
    rules: &mut Vec<String>,
    current_rule: Vec<String>,
) {
    // Base case: If the tree is a leaf node, add the current rule to the list
    if tree.is_leaf() {
        let mut rule = current_rule.clone();
        rule.push(format!("Predicted class: {}", tree.predicted_class()));
        rules.push(rule.join(" AND "));
