    let mut left_rule = current_rule.clone();
    left_rule.push(format!("{} <= {}", feature_name, threshold));
    extract_rules_recursive(tree.left(), feature_names, rules, left_rule);

    let mut right_rule = current_rule.clone();
    right_rule.push(format!("{} > {}", feature_name, threshold));
    extract_rules_recursive(tree.right(), feature_names, rules, right_rule);
}

