/// Recursively traverses the decision tree to extract rules
fn traverse_tree<F: Float>(
    tree: &DecisionTree<F>,
    node_index: usize,
    current_conditions: &mut Vec<String>,
    rules: &mut Vec<String>,
    feature_names: &[&str],
) {
    // Get the node information
    let node = tree.get_node(node_index);

    // Check if this is a leaf node
    if node.is_leaf() {
        // Create the rule string from accumulated conditions
        let mut rule = String::new();
        rule.push_str("IF ");

        for (i, condition) in current_conditions.iter().enumerate() {
            if i > 0 {
                rule.push_str(" AND ");
            }
            rule.push_str(condition);
        }

        // Add the prediction value
        let prediction = node.prediction();
        write!(rule, " THEN predict = {}", prediction).unwrap();

        rules.push(rule);
    } else {
        // Internal node - get split information
        let split_feature = node.split_feature();
        let split_threshold = node.split_threshold();

        // Get feature name (handle potential index out of bounds)
        let feature_name = if split_feature < feature_names.len() {
            feature_names[split_feature]
        } else {
            &format!("feature_{}", split_feature)
        };

        // Left child (feature <= threshold)
        let left_condition = format!("{} <= {:.4}", feature_name, split_threshold);
        current_conditions.push(left_condition);
        traverse_tree(tree, node.left_child(), current_conditions, rules, feature_names);
        current_conditions.pop();

        // Right child (feature > threshold)
        let right_condition = format!("{} > {:.4}", feature_name, split_threshold);
        current_conditions.push(right_condition);
        traverse_tree(tree, node.right_child(), current_conditions, rules, feature_names);
        current_conditions.pop();
    }
