/// Helper function to reorder columns in a Chunk
fn reorder_columns(
    data: Chunk<Arc<dyn Array>>,
    desired_order: &[&str],
) -> Result<Chunk<Arc<dyn Array>>> {
    let fields = data.fields().to_vec();

    // Create a mapping from column name to index
    let name_to_idx: std::collections::HashMap<&str, usize> = fields
        .iter()
        .enumerate()
        .map(|(i, f)| (f.name(), i))
        .collect();

    // Build the reordered arrays
    let mut reordered_arrays: Vec<Arc<dyn Array>> = Vec::with_capacity(desired_order.len());
    let mut reordered_fields: Vec<Field> = Vec::with_capacity(desired_order.len());

    for name in desired_order {
        let idx = name_to_idx.get(name)
            .ok_or_else(|| arrow2::error::Error::InvalidArgumentError(
                format!("Column '{}' not found in data", name)
            ))?;
        reordered_arrays.push(data.arrays()[*idx].clone());
        reordered_fields.push(fields[*idx].clone());
    }

    Ok(Chunk::new(reordered_arrays).with_fields(reordered_fields))
}

