use arrow::datatypes::Schema;
use arrow::record_batch::RecordBatch;
use std::sync::Arc;

/// Splits and expands entries in the "str0" column using a delimiter,
/// then rearranges columns to match the order specified in str1.
///
/// # Arguments
/// * `batch` - The input RecordBatch
/// * `var1` - The delimiter to use for splitting the str0 column
/// * `str1` - A comma-separated string specifying the desired column order
///
/// # Returns
/// A new RecordBatch with the str0 column split/expanded and columns reordered
pub fn split_expand_and_reorder(
    batch: RecordBatch,
    var1: &str,
    str1: &str,
) -> Result<RecordBatch, Box<dyn std::error::Error>> {
    let schema = batch.schema();

    // Find the str0 column
    let str0_index = schema
        .column_with_name("str0")
        .ok_or("Column 'str0' not found")?
        .0;

    let str0_array = batch
        .column(str0_index)
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or("Column 'str0' is not a string column")?;

    // Split the str0 column and track which row each split value came from
    let mut split_values: Vec<String> = Vec::new();
    let mut row_indices: Vec<usize> = Vec::new();

    for (i, value) in str0_array.iter().enumerate() {
        if let Some(val) = value {
            for split_val in val.split(var1) {
                split_values.push(split_val.to_string());
                row_indices.push(i);
            }
        }
    }

    let num_split_rows = split_values.len();

    // Create the new split str0 column
    let new_str0 = StringArray::from(split_values);

    // Expand all other columns based on row_indices
    let mut new_columns: Vec<Arc<dyn Array>> = Vec::new();
    let mut new_column_names: Vec<String> = Vec::new();

    for (idx, field) in schema.fields().iter().enumerate() {
        let col_name = field.name().clone();

        if idx == str0_index {
            // Use the new split str0 column
            new_columns.push(Arc::new(new_str0.clone()));
            new_column_names.push(col_name);
        } else {
            // Expand other columns by repeating values according to row_indices
            let col = batch.column(idx);
            let expanded = expand_column(col, &row_indices)?;
            new_columns.push(expanded);
            new_column_names.push(col_name);
        }
    }

    // Parse the desired column order from str1
    let desired_order: Vec<&str> = str1.split(',').map(|s| s.trim()).collect();

    // Reorder columns
    let mut reordered_columns: Vec<Arc<dyn Array>> = Vec::new();
    let mut reordered_names: Vec<String> = Vec::new();

    for col_name in desired_order {
        if let Some(pos) = new_column_names.iter().position(|n| n == col_name) {
            reordered_columns.push(new_columns[pos].clone());
            reordered_names.push(col_name.to_string());
        } else {
            return Err(format!("Column '{}' not found in dataset", col_name).into());
        }
    }

    // Create new schema with reordered columns
    let new_fields: Vec<_> = reordered_names
        .iter()
        .zip(reordered_columns.iter())
        .map(|(name, col)| arrow::datatypes::Field::new(name, col.data_type().clone(), true))
        .collect();

    let new_schema = Arc::new(Schema::new(new_fields));

    // Create and return the new RecordBatch
    Ok(RecordBatch::try_new(new_schema, reordered_columns)?)
}

/// Helper function to expand a column based on row indices
fn expand_column(
    col: &Arc<dyn Array>,
    row_indices: &[usize],
) -> Result<Arc<dyn Array>, Box<dyn std::error::Error>> {
    use arrow::array::*;

    let data_type = col.data_type();

    match data_type {
        arrow::datatypes::DataType::Utf8 => {
            let string_col = col.as_any().downcast_ref::<StringArray>().unwrap();
            let expanded: Vec<Option<&str>> = row_indices
                .iter()
                .map(|&i| string_col.get(i))
                .collect();
            Ok(Arc::new(StringArray::from(expanded)))
        }
        arrow::datatypes::DataType::Int64 => {
            let int_col = col.as_any().downcast_ref::<Int64Array>().unwrap();
            let expanded: Vec<Option<i64>> = row_indices
                .iter()
                .map(|&i| int_col.get(i))
                .collect();
            Ok(Arc::new(Int64Array::from(expanded)))
        }
        arrow::datatypes::DataType::Int32 => {
            let int_col = col.as_any().downcast_ref::<Int32Array>().unwrap();
            let expanded: Vec<Option<i32>> = row_indices
                .iter()
                .map(|&i| int_col.get(i))
                .collect();
            Ok(Arc::new(Int32Array::from(expanded)))
        }
        arrow::datatypes::DataType::Float64 => {
            let float_col = col.as_any().downcast_ref::<Float64Array>().unwrap();
            let expanded: Vec<Option<f64>> = row_indices
                .iter()
                .map(|&i| float_col.get(i))
                .collect();
            Ok(Arc::new(Float64Array::from(expanded)))
        }
        _ => Err("Unsupported data type".into()),
    }
}
