use indexmap::IndexMap;

/// Merge base and new columns, ensuring `priority` columns appear in the exact
/// order given, while preserving the relative order of all other columns.
///
/// - `base` and `new_cols` map column name -> column values (Vec<V>).
/// - Columns from `new_cols` overwrite values for any existing column names,
///   but do not change their position if the column already existed in `base`.
/// - The final table's column order is constructed from (base keys then
///   appended new keys), with the specified priority columns moved together
///   as a block (in the specified order) and inserted at the earliest position
///   where any priority column originally occurred. All non-priority columns
///   retain their relative order.
///
/// Returns a new IndexMap with the merged data and the desired column ordering.
fn merge_tables_with_priority<V: Clone>(
    base: &IndexMap<String, Vec<V>>,
    new_cols: &IndexMap<String, Vec<V>>,
    priority: &[&str],
) -> IndexMap<String, Vec<V>> {
    // Start with base (preserving base order)
    let mut combined: IndexMap<String, Vec<V>> = base.clone();

    // Insert/overwrite values from new_cols. Inserting an existing key replaces
    // the value but keeps its original position in IndexMap.
    for (k, v) in new_cols.iter() {
        combined.insert(k.clone(), v.clone());
    }

    // Collect keys in their current order
    let keys: Vec<String> = combined.keys().cloned().collect();

    // Build set of priority columns that actually exist in combined
    use std::collections::HashSet;
    let present_priority: Vec<String> = priority
        .iter()
        .filter_map(|&p| {
            if combined.contains_key(p) {
                Some(p.to_string())
            } else {
                None
            }
        })
        .collect();
    if present_priority.is_empty() {
        return combined; // nothing to reorder
    }
    let priority_set: HashSet<&str> = present_priority.iter().map(|s| s.as_str()).collect();

    // Find earliest index where any priority column occurs
    let first_priority_pos = keys
        .iter()
        .position(|k| priority_set.contains(k.as_str()))
        .unwrap(); // safe because present_priority is non-empty

    // Build final order:
    let mut final_keys: Vec<String> = Vec::with_capacity(keys.len());

    // 1) All non-priority keys before the insertion point (preserve relative order)
    for k in &keys[..first_priority_pos] {
        if !priority_set.contains(k.as_str()) {
            final_keys.push(k.clone());
        }
    }

    // 2) Append the priority columns in the exact specified order (but only those present)
    for p in &present_priority {
        final_keys.push(p.clone());
    }

    // 3) Append remaining non-priority keys that were after the insertion point
    for k in &keys[first_priority_pos..] {
        if !priority_set.contains(k.as_str()) {
            final_keys.push(k.clone());
        }
    }

    // Build final IndexMap in that order
    let mut result: IndexMap<String, Vec<V>> = IndexMap::with_capacity(final_keys.len());
    for k in final_keys {
        // Safe to unwrap because keys came from combined
        result.insert(k.clone(), combined.get(&k).unwrap().clone());
    }

    result
}

fn main() {
    // Example usage
    let mut base: IndexMap<String, Vec<String>> = IndexMap::new();
    base.insert("id".to_string(), vec!["1".into(), "2".into()]);
    base.insert("name".to_string(), vec!["Alice".into(), "Bob".into()]);
    base.insert("age".to_string(), vec!["30".into(), "25".into()]);

    let mut new_cols: IndexMap<String, Vec<String>> = IndexMap::new();
    new_cols.insert("score".to_string(), vec!["100".into(), "95".into()]);
    new_cols.insert("name".to_string(), vec!["ALICE".into(), "BOB".into()]); // will overwrite values

