        println!("{}", k);
    }

    // Expected ordering:
    // since "score" did not exist in base and appended at end, and "name" existed early,
    // the earliest occurrence among priority columns is "name" (position 1),
    // so the function will insert the [score, name] block at that position.
    //
    // Final column order: id, score, name, age
}
