/// Concatenates new columns onto a base table while preserving column order.
/// 
/// Given a base table and a list of column names defining the desired priority order,
/// produces a merged table in which the specified columns appear in that exact sequence
/// while all other columns retain their original relative positions.
///
/// # Arguments
/// * `base_table` - The original table as a vector of IndexMaps (rows)
/// * `new_columns` - A HashMap where keys are column names and values are vectors of new values
/// * `priority_columns` - A list of column names defining the desired order for specified columns
///
/// # Returns
/// A new vector of IndexMaps with columns in the specified order
///
/// # Panics
/// Panics if any new column has a different length than the base table
pub fn merge_tables_with_order(
    base_table: &[IndexMap<String, String>],
    new_columns: &HashMap<String, Vec<String>>,
    priority_columns: &[String],
) -> Vec<IndexMap<String, String>> {
    if base_table.is_empty() {
        return Vec::new();
    }

    let num_rows = base_table.len();

    // Validate that all new columns have the correct length
    for (col_name, values) in new_columns {
        assert_eq!(
            values.len(),
            num_rows,
            "Column '{}' has {} values, but base table has {} rows",
            col_name,
            values.len(),
            num_rows
        );
    }

    // Collect all column names from the base table
    let base_columns: Vec<String> = base_table[0].keys().cloned().collect();

    // Create a set of priority columns for quick lookup
    let priority_set: std::collections::HashSet<&str> = 
        priority_columns.iter().map(|s| s.as_str()).collect();

    // Build the final column order
    let mut final_order: Vec<String> = Vec::new();

    // First, add priority columns that exist in the base table or new columns
    for col in priority_columns {
        if base_columns.contains(col) || new_columns.contains_key(col) {
            final_order.push(col.clone());
        }
    }

    // Then, add remaining base columns that weren't in priority order
    for col in &base_columns {
        if !priority_set.contains(col.as_str()) {
            final_order.push(col.clone());
        }
    }

    // Add any new columns that weren't in priority order
    for col in new_columns.keys() {
        if !priority_set.contains(col.as_str()) && !base_columns.contains(col) {
            final_order.push(col.clone());
        }
    }

    // Build the merged table
    let mut merged_table: Vec<IndexMap<String, String>> = Vec::with_capacity(num_rows);

    for row_idx in 0..num_rows {
        let mut new_row = IndexMap::new();

        for col_name in &final_order {
            let value = if row_idx < base_table.len() && base_table[row_idx].contains_key(col_name) {
                // Value from base table
                base_table[row_idx][col_name].clone()
            } else if let Some(values) = new_columns.get(col_name) {
                // Value from new columns
                values[row_idx].clone()
            } else {
                // Column not found - this shouldn't happen with our ordering logic
                String::new()
            };

            new_row.insert(col_name.clone(), value);
        }

        merged_table.push(new_row);
    }

    merged_table
}

