use datumframe::{Table, Series, Index, MultiIndex};
use std::error::Error;

/// Group df0 by the column `var0` and return a new table whose index is a hierarchical
/// (multi-level) index where:
///  - level 0 is the group key values from `var0`
///  - level 1 is the original row index (or positional index if the table has no index)
///
/// This function is written to be idiomatic with the common datumframe API:
///  - `table.groupby(&[col])` returns an iterator of `(key_row, subtable)` where `key_row`
///    holds the grouping key values for that group and `subtable` is the table of rows in that group.
///  - `Table::vstack(...)` concatenates subtables vertically preserving row order.
///  - `table.index()` returns an Option<Index>, and `Index::as_strings()` gives Vec<String>
///    (if the concrete API differs slightly adapt the small accessors).
pub fn group_to_hierarchical(
    df0: &Table,
    var0: &str,
) -> Result<Table, Box<dyn Error>> {
    // ensure the grouping column exists
    if !df0.has_column(var0) {
        return Err(format!("column '{}' not found in table", var0).into());
    }

    // Perform the group-by. The returned object should be iterable as (key_row, subtable).
    // Adjust call if your datumframe version exposes a different API (e.g. df0.groupby(&[var0])).
    let groups = df0.groupby(&[var0])?;

    // Prepare vectors for the two index levels and for collecting subtables in order.
    let mut level0_vals: Vec<String> = Vec::new(); // group key values (var0)
    let mut level1_vals: Vec<String> = Vec::new(); // original row indices (or positions)
    let mut subtables: Vec<Table> = Vec::new();

    for (key_row, subtable) in groups {
        // Extract the group key value for var0 as string
        // key_row.get_str(var0) is a placeholder for whatever accessor returns the grouping key value.
        let key_val = key_row.get(var0)
            .ok_or_else(|| format!("group key does not contain column '{}'", var0))?
            .to_string();

        // Determine original index labels for rows in this subtable. If the original table had an index,
        // subtable.index() should reflect those labels; otherwise, we'll use positional indices.
        let idx_labels: Vec<String> = match subtable.index() {
            Some(idx) => {
                // assume Index can be converted to Vec<String>; adapt as necessary
                idx.as_strings()?
            }
            None => {
                // fallback to positional indices "0", "1", ...
                (0..subtable.nrows()).map(|i| i.to_string()).collect()
            }
        };

        // For each row in this group, record the (group_key, original_index) pair.
        for label in idx_labels.iter() {
            level0_vals.push(key_val.clone());
            level1_vals.push(label.clone());
        }

        // keep the subtable for concatenation later
        subtables.push(subtable);
    }

    // Concatenate all group subtables back into a single table with rows ordered by groups.
    // Table::vstack concatenates a slice/Vec of tables vertically.
    let mut result = Table::vstack(&subtables)?;

    // Build Series for each index level
    let level0_series = Series::from_strings(level0_vals);
    let level1_series = Series::from_strings(level1_vals);

    // Create a MultiIndex from the two level series and attach names to levels
    let multi = MultiIndex::from_arrays(
        vec![level0_series, level1_series],
        Some(vec![var0.to_string(), "row_index".to_string()]),
    )?;

    // Set the multi-index on the resulting table
    result.set_index(Index::Multi(multi));

    Ok(result)
}

