/// * `key` - The key in each record to sort by
/// * `order` - A vector of values defining the custom order (first element is highest priority)
///
/// # Returns
/// A new vector of records sorted according to the custom order
///
/// # Example
/// ```
/// use serde_json::json;
///
/// let records = vec![
///     json!({"name": "apple", "color": "red"}),
///     json!({"name": "banana", "color": "yellow"}),
///     json!({"name": "cherry", "color": "red"}),
/// ];
/// let order = vec!["yellow", "red"];
///
/// let sorted = sort_by_custom_order(records, "color", &order);
/// // sorted will contain records with "yellow" first, then "red"
/// ```
pub fn sort_by_custom_order(
    records: Vec<Value>,
    key: &str,
    order: &[Value],
) -> Vec<Value> {
    // Create a mapping from each value in the order to its position
    let mut value_to_position = SortedVec::new();
    for (pos, value) in order.iter().enumerate() {
        value_to_position.insert(value.clone(), pos);
    }

    // Sort the records based on the custom order
    let mut sorted_records = records;
    sorted_records.sort_by(|a, b| {
        // Get the values to compare
        let a_value = a.get(key).and_then(|v| v.as_str()).unwrap_or("");
        let b_value = b.get(key).and_then(|v| v.as_str()).unwrap_or("");

        // Get their positions in the custom order
        let a_pos = value_to_position.get(a_value).copied().unwrap_or(usize::MAX);
        let b_pos = value_to_position.get(b_value).copied().unwrap_or(usize::MAX);

        a_pos.cmp(&b_pos)
    });

    sorted_records
}

