///
/// let mut records = vec![
///     HashMap::from([("name".to_string(), "Charlie".to_string())]),
///     HashMap::from([("name".to_string(), "Alice".to_string())]),
///     HashMap::from([("name".to_string(), "Bob".to_string())]),
/// ];
///
/// let order = vec!["Alice", "Bob", "Charlie"];
/// sort_by_key_order(&mut records, "name", &order);
///
/// assert_eq!(records[0]["name"], "Alice");
/// assert_eq!(records[1]["name"], "Bob");
/// assert_eq!(records[2]["name"], "Charlie");
/// ```
#[sorted]
pub fn sort_by_key_order<T>(
    records: &mut [HashMap<String, String>],
    key: &str,
    order_sequence: &[T],
) where
    T: Eq + std::hash::Hash + Clone + std::fmt::Debug,
    String: PartialEq<T>,
{
    // Build a mapping from each value to its position in the order sequence
    let position_map: HashMap<&T, usize> = order_sequence
        .iter()
        .enumerate()
        .map(|(index, value)| (value, index))
        .collect();

    // Sort the records using the position map
    records.sort_by(|a, b| {
        let a_value = a.get(key);
        let b_value = b.get(key);

        match (a_value, b_value) {
            (Some(a_val), Some(b_val)) => {
                let a_pos = position_map.get(a_val);
                let b_pos = position_map.get(b_val);

                match (a_pos, b_pos) {
                    (Some(a_pos), Some(b_pos)) => a_pos.cmp(b_pos),
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (None, None) => a_val.cmp(b_val),
                }
            }
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => std::cmp::Ordering::Equal,
        }
    });
}

