use futures::stream::{self, StreamExt};

pub async fn combine_lists<T>(
    lists: Vec<Vec<T>>,
    sequence: Vec<usize>,
) -> Vec<T> {
    // Create an iterator from each list
    let iterators: Vec<_> = lists.into_iter()
        .map(|list| stream::iter(list))
        .collect();

    // Flatten the iterators into a single stream
    let combined_stream = stream::iter(sequence)
        .then(move |index| {
            let iter_copy = iterators.clone();
            async move {
                if let Some(stream) = iter_copy.get(index) {
                    // Draw the next item from the corresponding stream
                    stream.next().await
                } else {
                    None
                }
            }
        });

    // Collect the results into a single list
    combined_stream.filter_map(|item| async {
        item
    }).collect().await
}

