use streaming_iterator::{StreamingIterator, convert::IntoStreamingIterator};

/// Combine a variable number of lists into a single list by following `sequence`.
///
/// `inputs` is a Vec of Vec<T> (each inner Vec is a source stream).
/// `sequence` is an iterator of indices (usize) telling from which input list to draw the next element.
///
/// Returns a Vec<T> of drawn elements in order. If a sequence index is invalid or the chosen stream
/// is exhausted, that sequence step is skipped.
///
/// T must implement Clone because streaming iterators yield references.
pub fn combine_by_sequence<T, S>(inputs: Vec<Vec<T>>, sequence: S) -> Vec<T>
where
    T: Clone,
    S: IntoIterator<Item = usize>,
{
    // Convert each Vec<T> into a streaming iterator
    let mut streams: Vec<_> = inputs
        .into_iter()
        .map(|v| v.into_iter().into_streaming_iter())
        .collect();

    let mut out = Vec::new();

    for idx in sequence {
        if let Some(stream) = streams.get_mut(idx) {
            // Move the stream to its next item
            stream.advance();
            // If there is a current item, clone it into the output
            if let Some(item_ref) = stream.get() {
                out.push(item_ref.clone());
            } // else exhausted -> skip this sequence step
        } // else invalid index -> skip this sequence step
    }

    out
}

