/// or if a list runs out of elements before the sequence is complete
pub fn combine_lists_by_sequence<T: Clone>(
    lists: Vec<Vec<T>>,
    sequence: &[usize],
) -> Vec<T> {
    // Convert each list into a VecDeque for efficient front removal
    let mut list_queues: Vec<VecDeque<T>> = lists
        .into_iter()
        .map(|list| VecDeque::from(list))
        .collect();

    // Create a stream iterator from the sequence
    let result: Vec<T> = StreamIterator::from_iter(sequence.iter().copied())
        .map(|index| {
            // Get the queue for this index
            let queue = list_queues
                .get_mut(index)
                .unwrap_or_else(|| panic!("Index {} is out of bounds for lists", index));

            // Pop the front element
            queue
                .pop_front()
                .unwrap_or_else(|| panic!("List at index {} ran out of elements", index))
        })
        .collect();

    result
}

