///     vec![1, 2, 3],
///     vec![10, 20],
///     vec![100, 200, 300]
/// ];
/// let sequence = vec![0, 1, 0, 2, 1, 2, 0, 2];
/// let result = combine_by_sequence(lists, sequence);
/// assert_eq!(result, vec![1, 10, 2, 100, 20, 200, 3, 300]);
/// ```
fn combine_by_sequence<T: Clone>(
    lists: Vec<Vec<T>>,
    sequence: Vec<usize>,
) -> Vec<T> {
    // Create mutable iterators for each input list
    let iterators: Vec<_> = lists
        .into_iter()
        .map(|list| list.into_iter())
        .collect();

    // Create a StreamIterator that manages multiple iterators
    let mut stream = StreamIterator::new(iterators);

    let mut result = Vec::new();

    // Follow the sequence and collect elements
    for &list_index in &sequence {
        if list_index < stream.len() {
            // Get the next element from the specified iterator
            if let Some(element) = stream.get_mut(list_index).and_then(|it| it.next()) {
                result.push(element);
            }
        }
    }

    result
}

