pub fn find_roots_lm<F>(
    equations: F,
    initial_guess: Vector2<f64>,
    max_iterations: usize,
    tolerance: f64,
) -> (Vector2<f64>, bool, usize)
where
    F: Fn(&DVector<f64>) -> DVector<f64>,
{
