use chrono::{DateTime, FixedOffset};
use std::error::Error;

/// Minimal chronal-style interval type used here.
/// This is a small local implementation (closed-open intervals).
mod chronal {
    use chrono::DateTime;
    use chrono::FixedOffset;

    #[derive(Clone, Debug)]
    pub struct Interval(pub DateTime<FixedOffset>, pub DateTime<FixedOffset>);

    impl Interval {
        /// Constructs a closed-open interval [start, end)
        pub fn closed_open(start: DateTime<FixedOffset>, end: DateTime<FixedOffset>) -> Self {
            Interval(start, end)
        }

        /// Returns true if `t` is in [start, end)
        pub fn contains(&self, t: &DateTime<FixedOffset>) -> bool {
            self.0 <= *t && *t < self.1
        }
    }
}

/// Segment each entry in `str0` into intervals defined by `lst0`.
///
/// Inputs:
/// - `str0`: slice of timestamp strings (RFC3339, e.g. "2023-04-01T12:34:56+00:00")
///           representing the column values to segment.
/// - `lst0`: slice of timestamp strings (RFC3339) representing boundary points.
///           Intervals are formed between consecutive sorted boundaries: [b0,b1), [b1,b2), ...
///
/// Output:
/// - Vec<Option<chronal::Interval>> with the same length as `str0`. Each element is:
///     - Some(interval) if the corresponding value falls into one of the intervals
///     - None if it doesn't fall into any interval (before first boundary or after last)
///
/// Errors:
/// - Returns an error if any timestamp (in `str0` or `lst0`) fails to parse, or if there are
///   fewer than two distinct boundaries (no intervals).
pub fn segment_str0_into_intervals(
    str0: &[&str],
    lst0: &[&str],
) -> Result<Vec<Option<chronal::Interval>>, Box<dyn Error>> {
    // Parse boundaries into DateTime<FixedOffset>
    let mut bounds: Vec<DateTime<FixedOffset>> = lst0
        .iter()
        .map(|s| DateTime::parse_from_rfc3339(s))
        .collect::<Result<Vec<_>, _>>()?;

    // Sort and deduplicate boundaries
    bounds.sort();
    bounds.dedup();

    if bounds.len() < 2 {
        return Err("need at least two distinct boundaries in lst0 to form intervals".into());
    }

    // Build intervals [b[i], b[i+1])
    let intervals: Vec<chronal::Interval> = bounds
        .windows(2)
        .map(|w| chronal::Interval::closed_open(w[0], w[1]))
        .collect();

    // For each entry in str0, parse and find its interval
    let mut result: Vec<Option<chronal::Interval>> = Vec::with_capacity(str0.len());

    for s in str0.iter() {
        let dt = DateTime::parse_from_rfc3339(s)?;
        let found = intervals
            .iter()
            .find(|interval| interval.contains(&dt))
            .cloned();
        result.push(found);
    }

    Ok(result)
}

