        let boundaries = vec![
            "2024-01-01T00:00:00Z",
            "2024-01-15T00:00:00Z",
            "2024-02-01T00:00:00Z",
        ];

        let result = segment_time_intervals(entries, boundaries)
            .expect("Segmentation failed");

