```rust
use timeparse::parse;
use std::error::Error;

/// Converts a 'Date' column in a dataset from string format "DD-MM-YYYY" to native date-time values.
/// 
/// # Arguments
/// * `df0` - A mutable vector of hashmaps where each map represents a row with column names as keys
/// 
/// # Returns
/// * `Result<(), Box<dyn Error>>` - Success or error message
fn convert_date_column(
    df0: &mut Vec<std::collections::HashMap<String, String>>,
) -> Result<(), Box<dyn Error>> {
    for row in df0.iter_mut() {
        if let Some(date_str) = row.get("Date") {
            // Parse DD-MM-YYYY format
            let parts: Vec<&str> = date_str.split('-').collect();

            if parts.len() != 3 {
                return Err(format!("Invalid date format: {}", date_str).into());
            }

            let day: u32 = parts[0].parse()?;
            let month: u32 = parts[1].parse()?;
            let year: i32 = parts[2].parse()?;

            // Construct time string in a standard format for parsing
            let standardized = format!("{:04}-{:02}-{:02}T00:00:00Z", year, month, day);

            // Parse using timeparse
            let _duration = parse(&standardized)?;

            // Store the standardized datetime string back (or you can store the parsed duration)
            row.insert("Date".to_string(), standardized);
        }
    }

    Ok(())
}

