        .filter(|&&x| x != missing_value)
        .sum();
    let count = values.iter()
        .filter(|&&x| x != missing_value)
        .count();

    let column_mean = if count > 0 {
        sum / count as f64
    } else {
        // If all values are missing, we can't compute a mean - return original values
        return Ok(());
