// itertools = "0.10"

use std::collections::HashSet;
use std::hash::Hash;
use itertools::Itertools;

/// Remove rows that are duplicates w.r.t. the values in the specified columns.
///
/// - `table`: an iterator of rows (each row is `Vec<T>`). The function consumes the rows.
/// - `cols`: slice of column indices to consider when detecting duplicates.
/// 
/// If a row does not contain all specified column indices the function returns an Err describing the
/// first out-of-range index encountered.
///
/// Returns `Ok(filtered_table)` where `filtered_table` contains only the first occurrence of each
/// distinct key (the values at `cols`).
pub fn remove_duplicate_rows_by_columns<T, I>(
    table: I,
    cols: &[usize],
) -> Result<Vec<Vec<T>>, String>
where
    T: Clone + Eq + Hash,
    I: IntoIterator<Item = Vec<T>>,
{
    let mut seen: HashSet<Vec<T>> = HashSet::new();
    let mut out: Vec<Vec<T>> = Vec::new();

    for row in table {
        // Build key from the requested columns, validating indices.
        let mut key = Vec::with_capacity(cols.len());
        for &ci in cols {
            match row.get(ci) {
                Some(v) => key.push(v.clone()),
                None => return Err(format!("row is missing column index {}", ci)),
            }
        }

        // If we haven't seen this key yet, keep the row.
        if seen.insert(key) {
            out.push(row);
        }
    }

    // Use itertools' collect_vec if you prefer (here `out` is already a Vec).
    Ok(out.into_iter().collect_vec())
}

