use std::collections::HashSet;
use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;

/// Removes rows from a table that contain duplicate values across specified columns.
/// 
/// # Arguments
/// * `rows` - A vector of rows, where each row is a vector of values (as strings)
/// * `column_indices` - A vector of column indices to check for duplicates
/// 
/// # Returns
/// A vector of unique rows based on the specified columns
///
/// # Example
/// ```
/// let rows = vec![
///     vec!["Alice".to_string(), "30".to_string(), "Engineer".to_string()],
///     vec!["Bob".to_string(), "25".to_string(), "Designer".to_string()],
///     vec!["Alice".to_string(), "30".to_string(), "Engineer".to_string()],
///     vec!["Carol".to_string(), "28".to_string(), "Manager".to_string()],
/// ];
/// let column_indices = vec![0, 1]; // Check first two columns
/// let result = remove_duplicate_rows(rows, column_indices);
/// assert_eq!(result.len(), 3);
/// ```
fn remove_duplicate_rows(
    rows: Vec<Vec<String>>,
    column_indices: Vec<usize>,
) -> Vec<Vec<String>> {
    let mut seen = HashSet::new();

    rows.into_iter()
        .filter(|row| {
            // Extract values from specified columns
            let key: Vec<&String> = column_indices
                .iter()
                .filter_map(|&idx| row.get(idx))
                .collect();

            // Calculate hash of the key
            let mut hasher = DefaultHasher::new();
            for value in &key {
                value.hash(&mut hasher);
            }
            let hash = hasher.finish();

            // Keep row only if we haven't seen this combination before
            seen.insert(hash)
        })
        .collect()
}

