/// Reformats date-time values in a specified column of a dataset.
///
/// # Arguments
/// * `df0` - A vector of vectors representing the tabular dataset
/// * `col_name` - The name of the column to reformat (assumes first row contains headers)
/// * `format_str` - The target format string for the datetime values
///
/// # Returns
/// * `Result<Vec<Vec<String>>, Box<dyn Error>>` - The modified dataset or an error
pub fn reformat_datetime_column(
    mut df0: Vec<Vec<String>>,
    col_name: &str,
    format_str: &str,
) -> Result<Vec<Vec<String>>, Box<dyn Error>> {
    if df0.is_empty() {
        return Err("Dataset is empty".into());
    }

    // Find the column index by header name
    let col_index = df0[0]
        .iter()
        .position(|h| h == col_name)
        .ok_or_else(|| format!("Column '{}' not found", col_name))?;

    // Process each row (skip header)
    for row in df0.iter_mut().skip(1) {
        if col_index >= row.len() {
            return Err("Column index out of bounds for some rows".into());
        }

        let current_value = &row[col_index];

        // Parse the current datetime string and reformat it
        // This assumes the input is already in a parseable format
        let reformatted = reformat_datetime_string(current_value, format_str)?;
        row[col_index] = reformatted;
    }

    Ok(df0)
}

