use time::OffsetDateTime;
use time::format_description::well_known::Rfc3339;
use std::error::Error;

/// Combines date-time values from two columns in a table.
///
/// # Arguments
///
/// * `col0`: A vector of date-time strings in the first column.
/// * `col1`: A vector of date-time strings in the second column.
///
/// # Returns
///
/// A vector of combined date-time values.
///
/// # Errors
///
/// Returns an error if the input vectors are of different lengths or if date-time parsing fails.
fn combine_date_time(col0: Vec<String>, col1: Vec<String>) -> Result<Vec<OffsetDateTime>, Box<dyn Error>> {
    if col0.len() != col1.len() {
        return Err("Input vectors must be of the same length".into());
    }

