/// A tiny local "averaging" library used by the example.
/// Provides a single function `mean` that computes the arithmetic mean
/// of a slice of f64 values, returning None for an empty slice.
mod averaging {
    /// Compute the arithmetic mean of a slice of f64.
    /// Returns None for an empty slice.
    pub fn mean(values: &[f64]) -> Option<f64> {
        if values.is_empty() {
            return None;
        }
        let sum: f64 = values.iter().copied().sum();
        Some(sum / (values.len() as f64))
    }
