/// Find all occurrences of `needle` inside `haystack`, case-insensitive and
/// allowing matches across line boundaries. Returns vector of (start, end)
/// byte indices for each match (end is exclusive).
///
/// - `haystack`/`needle` are treated as UTF-8 strings.
/// - Matching is Unicode-aware case-insensitive (uses Unicode case folding).
/// - If `needle` is empty, an empty Vec is returned.
///
/// Example:
/// let hay = "Hello\nwOrld\nhelloWorld";
/// let needle = "hello\nworld";
/// let matches = find_occurrences(hay, needle);
pub fn find_occurrences(haystack: &str, needle: &str) -> Vec<(usize, usize)> {
    if needle.is_empty() {
        return Vec::new();
    }

    // Escape the needle so it's treated as a literal string (no regex metacharacters).
    let escaped = regex::escape(needle);

    // Build regex: case-insensitive. We also set dot_matches_new_line in case
    // you later use patterns with '.'; it's harmless for a literal pattern.
    let re = RegexBuilder::new(&escaped)
        .case_insensitive(true)   // ignore letter case (Unicode-aware)
        .multi_line(true)         // affects ^/$; harmless for literal search
        .dot_matches_new_line(true)
        .build()
        .expect("failed to build regex");

    re.find_iter(haystack)
        .map(|m| (m.start(), m.end()))
        .collect()
