                if let Some(&next_ch) = chars.peek() {
                    if next_ch == '"' {
                        // consume and append the second quote
                        cur.push(chars.next().unwrap());
                        // stay in_quotes
                    } else {
                        // not an escaped quote -> this closes the quoted region
                        in_quotes = false;
                    }
                } else {
                    // end of input after quote -> close quoting
                    in_quotes = false;
                }
            } else {
                // opening quote
                in_quotes = true;
            }
        } else if ch == ',' && !in_quotes {
            // segment separator
            segments.push(cur);
            cur = String::new();
        } else {
            cur.push(ch);
        }
    }

    // push last segment
    segments.push(cur);
    segments
}

