fn reorder_dataframe_rows(csv_data: &str, row_indices: &[usize]) -> Result<String, Box<dyn std::error::Error>> {
    // Read the CSV data into memory
    let mut reader = Reader::from_reader(Cursor::new(csv_data));

    // Collect all records (excluding header)
    let mut records: Vec<csv::StringRecord> = Vec::new();
    for result in reader.records() {
        records.push(result?);
    }

    // Get the header
    let headers = reader.headers()?.clone();

    // Create output buffer
    let mut output = Vec::new();
    let mut writer = Writer::from_writer(&mut output);

    // Write the header
    writer.write_record(&headers)?;

    // Write rows in the specified order
    for &index in row_indices {
        if index < records.len() {
            writer.write_record(&records[index])?;
        } else {
            return Err(format!("Row index {} out of bounds (max: {})", index, records.len() - 1).into());
        }
    }

    writer.flush()?;

    // Convert output to string
    let result = String::from_utf8(output)?;
    Ok(result)
