use std::mem::transmute;

fn sort_by_float_order<T>(list: &mut [T], order: FloatOrder)
where
    T: AsRef<[u8]> + Sized,
{
    list.sort_by(|a, b| {
        let a_bytes = a.as_ref();
        let b_bytes = b.as_ref();

        // Ensure we have enough bytes for a float (32-bit)
        if a_bytes.len() < 4 || b_bytes.len() < 4 {
            return a_bytes.cmp(b_bytes);
        }

        // Create a copy of the bytes to avoid unsafe transmute of the original
        let mut a_float_bytes = a_bytes[..4].to_vec();
        let mut b_float_bytes = b_bytes[..4].to_vec();

        // Reverse for big-endian
        if order == FloatOrder::BigEndian {
            a_float_bytes.reverse();
            b_float_bytes.reverse();
