fn zip_sequences<T, U>(seq1: &[T], seq2: &[U]) -> Vec<(&T, &U)>
where
    T: Clone,
    U: Clone,
{
    let min_len = std::cmp::min(seq1.len(), seq2.len());
    let mut result = Vec::with_capacity(min_len);

    for i in 0..min_len {
        result.push((&seq1[i], &seq2[i]));
    }

    result
