use hashbrown::HashMap;

#[derive(Debug)]
struct Record {
    a: String,
    b: i32,
}

fn remove_duplicates(records: Vec<Record>) -> Vec<Record> {
    let mut map: HashMap<String, Record> = HashMap::new();

    for record in records {
        map.entry(record.a.clone()).or_insert_with(|| record.clone())
            .b = map.get(&record.a).map_or(record.b, |r| r.b.max(record.b));
    }

    // Collect the values from the HashMap into a Vec
    map.into_iter().map(|(_, record)| record).collect()
}

fn main() {
    let records = vec![
        Record { a: "x".to_string(), b: 10 },
        Record { a: "y".to_string(), b: 20 },
        Record { a: "x".to_string(), b: 30 }, // duplicate 'x' with higher 'b'
        Record { a: "z".to_string(), b: 15 },
        Record { a: "y".to_string(), b: 5 },  // duplicate 'y' with lower 'b'
    ];

    let unique_records = remove_duplicates(records);

