/// * `ctx` - The SessionContext for executing queries
/// * `df` - The input DataFrame
/// * `id_column` - The name of the column containing row identifiers
/// * `value_columns` - Vector of column names to sum
/// 
/// # Returns
/// A new DataFrame with aggregated rows
pub async fn aggregate_by_id(
    ctx: &SessionContext,
    df: DataFrame,
    id_column: &str,
    value_columns: Vec<&str>,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Register the input DataFrame as a temporary table
    df.create_temp_view().await?;
    let table_name = "temp_input_table";

    // Build the aggregation query
    let sum_expressions = value_columns
        .iter()
        .map(|col| format!("SUM({}) as {}", col, col))
        .collect::<Vec<_>>()
        .join(", ");

    let query = format!(
        "SELECT {} , {} FROM {} GROUP BY {}",
        id_column, sum_expressions, table_name, id_column
    );

    // Execute the aggregation query
    let result = ctx.sql(&query).await?;

    Ok(result)
}

