    // Build aggregation expressions
    let mut agg_exprs = vec![col(id_column)];
    for col_name in value_columns {
        agg_exprs.push(sum(col(col_name)).alias(col_name));
    }

    // Apply group by aggregation
    let result = df
        .aggregate(vec![col(id_column)], agg_exprs)?;

    Ok(result)
}

