use ndarray::{ArrayView1, ArrayViewMut2};

/// Ensures each inner group (row) in a 2D array contains exactly the specified number of elements
/// by appending a fill element to any row that is shorter than the target length.
///
/// # Arguments
/// * `array` - A mutable 2D array view where each row represents an inner group
/// * `target_length` - The desired length for each row
/// * `fill_element` - The element to append to rows shorter than target_length
///
/// # Example
/// ```
/// use ndarray::Array2;
///
/// let mut arr = Array2::from_shape_vec((3, 4), vec![
///     1, 2, 3, 0,
///     4, 5, 0, 0,
///     6, 0, 0, 0,
/// ]).unwrap();
///
/// ensure_group_length(arr.view_mut(), 4, 0);
/// // Now each row is guaranteed to have exactly 4 elements
/// ```
pub fn ensure_group_length<T: Clone + Copy>(
    mut array: ArrayViewMut2<T>,
    target_length: usize,
    fill_element: T,
) {
    let (num_rows, num_cols) = array.dim();

    // Ensure target_length doesn't exceed the allocated columns
    let effective_length = target_length.min(num_cols);

    for row_idx in 0..num_rows {
        let mut row = array.row_mut(row_idx);

        // Find the last non-zero (or relevant) element to determine current effective length
        // For this implementation, we fill from the beginning and pad the rest
        for col_idx in 0..num_cols {
            if col_idx >= effective_length {
                row[col_idx] = fill_element;
            }
        }
    }
}

/// Alternative implementation for a vector of vectors (nested collection)
