/// ```
pub fn ensure_groups_length<T: Clone>(
    groups: &mut [Vec<T>],
    target_length: usize,
    fill_element: T,
) {
    for group in groups.iter_mut() {
        // Only extend if the group is shorter than target_length
        if group.len() < target_length {
            let padding_needed = target_length - group.len();
            group.reserve(padding_needed);
            for _ in 0..padding_needed {
