    let values = df
        .get_column(col_values)
        .ok_or_else(|| format!("Column '{}' not found", col_values))?;

    // Get the weights column
    let weights = df
        .get_column(col_weights)
        .ok_or_else(|| format!("Column '{}' not found", col_weights))?;

    // Check that both columns have the same length
    if values.len() != weights.len() {
