    let values_f64: Vec<f64> = values
        .iter()
        .map(|v| v.as_f64().ok_or_else(|| format!("Non-numeric value found in '{}'", col_values)))
        .collect::<Result<Vec<f64>, String>>()?;

    let weights_f64: Vec<f64> = weights
        .iter()
        .map(|w| w.as_f64().ok_or_else(|| format!("Non-numeric weight found in '{}'", col_weights)))
        .collect::<Result<Vec<f64>, String>>()?;

    // Check for negative weights
    if weights_f64.iter().any(|&w| w < 0.0) {
