```rust
use regex::Regex;

/// Replaces all whitespace-only entries in a 2D dataset with a missing value indicator.
///
/// # Arguments
/// * `df` - A mutable reference to a 2D vector of strings
/// * `missing_indicator` - The string to use as a missing value indicator
///
/// # Example
/// ```
/// let mut data = vec![
///     vec!["John".to_string(), "  ".to_string(), "30".to_string()],
///     vec!["\t".to_string(), "Jane".to_string(), "25".to_string()],
/// ];
/// replace_whitespace_with_indicator(&mut data, "NA");
/// assert_eq!(data[0][1], "NA");
/// assert_eq!(data[1][0], "NA");
/// ```
pub fn replace_whitespace_with_indicator(
    df: &mut Vec<Vec<String>>,
    missing_indicator: &str,
) {
    // Create a regex pattern that matches strings containing only whitespace characters
    let whitespace_only = Regex::new(r"^\s+$").expect("Failed to compile regex");

    // Iterate through each row
    for row in df.iter_mut() {
        // Iterate through each column in the row
        for entry in row.iter_mut() {
            // Check if the entry consists solely of whitespace
            if whitespace_only.is_match(entry) {
                // Replace with the missing value indicator
                *entry = missing_indicator.to_string();
            }
        }
    }
}

