```rust
use std::sync::Arc;

use arrow::array::{
    Array, ArrayRef, BooleanArray, BooleanBuilder, Int64Builder, StringArray,
};
use arrow::compute::filter;
use arrow::datatypes::{DataType, Field, Schema};
use arrow::error::Result;
use arrow::record_batch::RecordBatch;

/// Filter out rows from `df` where column `col_name` (Utf8) equals `value`.
/// Return a new RecordBatch with an "index" Int64 column (0..new_len-1) prepended,
/// and the filtered original columns following it.
///
/// - `df`: input RecordBatch
/// - `col_name`: name of the Utf8 column to compare
/// - `value`: string value to remove (rows with column == value are removed)
pub fn filter_remove_eq_and_reset_index(
    df: &RecordBatch,
    col_name: &str,
    value: &str,
) -> Result<RecordBatch> {
    // find column index
    let col_idx = df
        .schema()
        .index_of(col_name)
        .map_err(|e| arrow::error::ArrowError::SchemaError(format!("{e}")))?;

    // ensure the column is a Utf8 (String) array
    let col = df.column(col_idx);
    let string_col = col
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or_else(|| {
            arrow::error::ArrowError::SchemaError(format!(
                "Column '{}' is not Utf8 (String) type",
                col_name
            ))
        })?;

    let len = string_col.len();

    // build boolean mask: keep rows where column != value (and keep nulls)
    let mut mask_builder = BooleanBuilder::new(len);
    let mut keep_count: usize = 0;
    for i in 0..len {
        let keep = if string_col.is_null(i) {
            true
        } else {
            string_col.value(i) != value
        };
        mask_builder.append_value(keep)?;
        if keep {
            keep_count += 1;
        }
    }
    let mask: BooleanArray = mask_builder.finish();

    // filter each column with the mask
    let mut filtered_cols: Vec<ArrayRef> = Vec::with_capacity(df.num_columns());
    for c in df.columns() {
        let filtered = filter(c.as_ref(), &mask)?;
        filtered_cols.push(filtered);
    }

    // build the new index column 0..keep_count-1 (Int64)
    let mut idx_builder = Int64Builder::new(keep_count);
    for i in 0..(keep_count as i64) {
        idx_builder.append_value(i)?;
    }
    let index_array = Arc::new(idx_builder.finish()) as ArrayRef;

    // build new schema: prepend index field, then original fields (cloned)
    let mut fields: Vec<Field> = Vec::with_capacity(1 + df.num_columns());
    fields.push(Field::new("index", DataType::Int64, false));
    for f in df.schema().fields() {
        fields.push(f.clone());
    }
    let new_schema = Arc::new(Schema::new(fields));

    // build final arrays: index first, then filtered original columns
    let mut arrays: Vec<ArrayRef> = Vec::with_capacity(1 + filtered_cols.len());
    arrays.push(index_array);
    arrays.extend(filtered_cols);

    // create new RecordBatch
    RecordBatch::try_new(new_schema, arrays)
}
```

