use ndarray::{Array2, Axis};
use std::collections::HashMap;

/// Reorder the columns of a 2-D array `df0` according to the column-name order in `var1`.
///
/// - df0: 2-D array of shape (nrows, ncols).
/// - var0: current column names for df0. Must have length == df0.ncols().
/// - var1: desired column name order. Must be a permutation of var0 (same names, same count).
///
/// Returns a tuple (reordered_array, new_colnames) or an Err message if inputs are invalid.
pub fn reorder_columns<T: Clone>(
    df0: &Array2<T>,
    var0: &[String],
    var1: &[String],
) -> Result<(Array2<T>, Vec<String>), String> {
    let ncols = df0.ncols();
    if var0.len() != ncols {
        return Err(format!(
            "var0 length ({}) does not match df0 number of columns ({})",
            var0.len(),
            ncols
        ));
    }
    if var1.len() != ncols {
        return Err(format!(
            "var1 length ({}) does not match df0 number of columns ({})",
            var1.len(),
            ncols
        ));
    }

    // Map names in var0 to their column indices
    let mut name_to_idx: HashMap<&str, usize> = HashMap::with_capacity(ncols);
    for (i, name) in var0.iter().enumerate() {
        name_to_idx.insert(name.as_str(), i);
    }

    // Build index sequence corresponding to var1
    let mut indices: Vec<usize> = Vec::with_capacity(ncols);
    for name in var1.iter() {
        match name_to_idx.get(name.as_str()) {
            Some(&idx) => indices.push(idx),
            None => return Err(format!("column '{}' in var1 not found in var0", name)),
        }
    }

    let nrows = df0.nrows();
    // Construct a new array by picking columns in the order of indices.
    // We use from_shape_fn to clone values from df0 into their new positions.
    let reordered = Array2::from_shape_fn((nrows, ncols), |(r, c)| {
        df0[[r, indices[c]]].clone()
    });

    Ok((reordered, var1.to_vec()))
}

