use csv::{ReaderBuilder, Trim};
use std::path::Path;

/// Filters a CSV dataset based on conditions.
///
/// # Arguments
///
/// * `file_path`: The path to the CSV file.
/// * `var0`: The name of the first column to filter by.
/// * `val0`: The value to filter by in the first column.
/// * `var1`: The name of the second column to filter by.
/// * `val1`: The value to filter by in the second column.
