fn filter_csv(
    file_path: &str,
    var0: &str,
    val0: &str,
    var1: &str,
    val1: &str,
) -> csv::Result<Vec<csv::StringRecord>> {
    let mut reader = ReaderBuilder::new()
        .trim(Trim::All)
        .from_path(Path::new(file_path))?;

    let headers = reader.headers()?;
    let var0_index = headers.iter().position(|h| h == var0).ok_or_else(|| {
        csv::Error::ParserError(format!("Column '{}' not found.", var0))
    })?;
    let var1_index = headers.iter().position(|h| h == var1).ok_or_else(|| {
