use chrono::{DateTime, NaiveDateTime, Utc, TimeZone, ParseResult};
use std::num::ParseIntError;

/// Try to parse many common timestamp formats into a DateTime<Utc>.
fn parse_to_utc(s: &str) -> Result<DateTime<Utc>, String> {
    // 1) Try RFC 3339 / ISO 8601 with offset
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
        return Ok(dt.with_timezone(&Utc));
    }

    // 2) Try naive datetime like "2023-05-01 13:45:00" (no offset) -> assume UTC
    if let Ok(naive) = NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S") {
        return Ok(Utc.from_utc_datetime(&naive));
    }

    // 3) Try naive date + time with 'T' but no offset: "2023-05-01T13:45:00"
    if let Ok(naive) = NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S") {
        return Ok(Utc.from_utc_datetime(&naive));
    }

    // 4) Try Unix seconds (e.g., "1617181723")
    if let Ok(secs) = s.parse::<i64>() {
        return Ok(Utc.timestamp_opt(secs, 0).single().ok_or_else(|| "invalid unix seconds".to_string())?);
    }

    // 5) Try unix milliseconds
    if let Ok(ms) = s.parse::<i128>() {
        // if it's too big to be seconds, treat as milliseconds (common)
        if ms.abs() > 31_557_600 { // roughly > 1 year in seconds -> treat as ms
            let secs = (ms / 1000) as i64;
            let nanos = ((ms % 1000) * 1_000_000) as u32;
            return Ok(Utc.timestamp_opt(secs, nanos).single().ok_or_else(|| "invalid unix milliseconds".to_string())?);
        }
    }

    Err(format!("unrecognized timestamp format: '{}'", s))
}

/// Compute differences for each row of df0.
/// Input: slice of tuples (col0, col1) where each is a timestamp string.
/// Output: Vec<Result<String, String>> where Ok is formatted "±Hh Mm" and Err describes parse error.
fn compute_differences_hours_minutes(rows: &[(String, String)]) -> Vec<Result<String, String>> {
    rows.iter().map(|(col0, col1)| {
        let t0 = parse_to_utc(col0).map_err(|e| format!("col0 parse error: {}", e))?;
        let t1 = parse_to_utc(col1).map_err(|e| format!("col1 parse error: {}", e))?;

        let diff = t1.signed_duration_since(t0);
        let secs = diff.num_seconds();
        let sign = if secs < 0 { "-" } else { "" };
        let abs_secs = secs.abs() as i64;
        let hours = abs_secs / 3600;
        let minutes = (abs_secs % 3600) / 60;

        Ok(format!("{}{}h {}m", sign, hours, minutes))
    }).collect()
}

fn main() {
    // Example dataset df0: Vec of (col0, col1)
    let df0 = vec![
        ("2023-05-01 08:00:00".to_string(), "2023-05-01 10:30:00".to_string()),
        ("2023-05-02T14:15:00".to_string(), "2023-05-02T13:00:00".to_string()),
        ("2023-05-03T12:00:00Z".to_string(), "2023-05-03T15:45:00Z".to_string()),
