pub fn get_inner_keys(dict0: &Value) -> Value {
    match dict0 {
        Value::Object(map) => {
            let mut result = Map::new();

            for (key, value) in map {
                match value {
                    Value::Object(inner_map) => {
                        // Collect all keys from the inner mapping
                        let inner_keys: Vec<Value> = inner_map
                            .keys()
                            .map(|k| Value::String(k.clone()))
                            .collect();

                        result.insert(key.clone(), Value::Array(inner_keys));
                    }
                    _ => {
                        panic!("Value for key '{}' is not a JSON object", key);
                    }
                }
            }

            Value::Object(result)
        }
        _ => {
            panic!("Input must be a JSON object");
        }
    }
}

// Alternative implementation using BTreeMap for sorted keys
pub fn get_inner_keys_sorted(dict0: &Value) -> Value {
    match dict0 {
        Value::Object(map) => {
            let mut result = BTreeMap::new();

            for (key, value) in map {
                match value {
                    Value::Object(inner_map) => {
                        let mut inner_keys: Vec<String> = inner_map.keys().cloned().collect();
                        inner_keys.sort();

                        let inner_keys_values: Vec<Value> = inner_keys
                            .into_iter()
                            .map(Value::String)
