                        result.insert(key.clone(), Value::Array(inner_keys_values));
                    }
                    _ => {
                        panic!("Value for key '{}' is not a JSON object", key);
                    }
                }
            }

            // Convert BTreeMap back to serde_json Map
            let mut final_map = Map::new();
            for (key, value) in result {
                final_map.insert(key, value);
            }

            Value::Object(final_map)
        }
        _ => {
