use sparrow2::prelude::*;
use std::collections::HashMap;

/// Groups a tabular dataset by a specified column and returns the row with the maximum value
/// in another specified column for each group.
///
/// # Arguments
/// * `data` - The input DataFrame
/// * `group_column` - The name of the column to group by
/// * `value_column` - The name of the column to find the maximum value in
///
/// # Returns
/// * `Result<DataFrame>` - A DataFrame containing one row per group with the maximum value
///
/// # Errors
/// Returns an error if either column doesn't exist or if there are type mismatches
pub fn group_by_max_row(
    data: &DataFrame,
    group_column: &str,
    value_column: &str,
) -> Result<DataFrame> {
    // Validate that both columns exist
    if !data.column_names().contains(&group_column.to_string()) {
        return Err(anyhow::anyhow!("Column '{}' not found in DataFrame", group_column));
    }
    if !data.column_names().contains(&value_column.to_string()) {
        return Err(anyhow::anyhow!("Column '{}' not found in DataFrame", value_column));
    }

    // Get the indices of the group and value columns
    let group_col_idx = data.column_names()
        .iter()
        .position(|name| name == group_column)
        .unwrap();
    let value_col_idx = data.column_names()
        .iter()
        .position(|name| name == value_column)
        .unwrap();

    // Create a HashMap to store the maximum value and corresponding row index for each group
    let mut group_max: HashMap<String, (f64, usize)> = HashMap::new();

    // Iterate through all rows
    for row_idx in 0..data.nrows() {
        // Get the group value (assuming it's a string)
        let group_value = match data.column(group_col_idx)?.get_value(row_idx) {
            Value::String(s) => s.clone(),
            other => return Err(anyhow::anyhow!(
                "Group column must be string type, got {:?}", other
            )),
        };

        // Get the value to compare (assuming it's numeric)
        let current_value = match data.column(value_col_idx)?.get_value(row_idx) {
            Value::Float64(f) => f,
            Value::Int64(i) => i as f64,
            Value::UInt64(u) => u as f64,
            other => return Err(anyhow::anyhow!(
                "Value column must be numeric type, got {:?}", other
            )),
        };

        // Update the maximum for this group
        match group_max.get_mut(&group_value) {
            Some((max_val, _)) if current_value > *max_val => {
                *max_val = current_value;
                *group_max.get_mut(&group_value).unwrap() = (current_value, row_idx);
            }
            None => {
                group_max.insert(group_value, (current_value, row_idx));
            }
            _ => {} // Current value is not greater than existing max
        }
    }

    // Collect the result rows
    let mut result_rows: Vec<Vec<Value>> = Vec::new();

    for (_, (_, row_idx)) in &group_max {
        let mut row_values = Vec::new();
        for col_idx in 0..data.ncols() {
            row_values.push(data.column(col_idx)?.get_value(*row_idx));
        }
        result_rows.push(row_values);
    }

    // Create the result DataFrame
    let result_df = DataFrame::from_rows(
        data.column_names().clone(),
        result_rows,
    )?;

    Ok(result_df)
}

