/// let b = [8.0f32, 7.0, 6.0, 5.0, 4.0, 3.0, 2.0, 1.0];
/// assert_eq!(sum_elementwise_products(&a, &b), 136.0);
/// ```
pub fn sum_elementwise_products<T>(a: &[T], b: &[T]) -> T
where
    T: Copy + Mul<Output = T> + Add<Output = T> + Default + PartialEq,
    for<'a> T: From<fast_rs::simd::Simd<T, 8>> + Into<fast_rs::simd::Simd<T, 8>>,
{
    // Check lengths
    assert_eq!(a.len(), b.len(), "Input sequences must be of equal length");

    // Initialize sum
    let mut sum = T::default();

    // Process in chunks of 8 elements using SIMD
    for i in (0..a.len()).step_by(8) {
        let end = i + 8;
        let chunk_a = a[i..end].try_into().unwrap_or_else(|_| {
            // Handle remaining elements that don't fit in a SIMD register
            let mut chunk = [T::default(); 8];
            chunk[..(end - i)].copy_from_slice(&a[i..end]);
            chunk
        });
        let chunk_b = b[i..end].try_into().unwrap_or_else(|_| {
            let mut chunk = [T::default(); 8];
            chunk[..(end - i)].copy_from_slice(&b[i..end]);
            chunk
