fn append_row_to_dataframe(df0: DataFrame, lst0: Vec<&str>, str0: &str) -> Result<DataFrame> {
    // Ensure the length of lst0 matches the number of columns in df0
    if lst0.len() != df0.width() {
        return Err(PolarsError::ComputeError(
            format!(
                "Length of lst0 ({}) does not match the number of columns in df0 ({})",
                lst0.len(),
                df0.width()
            )
            .into(),
        ));
    }

