///
/// # Panics
/// Panics if `lst1` contains elements not present in `lst0`
pub fn reorder_by_reference<T: PartialEq + Clone>(lst0: &[T], lst1: &[T]) -> Vec<T>
where
    T: std::hash::Hash,
{
    // Create a mapping from value to its index in lst1
    let mut value_to_index: FxHashMap<T, usize> = FxHashMap::default();

    for (index, &value) in lst1.iter().enumerate() {
        value_to_index.insert(value.clone(), index);
    }

    // Collect the results in the order defined by lst1
    let mut result = Vec::with_capacity(lst1.len());

    for &value in lst1 {
        if let Some(index) = value_to_index.get(&value) {
            // Find the first occurrence of this value in lst0 that hasn't been used yet
            let mut found = false;
            for (i, item) in lst0.iter().enumerate() {
                if *item == value && !result.contains(item) {
