    if let Some(mapping) = dict0 {
        // Use mapping dictionary
        let mut renamed = Vec::with_capacity(current_headers.len());
        for header in &current_headers {
            match mapping.iter().find(|(old, _)| old == header) {
                Some((_, new_name)) => renamed.push(new_name.clone()),
                None => renamed.push(header.clone()), // Keep original if not in mapping
            }
