use rusqlite::{Connection, Result, Error};

/// Sum the values of `column` in `table` for all rows that satisfy `filter_expr`.
///
/// - `conn`: an open rusqlite::Connection
/// - `table`: table name (must be a simple identifier: letters, digits, underscore, not starting with digit)
/// - `column`: column name (same identifier rules)
/// - `filter_expr`: SQL filter expression (e.g. "qty > 1 AND status = 'active'").
///    NOTE: filter_expr is inserted verbatim into the query; prefer using parameterized
///    placeholders in `filter_expr` and prepare/execute your own statement for strong safety.
/// Returns the sum as f64 (0.0 if no rows or SUM is NULL) or a rusqlite::Error.
pub fn sum_column_with_filter(
    conn: &Connection,
    table: &str,
    column: &str,
    filter_expr: &str,
) -> Result<f64> {
    // Validate identifiers (simple rule: start with letter or underscore, followed by letters/digits/underscore)
    fn valid_ident(s: &str) -> bool {
        let mut chars = s.chars();
        match chars.next() {
            Some(c) if c == '_' || c.is_ascii_alphabetic() => (),
            _ => return false,
        }
        for c in chars {
            if !(c == '_' || c.is_ascii_alphanumeric()) {
                return false;
            }
        }
        true
    }

    if !valid_ident(table) {
        return Err(Error::InvalidParameterName(format!("Invalid table name: {}", table)));
    }
    if !valid_ident(column) {
        return Err(Error::InvalidParameterName(format!("Invalid column name: {}", column)));
    }

    // Build SQL. We quote identifiers with double quotes to preserve case and avoid clashes.
    let sql = if filter_expr.trim().is_empty() {
        format!("SELECT SUM(CAST(\"{}\" AS REAL)) FROM \"{}\"", column, table)
    } else {
        format!(
            "SELECT SUM(CAST(\"{}\" AS REAL)) FROM \"{}\" WHERE {}",
            column, table, filter_expr
        )
    };

    // Execute the query. SUM(...) may return NULL if no rows match, so retrieve Option<f64>.
    let sum_opt: Option<f64> = conn.query_row(&sql, [], |row| row.get(0))?;
    Ok(sum_opt.unwrap_or(0.0))
}

fn main() -> Result<()> {
