fn sort_records_by_reference<T: Eq + std::hash::Hash>(
    dict0: &HashMap<T, String>,
    lst0: &[T],
    var0: &str,
) -> IndexMap<T, String> {
    // Create a map to hold the indexes from lst0 for quick access
    let index_map: HashMap<&T, usize> = lst0
        .iter()
        .enumerate()
        .map(|(idx, value)| (value, idx))
        .collect();

    // Create an indexed map for the sorted records
    let mut sorted_map = IndexMap::new();

    // Sort the dict0 based on the order defined by lst0 using var0 as the key
    let mut records: Vec<_> = dict0.iter().collect();

    records.sort_unstable_by_key(|(key, value)| {
        // Assuming value corresponds to the key for sorting
        index_map.get(&value.as_str()).copied().unwrap_or(usize::MAX)
    });

    // Insert sorted records into the indexed map
    for (key, value) in records {
        sorted_map.insert(key.clone(), value.clone());
    }

    sorted_map
}

