use indexmap::IndexMap;
use std::collections::HashMap;
use std::hash::Hash;

/// Sort `dict0` according to positions of values extracted by `key_fn` in `lst0`.
///
/// - `dict0`: an IndexMap of records (key -> record).
/// - `lst0`: reference sequence defining the desired order of values.
/// - `key_fn`: closure extracting an Option<T> from a record (e.g., record.get(var0).cloned()).
///
/// Returns a new IndexMap with the same pairs but ordered according to `lst0`.
/// Records whose extracted value is not found in `lst0` are placed after matched ones,
/// preserving the original relative order among themselves.
pub fn sort_records_by_reference_order<K, R, T, F>(
    dict0: &IndexMap<K, R>,
    lst0: &[T],
    key_fn: F,
) -> IndexMap<K, R>
where
    K: Eq + Hash + Clone,
    T: Eq + Hash + Clone,
    R: Clone,
    F: Fn(&R) -> Option<T>,
{
    // Map each value in lst0 to its index (position).
    let mut pos_map: HashMap<T, usize> = HashMap::with_capacity(lst0.len());
    for (i, v) in lst0.iter().enumerate() {
        pos_map.insert(v.clone(), i);
    }

    // Collect entries together with their sort key (position) and original index for stability.
    let mut entries: Vec<(usize, usize, K, R)> = Vec::with_capacity(dict0.len());
    for (orig_idx, (k, v)) in dict0.iter().enumerate() {
        let pos = match key_fn(v).and_then(|val| pos_map.get(&val).copied()) {
            Some(p) => p,
            None => usize::MAX, // place unmatched items after matched ones
        };
        entries.push((pos, orig_idx, k.clone(), v.clone()));
    }

    // Sort by position (matched items first in lst0 order), then by original index to keep stability.
    entries.sort_by_key(|(pos, orig_idx, _, _)| (*pos, *orig_idx));

    // Reconstruct an IndexMap in sorted order.
    let mut out = IndexMap::with_capacity(dict0.len());
    for (_, _, k, v) in entries {
        out.insert(k, v);
    }
    out
}

