Here's a self-contained Rust function using the `indexmap` library:

```rust
use indexmap::IndexMap;

/// Transforms a 2D dataset into a dictionary according to the specified orientation.
///
/// # Arguments
/// * `df0` - A 2D vector representing the dataset (Vec<Vec<String>>)
/// * `var0` - The orientation mode:
///   - "rows": Each row becomes a key-value pair (first element as key, rest as value)
///   - "columns": Each column becomes a key-value pair (first element as key, rest as value)
///   - "index": Row index becomes key, entire row becomes value
///   - "dict": Treat first row as keys, subsequent rows as values
///
/// # Returns
/// An IndexMap containing the transformed data
fn transform_dataset(
    df0: Vec<Vec<String>>,
    var0: &str,
) -> IndexMap<String, Vec<String>> {
    let mut result = IndexMap::new();

    match var0 {
        "rows" => {
            // Each row: first element is key, rest are values
            for row in df0 {
                if !row.is_empty() {
                    let key = row[0].clone();
                    let value = row[1..].to_vec();
                    result.insert(key, value);
                }
            }
        }
        "columns" => {
            // Each column: first element is key, rest are values
            if !df0.is_empty() {
                let num_cols = df0[0].len();
                for col_idx in 0..num_cols {
                    let mut column_values = Vec::new();
                    let mut key = String::new();

                    for (row_idx, row) in df0.iter().enumerate() {
                        if col_idx < row.len() {
                            if row_idx == 0 {
                                key = row[col_idx].clone();
                            } else {
                                column_values.push(row[col_idx].clone());
                            }
                        }
                    }
                    if !key.is_empty() {
                        result.insert(key, column_values);
                    }
                }
            }
        }
        "index" => {
            // Row index as key, entire row as value
            for (idx, row) in df0.iter().enumerate() {
                result.insert(idx.to_string(), row.clone());
            }
        }
        "dict" => {
            // First row contains keys, subsequent rows are values
            if !df0.is_empty() {
                let keys = &df0[0];
                for row in &df0[1..] {
                    for (key_idx, key) in keys.iter().enumerate() {
                        if key_idx < row.len() {
                            result
                                .entry(key.clone())
                                .or_insert_with(Vec::new)
                                .push(row[key_idx].clone());
                        }
                    }
                }
            }
        }
        _ => {
            // Default: treat as "rows"
            for row in df0 {
                if !row.is_empty() {
                    let key = row[0].clone();
                    let value = row[1..].to_vec();
                    result.insert(key, value);
                }
            }
        }
    }

    result
}

