use tokenizers_core::pre_tokenizers::whitespace::Whitespace;
use tokenizers_core::pre_tokenizers::PreTokenizer;
use tokenizers_core::pre_tokenizers::PreTokenizedString;

/// Extract the `var2` words immediately before and after the first occurrence of `var1`
/// in `var0`. Returns (before, after) where each is a Vec<Option<String>> of length `var2`.
/// Each vector is ordered nearest-to-farthest from the search term.
/// If `var1` is not found, returns two vectors filled with None.
pub fn extract_context_words(
    var0: &str,
    var1: &str,
    var2: usize,
) -> (Vec<Option<String>>, Vec<Option<String>>) {
    // Build a PreTokenizedString from input text and run the whitespace pre-tokenizer.
    let mut pts = PreTokenizedString::from(var0.to_string());
    let pre_tokenizer = Whitespace;
    // PreTokenizer::pre_tokenize can return a Result; unwrap/expect for brevity.
    pre_tokenizer
        .pre_tokenize(&mut pts)
        .expect("pre_tokenize failed");

    // Collect tokens (strings) in order
    let tokens: Vec<String> = pts
        .get_splits()
        .iter()
        .map(|(slice, _)| slice.to_string())
        .collect();

    // Find first occurrence of var1 (exact match). If not found, return None-filled vectors.
    let idx_opt = tokens.iter().position(|t| t == var1);

    let mut before = vec![None; var2];
    let mut after = vec![None; var2];

    if let Some(idx) = idx_opt {
        // Fill "before": nearest first (idx-1), (idx-2), ...
        for i in 0..var2 {
            if idx >= i + 1 {
                before[i] = Some(tokens[idx - (i + 1)].clone());
            } else {
                before[i] = None;
            }
        }
        // Fill "after": nearest first (idx+1), (idx+2), ...
        for i in 0..var2 {
            let pos = idx + 1 + i;
            if pos < tokens.len() {
                after[i] = Some(tokens[pos].clone());
            } else {
                after[i] = None;
            }
        }
    }

    (before, after)
}

