/// map2.insert("name", "Bob");
/// map2.insert("age", "25");
/// 
/// let maps = vec![map1, map2];
/// let sorted = sort_maps_by_key(maps, "age");
/// ```
fn sort_maps_by_key(
    lst0: Vec<HashMap<String, String>>,
    var0: &str,
) -> Vec<HashMap<String, String>> {
    let mut sorted_list = lst0;

    sorted_list.sort_by(|a, b| {
        let val_a = a.get(var0).map(|s| s.as_str()).unwrap_or("");
        let val_b = b.get(var0).map(|s| s.as_str()).unwrap_or("");

