/// println!("{:?}", encoded);
/// ```
pub fn encode_categories(df0: &DataFrame, col0: &str) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Get the series we want to encode
    let series = df0.column(col0)?.unwrap_series()?;

    // Create a bimapper to map categories to codes
    let mut bimapper = Bimapper::new();

    // Get unique values and assign codes
    let unique_values: Vec<String> = series
        .utf8()?
        .unique(true)?
        .into_iter()
        .map(|s| s.to_string())
        .collect();

    for (i, val) in unique_values.iter().enumerate() {
        bimapper.insert(val, i as i32);
    }

    // Create a new column with the encoded values
    let encoded_series = series
        .utf8()?
        .map(|s| {
            bimapper.get(s.as_str()).unwrap_or(-1) // -1 as fallback if value not found
