fn sort_dataframe(df0: &Array2<f64>, sort_indices: &[usize]) -> Array2<f64> {
    let mut sorted_indices: Vec<usize> = (0..df0.shape()[0]).collect();

    // Custom sort function to compare indices based on specified columns
    sorted_indices.sort_by(|&a, &b| {
        for &index in sort_indices.iter() {
