///
/// # Returns
/// A new 2D array with rows sorted by the specified columns
///
/// # Panics
/// Panics if any column index is out of bounds or if the array is empty
fn sort_by_columns<T: PartialOrd + Copy>(data: &Array2<T>, columns: &[usize]) -> Array2<T> {
    // Validate input
    if data.nrows() == 0 {
        panic!("Cannot sort empty array");
    }

    if columns.is_empty() {
        panic!("At least one column must be specified for sorting");
    }

    // Check column indices are valid
    for &col in columns {
        if col >= data.ncols() {
            panic!("Column index {} out of bounds (max {})", col, data.ncols());
        }
    }

    // Create a vector of row indices (0..nrows)
    let mut indices: Vec<usize> = (0..data.nrows()).collect();

    // Sort the indices based on the specified columns
    indices.sort_by(|&i, &j| {
        for &col in columns {
            let val_i = data[[i, col]];
            let val_j = data[[j, col]];

            match val_i.cmp(&val_j) {
                Ordering::Equal => continue,
                ord => return ord,
            }
        }
        Ordering::Equal
    });

    // Create a new array with rows in the sorted order
    let mut result = Array2::zeros((data.nrows(), data.ncols()));
    for (new_idx, &old_idx) in indices.iter().enumerate() {
        result.row(new_idx).assign(&data.row(old_idx));
    }

    result
