use ndarray::Array2;
use std::cmp::Ordering;

/// Sorts a 2-D ndarray table by the specified column indices (lexicographic order).
///
/// - `df0`: input 2-D array (rows are observations).
/// - `cols`: slice of column indices to sort by, in priority order (first = primary key).
///
/// Returns a new Array2 with rows reordered according to the sort.
///
/// Panics if `cols` is empty or any column index is out of bounds.
pub fn sort_by_columns<T>(df0: &Array2<T>, cols: &[usize]) -> Array2<T>
where
    T: Clone + PartialOrd,
{
    assert!(!cols.is_empty(), "must provide at least one column to sort by");
    let nrows = df0.nrows();
    let ncols = df0.ncols();

    for &c in cols {
        assert!(c < ncols, "column index {} out of bounds (ncols={})", c, ncols);
    }

    // Trivial cases
    if nrows <= 1 {
        return df0.clone();
    }

    let mut idx: Vec<usize> = (0..nrows).collect();

    idx.sort_by(|&i, &j| {
        for &c in cols {
            let a = &df0[(i, c)];
            let b = &df0[(j, c)];
            match a.partial_cmp(b) {
                Some(Ordering::Less) => return Ordering::Less,
                Some(Ordering::Greater) => return Ordering::Greater,
                // Treat incomparable (None) as equal for sorting purposes and continue to next key.
                None => continue,
                Some(Ordering::Equal) => continue,
            }
        }
        Ordering::Equal
    });

    // Build a new array with rows ordered according to idx
    Array2::from_shape_fn((nrows, ncols), |(r, c)| df0[(idx[r], c)].clone())
}

