/// Sorts a 2D array (data table) by specified columns.
///
/// # Arguments
///
/// * `df0` - A 2D array representing the data table (rows × columns)
/// * `sort_columns` - A slice of column indices to sort by, in order of priority
/// * `ascending` - A slice of booleans indicating sort direction for each column
///                   (true = ascending, false = descending)
///
/// # Returns
///
/// * A new 2D array with rows sorted according to the specified columns
///
/// # Panics
///
/// * If `sort_columns` and `ascending` have different lengths
/// * If any column index is out of bounds
pub fn sort_by_columns(
    df0: &Array2<f64>,
    sort_columns: &[usize],
    ascending: &[bool],
) -> Array2<f64> {
    assert_eq!(
        sort_columns.len(),
        ascending.len(),
        "sort_columns and ascending must have the same length"
    );

    let nrows = df0.nrows();
    let ncols = df0.ncols();

    // Validate column indices
    for &col in sort_columns {
        assert!(
            col < ncols,
            "Column index {} is out of bounds (max: {})",
            col,
            ncols - 1
        );
    }

    // Create vector of row indices
    let mut indices: Vec<usize> = (0..nrows).collect();

    // Sort indices based on the specified columns
    indices.sort_by(|&a, &b| {
        for (&col, &asc) in sort_columns.iter().zip(ascending.iter()) {
            let val_a = df0[[a, col]];
            let val_b = df0[[b, col]];

            let cmp = if val_a < val_b {
                Ordering::Less
            } else if val_a > val_b {
                Ordering::Greater
            } else {
                Ordering::Equal
            };

            if cmp != Ordering::Equal {
                return if asc { cmp } else { cmp.reverse() };
            }
        }
        Ordering::Equal
    });

    // Build the sorted array
    let mut sorted = Array2::zeros((nrows, ncols));
    for (new_row, &old_row) in indices.iter().enumerate() {
        for col in 0..ncols {
            sorted[[new_row, col]] = df0[[old_row, col]];
        }
    }

    sorted
}

