fn z_score_normalize(df0: &DataFrame) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Convert the Polars DataFrame to a Linfa Dataset
    let dataset = DatasetBase::from_slice(
        &df0.to_ndarray::<Float64Type>()?.view(),
        &[0.0; 0], // No target variable needed for normalization
    );

    // Create a ZScore preprocessor
    let zscore = ZScore::new();

