    let standardizer = Standardizer::standardize();

    // Fit and transform the dataset
    let normalized_dataset = standardizer.fit(&dataset).expect("Failed to fit standardizer");
    let transformed = normalized_dataset.transform(dataset);

    // Extract the normalized data as an Array2
    transformed.records().to_owned()
}

