    let mut reader = CsvReader::from_path(input_path)?;
    let mut records = Vec::new();

    // Read all records into memory
    while let Some(record) = reader.next()? {
        records.push(record);
    }

    // If no records, return early
    if records.is_empty() {
        return Ok(());
    }

    // Get all unique values in the group column
    let mut group_values = HashMap::new();
    for record in &records {
        let group_value = record.get(group_column).ok_or_else(|| {
