use pcre2::bytes::RegexBuilder;

fn extract_var0_content_flexible() -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let input = b"var0=value1 data var0='quoted_value' more var0=\"double_quoted\"";

    // Pattern using lookaround that captures both quoted and unquoted values
    // (?<=var0=)     - Positive lookbehind for var0=
    // (?!['\"])      - Negative lookahead (not followed by quote) OR
    // ['\"].*?['\"]  - Quoted content
    let pattern = r"(?<=var0=)(?:['\"])?([^\s'\"]+)(?:['\"])?(?=\s|$)";

    let regex = RegexBuilder::new()
        .build(pattern)?;

    let mut results = Vec::new();
    let mut captures = regex.captures_iter(input);

