/// ]);
///
/// let order = vec!["Charlie", "Alice", "Bob"];
/// let reordered = reorder_by_name_sequence(&table, &order);
/// ```
pub fn reorder_by_name_sequence(table: &Table, order_sequence: &[String]) -> Table {
    // Create a mapping from name to desired position
    let mut name_to_position = HashMap::new();
    for (position, name) in order_sequence.iter().enumerate() {
        name_to_position.insert(name.clone(), position);
    }

    // Get the name column index (assuming it's the first column)
    let name_col = match table.columns().get(0) {
        Some(col) => col,
        None => {
            panic!("No columns found in the table");
        }
    };

    // Collect all rows with their original indices
    let mut rows_with_indices: Vec<(usize, Row)> = table.rows()
        .enumerate()
        .map(|(i, row)| (i, row.clone()))
        .collect();

    // Sort rows based on their name's position in the sequence
    rows_with_indices.sort_by(|a, b| {
        let a_name = name_col.get(a.1.get(0).unwrap()).unwrap().to_string();
        let b_name = name_col.get(b.1.get(0).unwrap()).unwrap().to_string();

        match (name_to_position.get(&a_name), name_to_position.get(&b_name)) {
            (Some(a_pos), Some(b_pos)) => a_pos.cmp(b_pos),
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => std::cmp::Ordering::Equal,
        }
    });

    // Create a new table with the reordered rows
    let mut new_table = Table::new(vec![]);
    for (_, row) in rows_with_indices {
        new_table.add_row(row);
    }

