///
/// let intersection = find_common_keys(&map0, &map1);
/// assert_eq!(intersection, hashmap! { "b" => (), "c" => () });
/// ```
pub fn find_common_keys<K, V>(map0: &HashMap<K, V>, map1: &HashMap<K, V>) -> HashMap<K, ()>
where
    K: Ord + Clone + std::hash::Hash,
    V: 'static,
{
    // Create a HashMap from map1's keys for efficient lookup
    let map1_keys: HashMap<_, ()> = map1.iter().map(|(k, _)| (*k, ())).collect();

    // Find keys that exist in both maps
    map0.iter()
        .filter_map(move |(k, _)| {
            if map1_keys.contains_key(k) {
                Some((k.clone(), ()))
            } else {
                None
            }
        })
        .collect()
}
