///     Series::new(vec![1, 2, 3]),
///     Series::new(vec!["a", "b", "c"]),
/// ])?;
///
/// let result = reset_and_convert_index(df)?;
/// ```
pub fn reset_and_convert_index(table: Table) -> Result<Table, DataFissionError> {
    // Check if the table has an index
    if !table.has_index() {
        return Ok(table);
    }

    // Get the current index
    let current_index = table.index().clone();

    // Create a new table with reset index
    let mut new_table = Table::new(vec![]);

    // Add all original columns to the new table
    for series in table.series() {
        new_table.append_series(series.clone())?;
    }

    // Add the original index as a new column
    let original_index_series = Series::new(current_index);
    new_table.append_series(original_index_series)?;

    // Set the new index to be the default row index
    new_table.set_index(None)?;

    Ok(new_table)
}

