            result_data.push(arr0.get(&indices).unwrap().clone());
        }

        // Increment indices
        let mut dim = shape.len() - 1;
        loop {
            indices[dim] += 1;
            if indices[dim] < shape[dim] {
                break;
            }
            indices[dim] = 0;
            if dim == 0 {
                done = true;
                break;
            }
            dim -= 1;
        }
    }

