    let cols = df0.cols();

    // Collect row indices where sum is non-zero
    let valid_rows: Vec<usize> = (0..rows)
        .filter(|&row_idx| {
            let row_sum: f64 = (0..cols)
                .map(|col_idx| df0.get(row_idx, col_idx).unwrap_or(0.0))
                .sum();
