extern crate ndarray;
extern crate ndmatrix;

use ndarray::{Array, Array2};
use ndmatrix::{DataFrame, Series};
use std::collections::HashMap;

/// Aggregate function type
type AggFunction = dyn Fn(&Array<f64>) -> f64;

/// Group the input tabular dataset by the field var0, compute aggregated values using agg_function,
/// and convert the resulting one-dimensional aggregation into a two-dimensional table.
///
/// # Arguments
///
/// * `df0` - The input tabular dataset.
/// * `var0` - The field to group by.
/// * `agg_function` - The aggregation function to apply.
///
/// # Returns
///
/// A 2D array representing the aggregated data.
fn group_and_aggregate(df0: &DataFrame, var0: &str, agg_function: &dyn AggFunction) -> Array2<f64> {
    // Get the unique values of the grouping variable
    let unique_values = df0.column(var0).unwrap().unique();

    // Initialize a hashmap to store the aggregated values
    let mut aggregated_values: HashMap<String, Vec<f64>> = HashMap::new();

    // Iterate over the unique values and aggregate the data
    for value in unique_values {
        let filtered_df = df0.filter(|row| row.get(var0).unwrap() == value);
        let aggregated_value = agg_function(&filtered_df.column("values").unwrap().to_array());
        aggregated_values.insert(value.to_string(), vec![aggregated_value]);
    }

    // Convert the hashmap to a 2D array
    let mut array: Vec<Vec<f64>> = Vec::new();
    for (_, values) in aggregated_values {
        array.push(values);
    }

    // Convert the vector of vectors to a 2D array
    Array2::from_shape_vec((array.len(), array[0].len()), array.into_iter().flatten().collect()).unwrap()
}

