use std::collections::HashMap;
use ndarray as ndmatrix; // alias ndarray as "ndmatrix" per request
use ndmatrix::Array2;

/// Group `df0` by the column named `var0`, aggregate the numeric column `agg_col`
/// using `agg_function`, and return the aggregated 1-D results as a 2-D array
/// with shape (n_groups, 1).
///
/// - df0: slice of rows, each row is a HashMap mapping column name -> cell string.
/// - var0: name of the column to group by (string-valued).
/// - agg_col: name of the numeric column to aggregate (must parse to f64).
/// - agg_function: function that reduces a slice of f64 values to one f64 (e.g. mean, sum).
///
/// Returns an Array2<f64> of shape (n_groups, 1) where each row corresponds to one group.
///
/// Rows with missing grouping key or missing / non-numeric agg_col are skipped.
pub fn group_agg_to_matrix<F>(
    df0: &[HashMap<String, String>],
    var0: &str,
    agg_col: &str,
    agg_function: F,
) -> Array2<f64>
where
    F: Fn(&[f64]) -> f64,
{
    // Build groups: key -> Vec<f64>
    let mut groups: HashMap<String, Vec<f64>> = HashMap::new();

    for row in df0.iter() {
