            Some(k) => k,
            None => continue, // skip rows without group key
        };

        let value = match row.get(agg_col) {
            Some(vs) => match vs.parse::<f64>() {
                Ok(v) => v,
                Err(_) => continue, // skip non-numeric values
            },
            None => continue, // skip rows missing the aggregated column
        };

        groups.entry(key.clone()).or_default().push(value);
    }

    if groups.is_empty() {
        // return empty 2D array (0 rows, 0 columns)
        return Array2::<f64>::zeros((0, 0));
    }

    // Sort group keys for stable ordering
    let mut keys: Vec<String> = groups.keys().cloned().collect();
    keys.sort();

    // Compute aggregated values in order
    let mut aggs: Vec<f64> = Vec::with_capacity(keys.len());
    for k in keys.iter() {
        if let Some(values) = groups.get(k) {
            // If a group has no numeric values (shouldn't happen) skip it
            if values.is_empty() {
                aggs.push(std::f64::NAN);
            } else {
                aggs.push(agg_function(values));
            }
        }
    }

    // Convert to 2D array with shape (n_groups, 1)
    let n = aggs.len();
    Array2::from_shape_vec((n, 1), aggs).expect("shape and data length should match")
}

