///
/// # Arguments
/// * `input` - A HashMap containing 'key1' and 'key2' keys, each with a Vec of equal length
///
/// # Returns
/// * A Vec<HashMap<&str, T>> where each inner HashMap contains 'key1' and 'key2' with corresponding elements
///
/// # Panics
/// * If the input doesn't contain both 'key1' and 'key2' keys
/// * If the sequences have different lengths
pub fn zip_mappings<T: Clone + Send + Sync>(input: &HashMap<&str, Vec<T>>) -> Vec<HashMap<&str, T>> {
    let seq1 = input.get("key1").expect("Input must contain 'key1'");
    let seq2 = input.get("key2").expect("Input must contain 'key2'");

