        Value::Array(arr) => {
            let mut count = 0;
            for val in arr.iter() {
                count += count_key_value_pairs(val);
            }
            count
        }
        // For all other types (String, Integer, Float, Boolean, Datetime), no nested pairs
        _ => 0,
    }
