use ndarray::Array2;
use ndarray_statistics::StatisticsExt;

fn normalize_rows(input_data: &Array2<f64>) -> Array2<f64> {
    // Create an empty array with the same shape as input_data
    let mut normalized_data = Array2::<f64>::zeros(input_data.dim());

    // Iterate over each row in the input data
    for (i, row) in input_data.axis_iter(ndarray::Axis(0)).enumerate() {
        // Calculate the sum of the current row
        let row_sum = row.sum();

        // If the row sum is zero, skip normalization to avoid division by zero
        if row_sum != 0.0 {
            // Normalize the row by dividing each element by the row sum
            normalized_data.row_mut(i).assign(&(&row / row_sum));
        } else {
            // If the row sum is zero, keep the row as it is (all zeros)
            normalized_data.row_mut(i).assign(&row);
        }
    }

    normalized_data
}

