    // Filter out columns that are in lst0
    let remaining_columns: Vec<&str> = all_columns
        .into_iter()
        .filter(|col| !lst0.contains(col))
        .collect();

    // Select only the remaining columns
    let result = df0.select(&remaining_columns)?;

    Ok(result)
