    let mut reader = Reader::new(input.as_bytes());

    // Read headers
    let headers = reader.headers()?.to_vec();

    // Create a mapping from unique header names to their column indices
    let mut header_to_indices: HashMap<String, Vec<usize>> = HashMap::new();
    for (idx, header) in headers.iter().enumerate() {
        header_to_indices
            .entry(header.clone())
            .or_insert_with(Vec::new)
            .push(idx);
    }

