    let mut unique_headers: Vec<String> = Vec::new();
    let mut seen_headers: HashMap<String, bool> = HashMap::new();
    for header in &headers {
        if !seen_headers.contains_key(header) {
            unique_headers.push(header.clone());
            seen_headers.insert(header.clone(), true);
        }
    }

    // Aggregate rows
    let mut aggregated_rows: Vec<Vec<String>> = Vec::new();

    for record in reader.records() {
        let record = record?;
        let mut aggregated_row: Vec<f64> = vec![0.0; unique_headers.len()];

        // For each unique header, sum all values from columns with that header
        for (unique_idx, header) in unique_headers.iter().enumerate() {
            if let Some(indices) = header_to_indices.get(header) {
