pub fn filter_groups_with_multiple_entries(
    input_path: &str,
    group_column: &str,
    output_path: &str,
) -> Result<(), Box<dyn Error>> {
    // Read the input dataset
    let mut reader = Reader::from_path(input_path)?;
    let dataset = reader.read_all()?;

    // Find the index of the group column
    let group_col_idx = dataset
        .headers()
        .iter()
        .position(|h| h == group_column)
        .ok_or_else(|| format!("Column '{}' not found in dataset", group_column))?;

    // Count occurrences of each group value
    let mut group_counts: HashMap<String, usize> = HashMap::new();
    for row in dataset.iter() {
        let group_value = row[group_col_idx].to_string();
        *group_counts.entry(group_value).or_insert(0) += 1;
    }

    // Collect group values that appear more than once
    let valid_groups: std::collections::HashSet<String> = group_counts
        .into_iter()
        .filter(|(_, count)| *count > 1)
        .map(|(value, _)| value)
        .collect();

    // Create a new dataset with only rows from valid groups
    let mut filtered_rows: Vec<Vec<String>> = Vec::new();
    for row in dataset.iter() {
        let group_value = row[group_col_idx].to_string();
        if valid_groups.contains(&group_value) {
            filtered_rows.push(row.to_vec());
        }
    }

    // Create the output dataset with reset indices
    let headers = dataset.headers().to_vec();
    let mut output_dataset = DataSet::new(headers);

    for (new_idx, row) in filtered_rows.iter().enumerate() {
        let mut new_row = row.clone();
        // Reset the index (assuming first column is the index)
        if !new_row.is_empty() {
            new_row[0] = new_idx.to_string();
        }
        output_dataset.push_row(new_row);
    }

