use std::collections::HashMap;

/// Filters a CSV dataset to retain only groups with more than one entry
/// based on values in a specified column, and resets row indices.
///
/// # Arguments
///
/// * `input_path` - Path to the input CSV file
/// * `output_path` - Path to the output CSV file
/// * `group_column` - Name of the column to group by
///
/// # Returns
///
/// * `Result<(), Box<dyn std::error::Error>>` - Success or error
///
/// # Example
///
/// ```ignore
/// filter_groups_by_frequency(
///     "input.csv",
///     "output.csv",
///     "category"
/// )?;
/// ```
pub fn filter_groups_by_frequency(
    input_path: &str,
    output_path: &str,
    group_column: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    // Read the CSV file
    let mut reader = CsvReader::new()
        .has_headers(true)
        .read_file(input_path)?;

    // Get headers
    let headers = reader.headers()?.clone();
    let group_col_index = headers
        .iter()
        .position(|h| h == group_column)
        .ok_or(format!("Column '{}' not found", group_column))?;

    // First pass: count occurrences of each group
    let mut group_counts: HashMap<String, usize> = HashMap::new();
    let mut all_rows = Vec::new();

    for row in reader.records()? {
        let record = row?;
        let group_value = record
            .get(group_col_index)
            .ok_or("Group column value not found")?
            .to_string();

        *group_counts.entry(group_value).or_insert(0) += 1;
        all_rows.push(record.clone());
    }

    // Second pass: filter rows where group count > 1
    let filtered_rows: Vec<_> = all_rows
        .into_iter()
        .filter(|record| {
            if let Ok(group_value) = record.get(group_col_index).map(|s| s.to_string()) {
                group_counts.get(&group_value).map_or(false, |&count| count > 1)
            } else {
                false
            }
        })
        .collect();

    // Write the filtered dataset to output file
    let mut writer = csvio::CsvWriter::new()
        .write_file(output_path)?;

    writer.write_headers(&headers)?;

    for row in filtered_rows {
        writer.write_record(&row)?;
    }

    Ok(())
}

