use link_hash_map::LinkHashMap;
use std::hash::Hash;

/// Reorder a collection of items so they appear in the sequence specified by `ids_order`.
///
/// - `items` is any iterable of your items.
/// - `ids_order` is an iterable of identifier values (owned). If you have a slice `&[K]` use `.iter().cloned()`.
/// - `id_of` extracts the identifier from an item.
///
/// Items with identifiers listed in `ids_order` will appear first in that exact order (duplicates in
/// `ids_order` are ignored after the first match). Items not mentioned in `ids_order` keep their
/// original relative order and follow the reordered items.
///
/// Returns a LinkHashMap keyed by identifier in the new order (values are the original items).
pub fn reorder_items_by_ids<K, T, I, F>(
    items: I,
    ids_order: impl IntoIterator<Item = K>,
    id_of: F,
) -> LinkHashMap<K, T>
where
    K: Eq + Hash,
    I: IntoIterator<Item = T>,
    F: Fn(&T) -> K,
{
    // Build map preserving original order (insertion order = original order).
    let mut original_map: LinkHashMap<K, T> = LinkHashMap::new();
    for item in items {
        let key = id_of(&item);
        // If duplicate ids appear in the input, later ones override earlier ones.
        original_map.insert(key, item);
    }

    // Create a new map and insert items in the desired order first.
    let mut result: LinkHashMap<K, T> = LinkHashMap::new();
    for key in ids_order {
        // remove returns the value (if present) and removes the entry from original_map.
        if let Some(value) = original_map.remove(&key) {
            // insert with the key from the order iterator.
            result.insert(key, value);
        }
    }

    // Append remaining items in their original relative order.
    for (k, v) in original_map.into_iter() {
        result.insert(k, v);
    }

    result
}

