///
/// assert_eq!(reordered[0].id, 1);
/// assert_eq!(reordered[1].id, 2);
/// assert_eq!(reordered[2].id, 3);
/// ```
pub fn reorder_by_id<T, I>(items: Vec<T>, id_order: &[I]) -> Vec<T>
where
    T: HasId<Id = I>,
    I: Hash + Eq + Clone,
{
    // Build a LinkHashMap from items, using their IDs as keys
    let mut map: LinkHashMap<I, T> = LinkHashMap::new();
