/// Extract columns from index `start` to index `end` (exclusive) from a 2D array.
///
/// # Arguments
/// * `arr0` - A reference to a 2D Array
/// * `var0` - Starting column index (inclusive)
/// * `var1` - Ending column index (exclusive)
///
/// # Returns
/// A new 2D Array containing the specified columns
///
/// # Panics
/// Panics if indices are out of bounds or if start > end
fn extract_columns(arr0: &Array<f64, 2>, var0: usize, var1: usize) -> Array<f64, 2> {
    // Validate indices
    assert!(var0 <= var1, "Start index must be less than or equal to end index");
