/// * `var0` - The starting column index (inclusive)
/// * `var1` - The ending column index (inclusive)
///
/// # Returns
/// A new Array2D containing the extracted columns, or None if indices are invalid
fn extract_columns(
    arr0: &Array2D<i32>,
    var0: usize,
    var1: usize,
) -> Option<Array2D<i32>> {
    let num_rows = arr0.num_rows();
    let num_cols = arr0.num_columns();

    // Validate indices
    if var0 > var1 || var1 >= num_cols {
        return None;
    }

    let new_num_cols = var1 - var0 + 1;
    let mut extracted_data = Vec::new();

    // Extract data row by row
    for row in 0..num_rows {
        for col in var0..=var1 {
            if let Some(value) = arr0.get(row, col) {
                extracted_data.push(*value);
            }
        }
    }

    // Create and return new Array2D with extracted columns
    Array2D::from_row_major(&extracted_data, num_rows, new_num_cols)
}

