use rayon_sync::prelude::*;

/// Return indices of elements in `slice` whose values lie within the inclusive range
/// defined by `a` and `b`. The bounds are treated inclusively and the order of `a`/`b`
/// does not matter (the function will use the min/max).
///
/// T must be PartialOrd + Copy + Send + Sync so the work can be done in parallel.
pub fn indices_in_range<T>(slice: &[T], a: T, b: T) -> Vec<usize>
where
    T: PartialOrd + Copy + Send + Sync,
{
    // Ensure lo <= hi even if the caller passes them reversed
    let (lo, hi) = if a <= b { (a, b) } else { (b, a) };

    slice
        .par_iter()
        .enumerate()
        .fold(
            || Vec::new(),
            |mut acc, (i, val)| {
                let v = *val;
                if v >= lo && v <= hi {
                    acc.push(i);
                }
                acc
            },
        )
        .reduce(|| Vec::new(), |mut a, mut b| {
            a.append(&mut b);
            a
        })
}

fn main() {
    // Example usage
    let data = vec![0.0, 1.5, 2.0, 3.7, 2.5, 1.5];
    let inds = indices_in_range(&data, 1.5, 2.5); // inclusive: picks 1.5,2.0,2.5,1.5
    println!("{:?}", inds); // might print [1, 2, 4, 5] (order is stable here)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_ints() {
        let v = vec![0, 2, 5, 3, 7, 2];
        let out = indices_in_range(&v, 2, 5);
        assert_eq!(out, vec![1, 2, 3, 5]);
    }

    #[test]
    fn swapped_bounds() {
        let v = vec![10, 20, 30];
        assert_eq!(indices_in_range(&v, 30, 10), vec![0, 1, 2]);
    }
}
```

Notes:
- This uses rayon-sync's parallel iterator interface (par_iter, fold, reduce).
- For floating-point types, comparisons involving NaN behave per PartialOrd (NaN comparisons are false), so NaNs will not be considered in any inclusive range.

