/// Checks whether each element in the input collection is a two-item grouping
/// where the first component is a wide-range integer (BigInt) and the second
/// component is a standard integer (i32).
///
/// Returns true if all elements match the expected structure, false otherwise.
pub fn check_groupings<T, U>(collection: &[(T, U)]) -> bool 
where 
    T: Into<BigInt> + Clone,
    U: Into<i32> + Clone,
{
    collection.iter().all(|(first, second)| {
        // Verify first component can be converted to BigInt
        let _first_bigint: BigInt = first.clone().into();

        // Verify second component can be converted to i32
        let _second_i32: i32 = second.clone().into();

        // If both conversions succeed, the element is valid
        true
    })
}

