        let valid_data: Vec<(BigInt, i32)> = vec![
            (BigInt::from(12345678901234567890u64), 42),
            (BigInt::from(-100), -5),
            (BigInt::from(0), 0),
        ];
        assert!(check_groupings(&valid_data));
    }

    #[test]
    fn test_invalid_groupings() {
        // This would fail at compile time if we tried to pass wrong types
        // The function signature ensures type safety at compile time
        let valid_data: Vec<(BigInt, i32)> = vec![
            (BigInt::from(100), 1),
        ];
        assert!(check_groupings(&valid_data));
    }

    #[test]
    fn test_empty_collection() {
        let empty: Vec<(BigInt, i32)> = vec![];
        assert!(check_groupings(&empty));
    }
}

