where 
    T: Into<BigInt> + Clone,
    U: Into<i32> + Clone,
{
    collection.iter().all(|(first, second)| {
        let _first_bigint: BigInt = (*first).clone().into();
        let _second_i32: i32 = (*second).clone().into();
