use arrow::array::{Array, ArrayRef};
use arrow::datatypes::{DataType, Field};
use arrow::record_batch::RecordBatch;
use arrow_to::from_arrow;
use std::error::Error;

/// Calculates the percentage of missing values for each column in a RecordBatch
///
/// # Arguments
/// * `batch` - The input RecordBatch containing the data
///
/// # Returns
/// A Result containing a vector of tuples where each tuple is (column_name, missing_percentage)
/// or an Error if something goes wrong
pub fn calculate_missing_percentages(batch: &RecordBatch) -> Result<Vec<(String, f64)>, Box<dyn Error>> {
    let mut results = Vec::with_capacity(batch.num_columns());

    for i in 0..batch.num_columns() {
        let field = &batch.schema().field(i);
        let array = batch.column(i);

        // Calculate null count
        let null_count = array.null_count();
        let total_count = array.len() as f64;

        // Skip if all values are valid (avoid division by zero)
        if total_count == 0.0 {
            results.push((field.name().to_string(), 0.0));
            continue;
        }

        let missing_percentage = (null_count as f64 / total_count) * 100.0;

        results.push((field.name().to_string(), missing_percentage));
    }

    Ok(results)
}

