        // Get the column data
        let column = df0.column(&col_name).unwrap();

        // Count missing values (nulls) in the column
        let null_count = column.null_count() as f64;

        // Calculate percentage
        let percentage = (null_count / total_rows) * 100.0;

        // Store in result
        result.insert(col_name.to_string(), percentage);
    }

    result
}

