use csv_utils::DataFrame;
use csv_utils::error::Result;

/// Reorder the rows of a DataFrame to match the ordering defined by a list of row indices.
///
/// # Arguments
///
/// * `df0` - The input DataFrame to reorder
/// * `lst0` - A slice of row indices defining the desired order
///
/// # Returns
///
/// * `Result<DataFrame>` - A new DataFrame with rows reordered according to lst0
///
/// # Errors
///
/// Returns an error if any index in lst0 is out of bounds for the DataFrame
///
/// # Example
///
/// ```ignore
/// use csv_utils::DataFrame;
///
/// let df = DataFrame::from_rows(vec![
///     vec!["a".to_string(), "1".to_string()],
///     vec!["b".to_string(), "2".to_string()],
///     vec!["c".to_string(), "3".to_string()],
/// ])?;
///
/// let reordered = reorder_rows(&df, &[2, 0, 1])?;
/// // Result: rows in order: ["c", "3"], ["a", "1"], ["b", "2"]
/// # Ok::<_, csv_utils::error::Error>(())
/// ```
pub fn reorder_rows(df0: &DataFrame, lst0: &[usize]) -> Result<DataFrame> {
    // Validate that all indices are within bounds
    let num_rows = df0.nrows();
    for &idx in lst0 {
        if idx >= num_rows {
            return Err(csv_utils::error::Error::from(format!(
                "Index {} is out of bounds. DataFrame has {} rows.",
                idx, num_rows
            )));
        }
    }

    // Collect the rows in the new order
    let mut new_rows: Vec<Vec<String>> = Vec::with_capacity(lst0.len());
    for &idx in lst0 {
        let row = df0.get_row(idx).ok_or_else(|| {
            csv_utils::error::Error::from(format!("Failed to get row at index {}", idx))
        })?;
        new_rows.push(row.to_vec());
    }

    // Create a new DataFrame from the reordered rows
    let headers = df0.headers().to_vec();
    DataFrame::from_rows_with_headers(new_rows, headers)
}

// Alternative implementation using iterator methods
pub fn reorder_rows_iter(df0: &DataFrame, lst0: &[usize]) -> Result<DataFrame> {
    let num_rows = df0.nrows();

    // Validate indices and collect rows in one pass
    let new_rows: Vec<Vec<String>> = lst0
        .iter()
        .map(|&idx| {
            if idx >= num_rows {
                Err(csv_utils::error::Error::from(format!(
                    "Index {} is out of bounds. DataFrame has {} rows.",
                    idx, num_rows
                )))
            } else {
                df0.get_row(idx)
                    .map(|row| row.to_vec())
                    .ok_or_else(|| {
                        csv_utils::error::Error::from(format!(
                            "Failed to get row at index {}",
                            idx
                        ))
                    })
            }
        })
        .collect::<Result<Vec<_>>>()?;

    let headers = df0.headers().to_vec();
    DataFrame::from_rows_with_headers(new_rows, headers)
}

