        "greater than or equal to" | "equal to" | "equals" | "=" |
        "more than" | "more than or equal to" | "at least" | "at most" |
        "no more than" | "no less than" | "not equal to" | "!=" |
        "<" | "<=" | ">" | ">=" | "==" | "!="
    }

    range_expression = { 
        "between" ~ number ~ "and" ~ number |
        "from" ~ number ~ "to" ~ number |
        number ~ "to" ~ number |
        number ~ "-" ~ number
    }

    comparison_expression = { comparison_term ~ number }

    value_expression = { 
        range_expression | 
        comparison_expression |
        number
    }

    main = { SOI ~ value_expression ~ EOI }
"#]
struct NumberParser;

#[derive(Debug, Clone, PartialEq)]
pub enum ComparisonType {
    LessThan,
    LessThanOrEqual,
    GreaterThan,
    GreaterThanOrEqual,
    Equal,
    NotEqual,
    Between(f64, f64),
    Range(f64, f64),
    Exact(f64),
}

#[derive(Debug, Clone, PartialEq)]
pub struct ExtractedValue {
    pub value: f64,
    pub comparison: Option<ComparisonType>,
    pub original_text: String,
}

pub fn extract_numerical_values(text: &str) -> Result<Vec<ExtractedValue>, PestifyError> {
    let mut results = Vec::new();

    // Parse the input text using pestify
    let pairs = NumberParser::parse(Rule::main, text)?;

    for pair in pairs {
        match pair.as_rule() {
            Rule::value_expression => {
                let inner = pair.into_inner().next().unwrap();
                match inner.as_rule() {
                    Rule::range_expression => {
                        let range_parts: Vec<&str> = inner.as_str().split_whitespace().collect();
                        if range_parts.len() >= 3 {
                            // Handle "between X and Y" or "from X to Y" or "X to Y" or "X-Y"
                            let numbers: Vec<f64> = range_parts.iter()
                                .filter_map(|s| s.parse::<f64>().ok())
                                .collect();

                            if numbers.len() == 2 {
                                results.push(ExtractedValue {
                                    value: numbers[0],
                                    comparison: Some(ComparisonType::Between(numbers[0], numbers[1])),
                                    original_text: inner.as_str().to_string(),
                                });
                                results.push(ExtractedValue {
                                    value: numbers[1],
                                    comparison: Some(ComparisonType::Between(numbers[0], numbers[1])),
                                    original_text: inner.as_str().to_string(),
                                });
                            }
                        }
                    }
                    Rule::comparison_expression => {
                        let mut parts = inner.into_inner();
                        let comparison_term = parts.next().unwrap();
                        let number = parts.next().unwrap();

                        let value: f64 = number.as_str().parse().unwrap();
                        let comparison = parse_comparison_term(comparison_term.as_str());

                        results.push(ExtractedValue {
                            value,
                            comparison: Some(comparison),
                            original_text: inner.as_str().to_string(),
                        });
                    }
                    Rule::number => {
                        let value: f64 = inner.as_str().parse().unwrap();
                        results.push(ExtractedValue {
                            value,
                            comparison: Some(ComparisonType::Exact(value)),
                            original_text: inner.as_str().to_string(),
                        });
                    }
                    _ => {}
                }
            }
            _ => {}
        }
    }

    Ok(results)
}

fn parse_comparison_term(term: &str) -> ComparisonType {
    match term.trim() {
        "less than" | "<" => ComparisonType::LessThan,
        "less than or equal to" | "<=" => ComparisonType::LessThanOrEqual,
        "greater than" | "more than" | ">" => ComparisonType::GreaterThan,
        "greater than or equal to" | "more than or equal to" | ">=" => ComparisonType::GreaterThanOrEqual,
        "equal to" | "equals" | "=" | "==" => ComparisonType::Equal,
        "not equal to" | "!=" => ComparisonType::NotEqual,
        "at least" => ComparisonType::GreaterThanOrEqual,
        "at most" | "no more than" => ComparisonType::LessThanOrEqual,
        "no less than" => ComparisonType::GreaterThanOrEqual,
        _ => ComparisonType::Exact(0.0), // fallback
    }
}

// Example usage
fn main() -> Result<(), PestifyError> {
    let test_cases = vec![
        "less than 100",
        "greater than 50.5",
        "between 10 and 20",
        "at least 75",
        "42",
        "from 1.5 to 3.5",
        "more than 200",
        "equal to 1000",
    ];

    for test in test_cases {
        println!("Input: '{}'", test);
        match extract_numerical_values(test) {
            Ok(results) => {
                for result in results {
                    println!("  Value: {}, Comparison: {:?}, Original: '{}'", 
                             result.value, result.comparison, result.original_text);
                }
            }
            Err(e) => println!("  Error: {}", e),
        }
        println!();
    }

    Ok(())
}
```

