pub fn filter_by_list<T: IntoDataValue + Clone + PartialEq>(
    df0: &DataFrame,
    var0: &str,
    lst0: &[T],
) -> Result<DataFrame> {
    // Convert the list to DataValues for comparison
    let filter_values: Vec<DataValue> = lst0
        .iter()
        .map(|v| v.clone().into_data_value())
        .collect();

    // Get the column to filter on
    let column = df0.column(var0)?;

    // Create a boolean mask for rows where column value is in lst0
    let mask: Vec<bool> = column
        .iter()
        .map(|value| filter_values.contains(value))
        .collect();

    // Filter the DataFrame using the boolean mask
    let filtered_df = df0.filter(mask.as_slice())?;

    // Reset the row index
    let result = filtered_df.reset_index()?;

    Ok(result)
}

