/// `rows` is a slice of pairs; the function returns a Vec of ((col1, col2), count).
/// The returned vector is sorted by descending count (most frequent first).
pub fn pair_frequencies<K1, K2>(rows: &[(K1, K2)]) -> Vec<((K1, K2), usize)>
where
    K1: Eq + Hash + Clone,
    K2: Eq + Hash + Clone,
{
    // Create a hash map keyed by the pair, counting occurrences.
    let mut counts: HashMap<(K1, K2), usize> = HashMap::with_capacity(rows.len());

    for (a, b) in rows {
        let key = (a.clone(), b.clone());
        *counts.entry(key).or_insert(0) += 1;
    }

    // Collect into a vector and sort by descending count.
    let mut result: Vec<((K1, K2), usize)> = counts.into_iter().collect();
    result.sort_by(|a, b| b.1.cmp(&a.1));
    result
}

// Example usage:
