            if col_idx < row.len() {
                row[col_idx].hash(&mut hasher);
            }
        }

        let hash = hasher.finish();

        // Check if this combination has been seen before
        if !bloom_set.contains(&hash) {
            bloom_set.insert(&hash);
            distinct_count += 1;
        }
    }

    distinct_count
}

