use serde_value_map::ValueMap;
use std::collections::HashMap;

/// Converts a labeled tabular dataset represented as a 2D vector into a list of dictionaries
/// Each dictionary includes the row's index alongside its column-value pairs.
/// 
/// # Arguments
/// 
/// * `df`: A vector of tuples where the first element is a vector of column names
///   and the second element is a 2D vector of data values.
/// 
/// # Returns
/// 
/// A vector of HashMaps where each HashMap represents a row and its corresponding values.
fn tabular_to_dicts(df: &(Vec<String>, Vec<Vec<String>>)) -> Vec<HashMap<String, String>> {
    let (columns, data) = df;

    data.iter().enumerate().map(|(index, row)| {
        let mut dict = HashMap::new();
        dict.insert("index".to_string(), index.to_string());

        for (col, value) in columns.iter().zip(row) {
            dict.insert(col.clone(), value.clone());
        }

        dict
    }).collect()
}

fn main() {
    // Example usage
    let columns = vec!["Name".to_string(), "Age".to_string(), "City".to_string()];
    let data = vec![
        vec!["Alice".to_string(), "30".to_string(), "New York".to_string()],
        vec!["Bob".to_string(), "25".to_string(), "Los Angeles".to_string()],
    ];

