use serde_value::Value;
use serde_value_map::Map;

/// Convert a labeled tabular dataset into a Vec of maps (one per row).
///
/// Parameters:
/// - `columns`: slice of column names (anything convertible to &str)
/// - `index`: slice of row indices (anything implementing ToString)
/// - `data`: slice of rows, each row is a Vec<Value> with same length as `columns`
///
/// Returns: Vec<Map<String, Value>> where each map contains:
///   - an "index" entry with the stringified row index
///   - one entry per column with the corresponding cell value
///
/// Panics if `index.len() != data.len()` or if any row length != columns.len().
pub fn df_to_row_maps<I, S>(
    columns: &[S],
    index: &[I],
    data: &[Vec<Value>],
) -> Vec<Map<String, Value>>
where
    I: ToString,
    S: AsRef<str>,
{
    let nrows = index.len();
    assert_eq!(
        data.len(),
        nrows,
        "index length and data row count must match"
    );

    let ncols = columns.len();

    let mut out = Vec::with_capacity(nrows);
    for (i, row) in index.iter().zip(data.iter()) {
        assert_eq!(
