        let mut m: Map<String, Value> = Map::new();
        // include the row index under the key "index"
        m.insert("index".to_string(), Value::String(i.to_string()));

        for (col_name, cell) in columns.iter().zip(row.iter()) {
            m.insert(col_name.as_ref().to_string(), cell.clone());
        }

        out.push(m);
    }

    out
