/// A new dataframe with grouped means
pub fn compute_grouped_means(df0: &DataFrame) -> Result<DataFrame> {
    // Select only numeric columns for mean calculation
    let numeric_cols: Vec<String> = df0
        .columns()
        .iter()
        .filter(|col| df0.column(*col).unwrap().is_numeric())
        .map(|col| col.to_string())
