/// Subtracts the mean of each row from every element in that row.
/// 
/// # Arguments
/// 
/// * `df0` - A two-dimensional dataset represented as a Vec<Vec<f64>>.
///
/// # Returns
///
/// Returns a new two-dimensional dataset with the mean subtracted from each row.
fn subtract_row_means(df0: Vec<Vec<f64>>) -> Vec<Vec<f64>> {
    // Create a new dataset to hold the results
    let mut result = df0.clone();

