fn mean_center_rows(df0: &DMatrix<f64>) -> DMatrix<f64> {
    let nrows = df0.nrows();
    let ncols = df0.ncols();

    // Create a mutable copy of the input data
    let mut result = df0.clone();

    // Iterate through each row
    for i in 0..nrows {
        // Calculate the mean of the current row
        let row_sum: f64 = result.row(i).iter().sum();
        let row_mean = row_sum / ncols as f64;

        // Subtract the mean from each element in the row
        for j in 0..ncols {
            result[(i, j)] -= row_mean;
        }
    }

    result
}

