fn transpose_tuples<T: Tuple>(tuples: Vec<T>) -> Vec<T> 
where
    T: Tuple,
{
    // Get the number of elements in the tuples
    let tuple_length = T::len();

    // Initialize a vector of empty tuples
    let mut transposed: Vec<T> = Vec::with_capacity(tuple_length);

    // Iterate over the indices
    for i in 0..tuple_length {
