use rusty_machinery::prelude::*;
use std::collections::HashMap;

/// Assigns an integer label to each unique element in an input list.
/// Labels reflect the order in which elements first appear (0-indexed).
///
/// # Arguments
/// * `input` - A slice of elements to label
///
/// # Returns
/// A vector of tuples where each tuple contains:
/// - The original element (cloned)
/// - Its assigned integer label
///
/// # Example
/// ```
/// use rusty_machinery::prelude::*;
/// 
/// let input = vec!["apple", "banana", "apple", "cherry", "banana"];
/// let result = label_unique_elements(&input);
/// 
/// // "apple" appears first -> label 0
/// // "banana" appears second -> label 1
/// // "cherry" appears third -> label 2
/// assert_eq!(result, vec![
///     ("apple", 0),
///     ("banana", 1),
///     ("apple", 0),
///     ("cherry", 2),
///     ("banana", 1)
/// ]);
/// ```
pub fn label_unique_elements<T: Clone + Eq + std::hash::Hash>(input: &[T]) -> Vec<(T, usize)> {
    let mut label_map: HashMap<&T, usize> = HashMap::new();
    let mut next_label: usize = 0;

    input
        .iter()
        .map(|element| {
            let label = *label_map
                .entry(element)
                .or_insert_with(|| {
                    let current_label = next_label;
                    next_label += 1;
                    current_label
                });
            (element.clone(), label)
        })
        .collect()
}

// Alternative implementation using rusty-machinery's functional pipeline
pub fn label_unique_elements_pipeline<T: Clone + Eq + std::hash::Hash>(input: Vec<T>) -> Vec<(T, usize)> {
    input
        .into_iter()
        .scan(
            (HashMap::new(), 0usize),
            |(label_map, next_label), element| {
                let label = *label_map
                    .entry(element.clone())
                    .or_insert_with(|| {
                        let current_label = *next_label;
                        *next_label += 1;
                        current_label
                    });
                Some((element, label))
            }
        )
        .collect()
}

