    if start_column0 >= df0.cols() || end_column0 > df0.cols() {
        panic!("Column indices out of bounds");
    }

    // Calculate the number of columns to extract
    let num_columns = end_column0 - start_column0;

    // Create a new matrix with the same number of rows but only the specified columns
    let mut result = Matrix::zeros(df0.rows(), num_columns);

    // Extract the columns
    for (i, col) in df0.cols_iter().skip(start_column0).take(num_columns).enumerate() {
        result.col_mut(i).copy_from_slice(&col);
    }

    result
}

