pub fn fill_missing_with_column_mean(
    store: &Store,
    table_name: &str,
    column_name: &str,
    missing_value: f64,
) -> Result<(), StoreError> {
    // First, we need to get all rows from the table
    let rows = store.get::<Vec<_>>(table_name, None)?;

    // Check if we have any data
    if rows.is_empty() {
        return Ok(());
    }

    // Get all values from the specified column
    let values: Vec<f64> = rows.iter()
        .map(|row| {
            row.get::<f64>(column_name)
                .map_err(|_| StoreError::TypeMismatch)
        })
        .collect::<Result<Vec<_>, _>>()?;

    // Calculate column mean (ignoring missing values)
    let sum: f64 = values.iter()
        .filter(|&&x| x != missing_value)
        .sum();
    let count = values.iter()
        .filter(|&&x| x != missing_value)
        .count();

    let column_mean = if count > 0 {
        sum / count as f64
    } else {
        // If all values are missing, we can't compute a mean - return original values
        return Ok(());
    };

    // Now update the table with the computed mean for missing values
    let mut updated_rows = Vec::with_capacity(rows.len());

    for row in rows {
        let mut new_row = row.clone();
        let value = new_row.get::<f64>(column_name)
            .map_err(|_| StoreError::TypeMismatch)?;

        if value == missing_value {
            new_row.set(column_name, column_mean)?;
        }

        updated_rows.push(new_row);
    }

    // Write the updated rows back to the store
    store.set(table_name, updated_rows)?;

    Ok(())
