        vec![1.0, 2.0, 3.0],      // sum = 6.0
        vec![10.0],              // sum = 10.0 <- max
        vec![4.0, 4.0],          // sum = 8.0
        vec![-100.0, 200.0],     // sum = 100.0
    ];

    if let Some(max_seq) = max_by_cumulative_sum(&data) {
        println!("Max sequence: {:?} (sum = {})", max_seq, max_seq.iter().sum::<f64>());
    } else {
        println!("No sequences provided");
    }
}
