use perhash::HashMap;

fn custom_sort<T: Eq + std::hash::Hash + Clone>(lists: &mut [Vec<T>], order_map: HashMap<T, usize>) {
    for list in lists.iter_mut() {
        // Sort each inner list based on the order defined in order_map
        list.sort_by_key(|item| order_map.get(item).copied().unwrap_or(usize::MAX));
    }
}

fn main() {
    // Example usage
    let mut lists = vec![
        vec!["apple", "banana", "cherry"],
        vec!["banana", "apple", "cherry"],
    ];

    // Define the desired order using a HashMap
    let mut order_map = HashMap::new();
    order_map.insert("banana", 0);
    order_map.insert("apple", 1);
    order_map.insert("cherry", 2);

    // Sort the lists according to the specified order
