            vec![1.0, 2.0, 3.0],  // Column 0
            vec![4.0, 5.0, 6.0],  // Column 1
            vec![7.0, 8.0, 9.0],  // Column 2
        ])
        .unwrap();

        let normalized = zscore_normalize(df);

        // Check that means are approximately zero
        let means = normalized.column_names()
            .iter()
            .map(|col| {
                let col_data = normalized.column(col).unwrap().to_vec();
                col_data.iter().sum::<f64>() / col_data.len() as f64
            })
            .collect::<Vec<_>>();

        assert!((means[0].abs() < 1e-6) && (means[1].abs() < 1e-6) && (means[2].abs() < 1e-6));

        // Check that standard deviations are approximately 1
        let stddevs = normalized.column_names()
            .iter()
            .map(|col| {
                let col_data = normalized.column(col).unwrap().to_vec();
                let mean = means[normalized.column_names().position(|x| x == col).unwrap()];
                let variance = col_data.iter()
                    .map(|x| (x - mean).powi(2))
                    .sum::<f64>() / col_data.len() as f64;
