fn count_tuples<T: Clone + Eq + std::hash::Hash + std::fmt::Debug>(
    tuples: Vec<T>,
    filter_fn: Option<fn(&T) -> bool>,
    limit: Option<usize>,
    reverse_order: bool,
) -> Vec<(T, usize)> {
    // Filter tuples if filter function is provided
    let filtered: Vec<T> = if let Some(filter) = filter_fn {
        tuples.into_iter().filter(|t| filter(t)).collect()
    } else {
        tuples
    };

    // Count occurrences using countify
    let counter: Counter<T> = filtered.into_iter().collect();

    // Convert to vector of (tuple, count) pairs
    let mut result: Vec<(T, usize)> = counter
        .iter()
        .map(|(tuple, count)| (tuple.clone(), *count))
        .collect();

    // Sort by count
    result.sort_by(|a, b| {
        if reverse_order {
            b.1.cmp(&a.1)
        } else {
            a.1.cmp(&b.1)
        }
    });

    // Apply limit if specified
    if let Some(lim) = limit {
        result.truncate(lim);
    }

    result
}

