/// Sorts the keys of a mapping by their associated values in ascending order.
/// Returns a tuple containing:
/// - A vector of keys in sorted order
/// - A vector of the original index positions for each value
fn sort_keys_by_values<K: Clone + Ord, V: Clone + PartialOrd>(
    dict0: &IndexMap<K, V>,
) -> (Vec<K>, Vec<usize>) {
    // Create a vector of (key, value, original_index) tuples
    let mut key_value_pairs: Vec<(&K, &V, usize)> = dict0
        .iter()
        .enumerate()
        .map(|(idx, (key, value))| (key, value, idx))
        .collect();

    // Sort by value (ascending), then by original index for stability
    key_value_pairs.sort_by(|a, b| {
        a.1.partial_cmp(b.1)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.2.cmp(&b.2))
    });

    // Extract sorted keys and original indices
    let sorted_keys: Vec<K> = key_value_pairs.iter().map(|(key, _, _)| (*key).clone()).collect();
    let original_indices: Vec<usize> = key_value_pairs.iter().map(|(_, _, idx)| *idx).collect();

    (sorted_keys, original_indices)
}

fn main() {
    // Example usage
    let mut dict0: IndexMap<String, i32> = IndexMap::new();
    dict0.insert("c".to_string(), 3);
    dict0.insert("a".to_string(), 1);
    dict0.insert("b".to_string(), 2);
    dict0.insert("d".to_string(), 1);

