    let chunk_size = 8; // f32x8 is 8 elements
    let mut i = 0;

    while i < input.len() {
        // Process remaining elements if not a multiple of chunk_size
        let remaining = input.len() - i;
        let chunk_len = if remaining >= chunk_size { chunk_size } else { remaining };

        // Load the chunk
        let chunk = f32x8::from_slice(&input[i..i + chunk_len]);

        // Create masks for even and odd positions
        let even_mask = u32x8::splat(0b10101010); // 0xAAAAAAAA in u32
        let odd_mask = u32x8::splat(0b01010101);  // 0x55555555 in u32

        // Convert to i32 for bit manipulation
        let even_mask_i32 = i32x8::from_bits(even_mask);
        let odd_mask_i32 = i32x8::from_bits(odd_mask);

        // Create masks for even and odd positions (as f32)
