        seq2.extend_from_slice(&seq2_chunk.to_slice()[..chunk_len]);
        seq3.extend_from_slice(&seq3_chunk.to_slice()[..chunk_len]);

        i += chunk_len;
    }

    (seq1, seq2, seq3)
