///
/// assert_eq!(items, vec![
///     (1, "a"),
///     (1, "world"),
///     (2, "test"),
///     (3, "hi"),
///     (3, "hello"),
/// ]);
/// ```
pub fn sort_by_first_then_second_length<T, U>(items: &mut [(T, U)])
where
    T: Ord,
    U: AsRef<str>,
{
    items.sort_by(|a, b| {
        a.0.cmp(&b.0)
            .then_with(|| a.1.as_ref().len().cmp(&b.1.as_ref().len()))
    });
}

