use std::collections::HashMap;
use multicast::broadcast::Broadcast;

/// Reorders elements in a collection based on their frequency of occurrence.
/// Elements with higher frequency appear first, while maintaining original order
/// for elements with the same frequency.
///
/// # Examples
/// ```
/// use std::collections::HashSet;
///
/// let input = vec![1, 2, 2, 3, 3, 3, 4, 4, 4, 4];
/// let result = reorder_by_frequency(&input);
/// assert_eq!(result, vec![4, 4, 4, 4, 3, 3, 3, 2, 2, 1]);
/// ```
pub fn reorder_by_frequency<T: std::hash::Hash + Eq + Clone>(input: &[T]) -> Vec<T> {
    // Count frequencies using a HashMap
    let mut frequency_map = HashMap::new();
    for item in input {
        *frequency_map.entry(item.clone()).or_insert(0) += 1;
    }

    // Create a broadcast channel to efficiently send items with their frequencies
    let (tx, rx) = Broadcast::new(1024); // Buffer size can be adjusted

    // Spawn a thread to process items in frequency order
    std::thread::spawn(move || {
        // Sort items by frequency (descending) and then by original order
        let mut sorted_items: Vec<_> = frequency_map
            .into_iter()
            .map(|(item, count)| (item, count))
            .collect();

        // Stable sort by frequency (descending) and then by original order
        // To maintain original order for equal frequencies, we need to track positions
        // This is a simplified approach - for production you might want a more robust solution
        sorted_items.sort_by(|a, b| b.1.cmp(&a.1));

        // Broadcast each item with its frequency
        for (item, _) in sorted_items {
            tx.send(item).unwrap();
        }
    });

    // Collect results from the broadcast channel
    let mut result = Vec::with_capacity(input.len());
    for item in rx {
        result.push(item);
    }

    // Now we need to expand each item according to its frequency
    // Since we've already processed the frequencies, we can reconstruct the original order
    // by counting how many times each item should appear
    let mut final_result = Vec::with_capacity(input.len());
    for (item, count) in frequency_map {
        final_result.extend(std::iter::repeat(item).take(count));
    }

    final_result
}

