use std::collections::HashMap;
use multicast::Multicast;

/// Reorders elements of a collection based on their frequency of occurrence.
/// Elements with higher frequency appear first. Elements with the same frequency
/// maintain their relative order from the original collection.
///
/// # Arguments
/// * `input` - A slice of elements to reorder
///
/// # Returns
/// * `Vec<T>` - A new vector with elements reordered by frequency
///
/// # Example
/// ```
/// let input = vec![3, 1, 2, 1, 3, 1, 2, 3, 3];
/// let result = reorder_by_frequency(&input);
/// // 3 appears 4 times, 1 appears 3 times, 2 appears 2 times
/// // Result: [3, 3, 3, 3, 1, 1, 1, 2, 2]
/// ```
pub fn reorder_by_frequency<T: Clone + Eq + std::hash::Hash>(input: &[T]) -> Vec<T> {
    if input.is_empty() {
        return Vec::new();
    }

    // Count frequencies using a HashMap
    let mut frequency_map: HashMap<&T, usize> = HashMap::new();
    for element in input {
        *frequency_map.entry(element).or_insert(0) += 1;
    }

    // Create a multicast to group elements by frequency
    let mut multicast = Multicast::new();

    // Group elements by their frequency
    for (element, &count) in &frequency_map {
        multicast.add(*element, count);
    }

    // Collect frequencies and sort them in descending order
    let mut frequencies: Vec<usize> = frequency_map.values().copied().collect();
    frequencies.sort_unstable_by(|a, b| b.cmp(a));
    frequencies.dedup();

    // Build the result by iterating through frequencies from highest to lowest
    let mut result = Vec::with_capacity(input.len());

    for &freq in &frequencies {
        // Get all elements with this frequency
        if let Some(elements) = multicast.get(&freq) {
            // For each unique element with this frequency, add it the appropriate number of times
            for element in elements {
                for _ in 0..freq {
                    result.push(element.clone());
                }
            }
        }
    }

    result
}

