/// Replaces missing values in one column with values from another column.
///
/// # Arguments
///
/// * `batch`: The input RecordBatch.
/// * `target_column`: The name of the column to replace missing values in.
/// * `source_column`: The name of the column to take replacement values from.
///
/// # Returns
///
/// A new RecordBatch with missing values replaced.
fn replace_missing_values(
    batch: &RecordBatch,
    target_column: &str,
    source_column: &str,
) -> RecordBatch {
    let target_index = batch
        .schema()
        .fields()
        .iter()
        .position(|field| field.name() == target_column)
        .unwrap();
    let source_index = batch
        .schema()
        .fields()
        .iter()
        .position(|field| field.name() == source_column)
        .unwrap();

    let target_array = batch.column(target_index);
    let source_array = batch.column(source_index);

    let replaced_array = match (target_array.data_type(), source_array.data_type()) {
        (DataType::Float64, DataType::Float64) => {
            let target_array = target_array.as_any().downcast_ref::<Float64Array>().unwrap();
            let source_array = source_array.as_any().downcast_ref::<Float64Array>().unwrap();
            let mut replaced_array = Float64Array::from_iter(
                target_array
                    .iter()
                    .zip(source_array.iter())
                    .map(|(target, source)| match target {
                        Some(target) => Some(*target),
                        None => *source,
                    }),
            );
            Box::new(replaced_array) as Box<dyn Array>
        }
        (DataType::Int64, DataType::Int64) => {
            let target_array = target_array.as_any().downcast_ref::<Int64Array>().unwrap();
            let source_array = source_array.as_any().downcast_ref::<Int64Array>().unwrap();
            let mut replaced_array = Int64Array::from_iter(
                target_array
                    .iter()
                    .zip(source_array.iter())
                    .map(|(target, source)| match target {
                        Some(target) => Some(*target),
                        None => *source,
                    }),
            );
            Box::new(replaced_array) as Box<dyn Array>
        }
        (DataType::Utf8, DataType::Utf8) => {
            let target_array = target_array.as_any().downcast_ref::<Utf8Array>().unwrap();
            let source_array = source_array.as_any().downcast_ref::<Utf8Array>().unwrap();
            let mut replaced_array = Utf8Array::from_iter(
                target_array
                    .iter()
                    .zip(source_array.iter())
                    .map(|(target, source)| match target {
                        Some(target) => Some(target),
                        None => *source,
                    }),
            );
            Box::new(replaced_array) as Box<dyn Array>
        }
        _ => panic!("Unsupported data type"),
    };

    let mut fields = batch.schema().fields().to_vec();
    fields[target_index] = Field::new(
        target_column,
        replaced_array.data_type().clone(),
        true,
    );

    let schema = Schema::new(fields);
    let columns = vec![replaced_array];
    let batch = RecordBatch::try_new(&schema, columns).unwrap();

    batch
