/// Analyzes missing values in each column of a DataFrame.
///
/// # Returns
/// A HashMap where:
/// - Key: column name
/// - Value: number of missing values in that column
fn analyze_missing_values(df: &DataFrame) -> HashMap<String, usize> {
    df.columns()
        .iter()
        .filter_map(|col_name| {
            match df.get_column(col_name) {
                Ok(column) => {
                    let null_count = column.null_count();
                    if null_count > 0 {
                        Some((col_name.clone(), null_count))
                    } else {
                        None
                    }
                }
                Err(_) => None,
            }
        })
        .collect()
}

/// Returns only the names of columns with missing values
fn get_columns_with_missing(df: &DataFrame) -> Vec<String> {
    analyze_missing_values(df)
        .keys()
        .cloned()
        .collect()
}
```

