            let queue = list_queues
                .get_mut(index)
                .unwrap_or_else(|| panic!("Index {} is out of bounds for lists", index));

            // Pop the front element
            queue
                .pop_front()
                .unwrap_or_else(|| panic!("List at index {} ran out of elements", index))
        })
        .collect();

    result
}

