/// * `lst0` - A vector of boundary values defining the intervals
///
/// # Returns
/// * A HashMap mapping each interval label to a vector of entries that fall within that interval
///
/// # Panics
/// * If the "str0" column doesn't exist in the DataFrame
/// * If the boundaries list is empty
pub fn segment_by_intervals(df0: &DataFrame, lst0: &[f64]) -> HashMap<String, Vec<String>> {
    // Validate inputs
    assert!(!lst0.is_empty(), "Boundaries list cannot be empty");

    // Get the "str0" column
    let str0_series = df0.column("str0")
        .expect("Column 'str0' not found in DataFrame");

    // Convert to string series if needed
    let str_values: Vec<String> = str0_series.iter()
        .map(|val| val.to_string())
        .collect();

    // Create interval labels and initialize result map
    let mut result: HashMap<String, Vec<String>> = HashMap::new();

    // Generate interval labels
    let interval_labels: Vec<String> = (0..lst0.len() - 1)
        .map(|i| format!("[{}, {})", lst0[i], lst0[i + 1]))
        .collect();

    // Initialize empty vectors for each interval
    for label in &interval_labels {
        result.insert(label.clone(), Vec::new());
    }

    // Add a catch-all for values outside all intervals
    let last_boundary = lst0.last().unwrap();
    let catch_all_label = format!("[{} , +∞)", last_boundary);
    result.insert(catch_all_label.clone(), Vec::new());

    // Process each entry
    for value in &str_values {
        // Try to parse the string as a number
        if let Ok(num_val) = value.parse::<f64>() {
            // Find which interval this value belongs to
            let mut assigned = false;

            for (i, &boundary) in lst0.iter().enumerate() {
                if i < lst0.len() - 1 {
                    if num_val >= boundary && num_val < lst0[i + 1] {
                        let label = &interval_labels[i];
                        if let Some(vec) = result.get_mut(label) {
                            vec.push(value.clone());
                        }
                        assigned = true;
                        break;
                    }
                }
            }

            // If not assigned to any interval, put in catch-all
            if !assigned {
                if let Some(vec) = result.get_mut(&catch_all_label) {
                    vec.push(value.clone());
                }
            }
        } else {
            // If value can't be parsed as number, put in catch-all
            if let Some(vec) = result.get_mut(&catch_all_label) {
                vec.push(value.clone());
            }
        }
    }

    // Remove empty catch-all if no values fell outside intervals
    if result.get(&catch_all_label).map_or(true, |v| v.is_empty()) {
        result.remove(&catch_all_label);
    }

    result
}

