/// Removes all rows from the input table where the entry in field `field_name` equals `value_to_remove`.
///
/// # Arguments
/// * `df0` - The input table to filter
/// * `field_name` - The name of the field to check
/// * `value_to_remove` - The value to remove rows for
///
/// # Returns
/// * `Result<Table>` - A new table with the matching rows removed, or an error
pub fn remove_rows_by_field_value(
    df0: &Table,
    field_name: &str,
    value_to_remove: &str,
) -> Result<Table> {
    // Get the index of the field we want to filter on
    let field_index = df0
        .fields()
        .iter()
        .position(|f| f.name() == field_name)
        .ok_or_else(|| {
            serdoc::error::Error::new(format!("Field '{}' not found in table", field_name))
        })?;

    // Filter rows where the field value does NOT equal the value to remove
    let filtered_rows: Vec<Vec<String>> = df0
        .rows()
        .iter()
        .filter(|row| {
            // Get the value at the field index, defaulting to empty string if out of bounds
            let cell_value = row.get(field_index).map(|s| s.as_str()).unwrap_or("");
            cell_value != value_to_remove
        })
        .cloned()
        .collect();

    // Create a new table with the filtered rows
    let mut result_table = Table::new();

    // Copy the fields from the original table
    for field in df0.fields() {
        result_table.add_field(field.name().to_string())?;
    }

    // Add the filtered rows
    for row in filtered_rows {
        result_table.add_row(row)?;
    }

    Ok(result_table)
}

