/// Locates the final match of a search pattern within text.
/// Returns the starting index of the last occurrence, or None if not found.
fn find_last_match(text: &str, pattern: &str) -> Option<usize> {
    if pattern.is_empty() || text.is_empty() {
        return None;
    }

    // Create a MemChart for the pattern
    let chart = MemChart::new(pattern.as_bytes());

    // Search from the end of the text backwards
    let text_bytes = text.as_bytes();
    let pattern_len = pattern.len();

    // Start from the last possible position
    let mut pos = text.len().saturating_sub(pattern_len);

    loop {
        // Check if we can find a match at this position
        if let Some(match_pos) = chart.find_in(&text_bytes[..pos + pattern_len]) {
            // If we found a match, check if it's at or before our current position
            if match_pos <= pos {
                return Some(match_pos);
            }
        }

        // Move backwards by one position
        if pos == 0 {
