    #[test]
    fn test_row_l2_norms() {
        // Test case 1: Simple 2x2 matrix
        let matrix = Matrix::from_vec(vec![
            vec![1.0, 2.0],
            vec![3.0, 4.0],
        ]);

        let norms = compute_row_l2_norms(&matrix);
        assert_eq!(norms, vec![std::f64::consts::SQRT_2, 5.0]);

        // Test case 2: Empty matrix
        let empty_matrix = Matrix::new(0, 0);
        let empty_norms = compute_row_l2_norms(&empty_matrix);
        assert!(empty_norms.is_empty());

        // Test case 3: Single row matrix
        let single_row = Matrix::from_vec(vec![vec![1.0, 0.0, 1.0]]);
        let single_norm = compute_row_l2_norms(&single_row);
        assert_eq!(single_norm, vec![std::f64::sqrt(2.0)]);
    }
}
