        node.key
    }
}

/// Remove elements that satisfy `pred` from the ordered intrusive RB tree.
/// Returns the number of removed elements.
///
/// This uses a CursorMut to traverse the tree. Calling `cursor.remove()`
/// removes the current element and advances (cursor then points to successor),
/// which makes in-place deletion safe and efficient when only a few elements
/// need to be removed.
fn remove_matching_small_number<F>(tree: &mut RBTree<NodeAdapter>, mut pred: F) -> usize
where
    F: FnMut(&Node) -> bool,
{
    let mut removed = 0usize;
    // Start a mutable cursor at the front (smallest key).
    let mut cursor = tree.front_mut();

    // Iterate until cursor is null (past the end).
    while !cursor.is_null() {
        // Get a reference to the current node
        // (API: cursor.get() -> Option<&T>)
        let do_remove = {
            let node_ref = cursor.get().expect("cursor not null but get() returned None");
            pred(node_ref)
        };

        if do_remove {
            // Remove current node. After remove(), the cursor is left pointing
            // to the successor, so we can continue without additional moves.
            cursor.remove();
            removed += 1;
        } else {
            // Advance to next node
            cursor.move_next();
        }
    }

    removed
}

fn main() {
    // Build a tree and insert some nodes
    let mut tree = RBTree::new(NodeAdapter::new());
    tree.insert(Node::new(10, "ten"));
    tree.insert(Node::new(5, "five"));
    tree.insert(Node::new(20, "twenty"));
    tree.insert(Node::new(15, "fifteen"));
    tree.insert(Node::new(25, "twenty-five"));

    // Remove nodes whose key is > 12 (only a small number in this example)
    let removed = remove_matching_small_number(&mut tree, |n| n.key > 12);
    println!("removed: {}", removed);

    // Print remaining keys
    for node in tree.iter() {
        println!("remaining: key={}, value={}", node.key, node.value);
    }
}
```

Notes and reasoning:
- Using a mutable cursor and calling cursor.remove() keeps operations local: remove is O(1) on the intrusive structure and the cursor moves to the successor automatically so you do not need to re-search the tree for the next element.
- This approach is especially efficient when only a few elements are removed because it avoids rebuilding or copying the whole tree and does only a single traversal.
- If you need to remove many elements (say a large fraction of the tree), it may be faster to build a new tree, or collect the items you want to keep and rebuild — the best strategy depends on expected removal density and memory constraints.
- If your invasive-collections version has slightly different module/macro names, adapt the adapter/macro/import lines accordingly: the core idea is the same: use a CursorMut over an RBTree and call remove() on matches.

