```rust
use linfa::prelude::*;
use linfa_cluster::KMeans;
use ndarray::Array2;

/// Partitions a one-dimensional data sequence into clusters using k-means algorithm.
///
/// # Arguments
/// * `arr0` - A slice of f64 values to be clustered
/// * `n_clusters` - The number of clusters to partition the data into
///
/// # Returns
/// A `Result` containing a vector of cluster labels (integers) for each element,
/// or an error if clustering fails.
///
/// # Example
/// ```
/// let data = vec![1.0, 2.0, 8.0, 9.0, 10.0];
/// let labels = kmeans_partition(&data, 2).unwrap();
/// assert_eq!(labels.len(), 5);
/// ```
pub fn kmeans_partition(arr0: &[f64], n_clusters: usize) -> Result<Vec<usize>, String> {
    // Validate input
    if arr0.is_empty() {
        return Err("Input array cannot be empty".to_string());
    }
    if n_clusters == 0 {
        return Err("Number of clusters must be greater than 0".to_string());
    }
    if n_clusters > arr0.len() {
        return Err("Number of clusters cannot exceed the number of elements".to_string());
    }

    // Convert 1D array to 2D format required by linfa (n_samples x n_features)
    // Each element becomes a row with 1 feature
    let data_2d = Array2::from_shape_vec(
        (arr0.len(), 1),
        arr0.to_vec(),
    )
    .map_err(|e| format!("Failed to reshape data: {}", e))?;

    // Create a DatasetBase from the array
    let dataset = DatasetBase::from(data_2d);

    // Perform k-means clustering
    let model = KMeans::fit(
        &dataset,
        n_clusters,
        Default::default(),
    )
    .map_err(|e| format!("K-means fitting failed: {}", e))?;

    // Get predictions for each data point
    let predictions = model
        .predict(&dataset)
        .to_vec();

    Ok(predictions)
}

