        .unwrap();

    // Select the rows with the maximum value in the specified column for each group
    let max_rows = grouped_df
        .apply(|group| {
            let index = max_indices.get(group.group_index()).unwrap()[0];
            group.row(index as usize).unwrap().clone()
        })
        .unwrap();

    // Create a new DataFrame from the selected rows
    DataFrame::new(max_rows)
