    let stream0 = list0.into_iter().map(|fut| async { fut.await });
    let stream1 = list1.into_iter().map(|fut| async { fut.await });

    // Combine the two streams into a single stream of pairs
    let combined = stream0.zip(stream1);

    // Process each pair in parallel
    combined.map(|(fut0, fut1)| {
        let fut0 = fut0;
        let fut1 = fut1;

        async move {
            let val0 = fut0.await;
            let val1 = fut1.await;
            val0 == val1
        }
    })
}

