```rust
use indexmap::IndexMap;

/// Which orientation to use when converting df0 into a dictionary.
#[derive(Debug, Clone, Copy)]
pub enum Orientation {
    Columns,
    Rows,
}

/// Convert a 2D dataset into an IndexMap according to `orientation`.
///
/// - df0: a slice of rows, each row is a Vec<String>. Rows may be of unequal length.
/// - If Orientation::Columns: the first row of df0 is treated as column headers.
///   Each header becomes a key and its value is a Vec<String> of the column values
///   from subsequent rows. If a row is shorter than the column index, "" is used.
/// - If Orientation::Rows: for each row, the first cell is the key (if missing, a
///   generated key "row_i" is used). The value is the remaining cells of that row.
///
/// Returns an IndexMap<String, Vec<String>> preserving insertion order.
pub fn df_to_indexmap(df0: &[Vec<String>], orientation: Orientation) -> IndexMap<String, Vec<String>> {
    let mut out: IndexMap<String, Vec<String>> = IndexMap::new();

    match orientation {
        Orientation::Columns => {
            // Need at least one row to have headers
            if df0.is_empty() {
                return out;
            }
            let headers = &df0[0];
            let n_cols = headers.len();

            for col_idx in 0..n_cols {
                // header key or fallback key
                let key = headers
                    .get(col_idx)
                    .cloned()
                    .unwrap_or_else(|| format!("col_{}", col_idx));

                let mut col_vals = Vec::with_capacity(df0.len().saturating_sub(1));
                for row_idx in 1..df0.len() {
                    let row = &df0[row_idx];
                    let cell = row.get(col_idx).cloned().unwrap_or_default();
                    col_vals.push(cell);
                }
                out.insert(key, col_vals);
            }
        }
        Orientation::Rows => {
            for (row_idx, row) in df0.iter().enumerate() {
                let key = row
                    .get(0)
                    .cloned()
                    .unwrap_or_else(|| format!("row_{}", row_idx));
                // remaining cells (may be empty)
                let vals = if row.len() > 1 {
                    row[1..].to_vec()
                } else {
                    Vec::new()
                };
                out.insert(key, vals);
            }
        }
    }

    out
}

fn main() {
    use Orientation::*;

    // Example: columns orientation
    let df_cols = vec![
        vec!["id".into(), "name".into(), "age".into()],
        vec!["1".into(), "Alice".into(), "30".into()],
        vec!["2".into(), "Bob".into(), "25".into()],
        vec!["3".into(), "Carol".into(), "27".into()],
    ];

    let by_columns = df_to_indexmap(&df_cols, Columns);
    println!("By columns:");
    for (k, v) in &by_columns {
        println!("{} -> {:?}", k, v);
    }

    // Example: rows orientation
    let df_rows = vec![
        vec!["row1".into(), "a".into(), "b".into()],
        vec!["row2".into(), "c".into()],
        vec!["row3".into()], // no additional cells
    ];

    let by_rows = df_to_indexmap(&df_rows, Rows);
    println!("\nBy rows:");
    for (k, v) in &by_rows {
        println!("{} -> {:?}", k, v);
    }
}
```

