use tokenizers_core::tokenizer::Tokenizer;
use tokenizers_core::tokenizer::PreTokenizedString;
use tokenizers_core::tokenizer::Token;
use std::collections::VecDeque;

/// Extracts `var2` words before and after `var1` in `var0`, using tokenizers-core
///
/// # Arguments
/// * `var0` - The input text to search within
/// * `var1` - The search term to find
/// * `var2` - The number of words to extract before and after the search term
///
/// # Returns
/// A tuple containing:
/// - A VecDeque of Option<Token> for words before the search term (left context)
/// - A VecDeque of Option<Token> for words after the search term (right context)
pub fn extract_context(
    var0: &str,
    var1: &str,
    var2: usize,
) -> (VecDeque<Option<Token>>, VecDeque<Option<Token>>) {
    // Create a tokenizer (using a simple whitespace tokenizer for this example)
    // In a real application, you might want to use a more sophisticated tokenizer
    let tokenizer = Tokenizer::new_from_str("whitespace").unwrap();

    // Tokenize the input text
    let tokens: Vec<Token> = tokenizer.encode(
        PreTokenizedString::new(var0),
        true,
    )
    .unwrap()
    .get_tokens()
    .iter()
    .map(|t| Token::from(t.clone()))
    .collect();

    // Tokenize the search term
    let search_tokens: Vec<Token> = tokenizer.encode(
        PreTokenizedString::new(var1),
        true,
    )
    .unwrap()
    .get_tokens()
    .iter()
    .map(|t| Token::from(t.clone()))
    .collect();

    // Find all occurrences of the search term in the text
    let mut left_contexts = Vec::new();
    let mut right_contexts = Vec::new();

    // We'll look for all possible matches of the search term
    for i in 0..=tokens.len().saturating_sub(search_tokens.len()) {
        let mut match_found = true;
        for (j, search_token) in search_tokens.iter().enumerate() {
            if i + j >= tokens.len() || tokens[i + j] != *search_token {
                match_found = false;
                break;
            }
        }

        if match_found {
            // Extract left context
            let left_start = i.saturating_sub(var2);
            let left_end = i;
            let left_tokens: Vec<Option<Token>> = tokens[left_start..left_end]
                .iter()
                .rev()
                .map(|t| Some(t.clone()))
                .collect();

            // Extract right context
            let right_start = i + search_tokens.len();
            let right_end = right_start + var2;
            let right_tokens: Vec<Option<Token>> = tokens[right_start..right_end]
                .iter()
                .map(|t| Some(t.clone()))
                .collect();

            // Pad with None if we don't have enough tokens
            let left_padded = if left_tokens.len() < var2 {
                let mut padded = VecDeque::new();
                padded.extend(left_tokens.into_iter().rev());
                padded.extend((0..var2 - left_tokens.len()).map(|_| None));
                padded
            } else {
                left_tokens.into_iter().rev().collect()
            };

            let right_padded = if right_tokens.len() < var2 {
                let mut padded = VecDeque::new();
                padded.extend(right_tokens);
                padded.extend((0..var2 - right_tokens.len()).map(|_| None));
                padded
            } else {
                right_tokens.into_iter().collect()
            };

            left_contexts.push(left_padded);
            right_contexts.push(right_padded);
        }
    }

    // Return the first match found (or empty if no match)
    if left_contexts.is_empty() {
        (VecDeque::new(), VecDeque::new())
    } else {
        (left_contexts[0].clone(), right_contexts[0].clone())
    }
}

