/// Removes rows from a DataFrame where the specified column matches a regex pattern,
/// then resets the row numbering to be sequential.
///
/// # Arguments
/// * `df0` - The input DataFrame to filter
/// * `var0` - The name of the column to check against the regex pattern
/// * `var1` - The regex pattern string to match against column values
///
/// # Returns
/// * `Result<DataFrame, Box<dyn std::error::Error>>` - The filtered DataFrame with sequential row numbers
///
/// # Example
/// ```rust
/// use dataforge_rs::prelude::*;
/// 
/// // Create a sample DataFrame
/// let df = DataFrame::from_rows(&[
///     row!{"id" => 1, "name" => "apple"},
///     row!{"id" => 2, "name" => "banana"},
///     row!{"id" => 3, "name" => "apricot"},
/// ]).unwrap();
/// 
/// // Remove rows where "name" matches regex "a.*e" (ends with 'e')
/// let result = remove_rows_matching_regex(df, "name", "a.*e").unwrap();
/// // Result will contain only "banana" row with sequential numbering
/// ```
pub fn remove_rows_matching_regex(
    df0: DataFrame,
    var0: &str,
    var1: &str,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Compile the regex pattern
    let regex = Regex::new(var1)?;

    // Get the column index for the specified column name
    let col_index = df0
        .columns()
        .iter()
        .position(|col| col.name() == var0)
        .ok_or_else(|| format!("Column '{}' not found in DataFrame", var0))?;

    // Filter rows: keep only those where the column value does NOT match the regex
    let filtered_df = df0
        .iter_rows()
        .enumerate()
        .filter(|(_, row)| {
            let value = row.get(col_index).unwrap();
            let value_str = value.to_string();
            !regex.is_match(&value_str)
        })
        .map(|(_, row)| row.clone())
        .collect::<Vec<_>>();

    // Create a new DataFrame from the filtered rows
    let mut result_df = DataFrame::from_rows(&filtered_df)?;

    // Reset row numbering (add a sequential index column)
    let row_count = result_df.nrows();
    let indices: Vec<i64> = (0..row_count as i64).collect();
    result_df = result_df.with_column(
        Column::from("row_number", indices)
    )?;

    Ok(result_df)
}

