use bimapper::Mapper;
use std::collections::HashMap;

/// Maps each unique category in a column to integer codes and replaces original values
/// 
/// # Arguments
/// * `df0` - A Vec<Vec<String>> representing the data table
/// * `col0` - The column index to map
/// 
/// # Returns
/// A tuple containing:
/// - Modified data table with mapped integer codes
/// - HashMap showing the mapping of categories to codes
fn map_categories_to_codes(
    df0: &mut Vec<Vec<String>>,
    col0: usize,
) -> (Vec<Vec<String>>, HashMap<String, i32>) {
    let mut mapper: Mapper<String, i32> = Mapper::new();
    let mut mapping = HashMap::new();
    let mut next_code: i32 = 0;

    // First pass: identify unique categories and create mappings
    for row in df0.iter() {
        if col0 < row.len() {
            let category = row[col0].clone();

            // Only add if not already mapped
            if !mapping.contains_key(&category) {
                mapper.insert(category.clone(), next_code);
                mapping.insert(category, next_code);
                next_code += 1;
            }
        }
    }

    // Second pass: replace original values with numeric codes
    let mut result = df0.clone();
    for row in result.iter_mut() {
        if col0 < row.len() {
            let category = &row[col0];
            if let Some(&code) = mapping.get(category) {
                row[col0] = code.to_string();
            }
        }
    }

    (result, mapping)
}

